 body: JSON.stringify({ chat_id, text: msg, parse_mode: 'Markdown' })\\n    });\\n  } catch(e) {}\\n}\\nreturn [{ json: { thanh_cong: true, ma_tai_san: d.ma_tai_san } }];\\n","notice":""},"id":"4085f70e-c2a1-4e1a-b84a-58fca33ac0b2","name":"Bao_Hoc_Xong_Telegram1","type":"n8n-nodes-base.code","typeVersion":2,"position":[7248,1344]}],"connections":{"Kich_Hoat_Ho_So_Vao":{"main":[[{"node":"Tien_Kiem_Tra_Ho_So","type":"main","index":0}]]},"Kiem_Tra_Trang_Thai_Sheet":{"main":[[{"node":"IF_Da_Phe_Duyet","type":"main","index":0}]]},"IF_Da_Phe_Duyet":{"main":[[{"node":"Tai_Prompt_Quy_Tac_Drive","type":"main","index":0}],[{"node":"Chuyen_File_Loi_Va_Alert","type":"main","index":0}]]},"Tai_Prompt_Quy_Tac_Drive":{"main":[[{"node":"Tai_File_Ho_So_Khach","type":"main","index":0}]]},"Tai_File_Ho_So_Khach":{"main":[[{"node":"Gemini_Extract_Du_Lieu","type":"main","index":0}]]},"Gemini_Extract_Du_Lieu":{"main":[[{"node":"Kiem_Dinh_Validator_JS","type":"main","index":0}]]},"Kiem_Dinh_Validator_JS":{"main":[[{"node":"Luu_File_JSON_Drive","type":"main","index":0}]]},"Luu_File_JSON_Drive":{"main":[[{"node":"Ghi_Log_Sheets_Van_Hanh","type":"main","index":0}]]},"Ghi_Log_Sheets_Van_Hanh":{"main":[[{"node":"Bao_Ket_Qua_Telegram","type":"main","index":0}]]},"Kich_Hoat_Yeu_Cau_Duyet":{"main":[[{"node":"Kiem_Thu_Hoi_Quy_Dice","type":"main","index":0}]]},"Kiem_Thu_Hoi_Quy_Dice":{"main":[[{"node":"Cap_Nhat_Trang_Thai_Duyet","type":"main","index":0}]]},"Cap_Nhat_Trang_Thai_Duyet":{"main":[[{"node":"Bao_Duyet_Telegram","type":"main","index":0}]]},"Tien_Kiem_Tra_Ho_So":{"main":[[{"node":"Kiem_Tra_Trang_Thai_Sheet","type":"main","index":0}]]},"Phan_Tich_Ten_File":{"main":[[{"node":"Tai_Noi_Dung_File_Drive","type":"main","index":0}]]},"Tai_Noi_Dung_File_Drive":{"main":[[{"node":"AI_Prep_Gemini_Body","type":"main","index":0}]]},"AI_Prep_Gemini_Body":{"main":[[{"node":"Gemini_Phan_Tich_Mau1","type":"main","index":0}]]},"Xu_Ly_Data_Output":{"main":[[{"node":"Bao_Hoc_Xong_Telegram1","type":"main","index"