46	{"id":"Kw0nqux4dOo1kdnP","name":"WF01_DYNAMIC_AI_ONBOARDING_STANDARD","nodes":[{"parameters":{"pollTimes":{"item":[{"mode":"everyMinute"}]},"authentication":"oAuth2","triggerOn":"specificFolder","folderToWatch":{"__rl":true,"value":"13LfY46PZMDQG8WWRTnwaR7JUTG6P7crF","mode":"id"},"event":"fileCreated","asas":"","options":{}},"id":"606dd836-5522-4678-9836-1c369a942092","name":"Kich_Hoat_Ho_So_Vao","type":"n8n-nodes-base.googleDriveTrigger","typeVersion":1,"position":[6032,1824],"credentials":{"googleDriveOAuth2Api":{"id":"rTUSZlOSjhGVDCDG","name":"Google Drive account LETRUNG80.HUE"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst payload = $json;\\nconst file_id = payload.id || '';\\nconst ten_file = payload.name || '';\\nconst mime_type = payload.mimeType || '';\\nconst size = parseInt(payload.size || '0', 10);\\nconst now_str = new Date().toISOString();\\n\\nconst ma_thuc_thi = `thuc_thi_${now_str.replace(/[-:T.Z]/g, '').substring(0, 15)}_${Math.floor(Math.random() * 9000 + 1000)}`;\\nconst thoi_gian_bat_dau = Date.now();\\n\\nconsole.log('[WF02-PreCheck] Tiếp nhận hồ sơ: ' + ten_file);\\n\\nlet hop_le = true;\\nlet ly_do = '';\\n\\nif (size === 0) {\\n  hop_le = false;\\n  ly_do = 'Tệp rỗng (0 byte).';\\n} else if (size > 20 * 1024 * 1024) {\\n  hop_le = false;\\n  ly_do = 'Tệp vượt kích thước tối đa 20MB.';\\n} else if (!['application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'image/png', 'image/jpeg'].includes(mime_type)) {\\n  hop_le = false;\\n  ly_do = 'Định dạng không được hỗ trợ. Chỉ nhận PDF, DOCX, PNG, JPG.';\\n}\\n\\nconst ten_khong_duoi = ten_file.replace(/\\\\.[^.]+$/, '');\\nconst vi_tri = ten_khong_duoi.indexOf('__');\\nlet ma_tai_san = '';\\nif (vi_tri === -1) {\\n  hop_le = false;\\n  ly_do = 'Tên file không đúng định dạng <ma_tai_san>__<ten>.pdf';\\n} else {\\n  ma_tai_san = ten_khong_duoi.substring(0, vi_tri);\\n}\\n\\nreturn [{ json: {\\n  ma_thuc_thi, file_id, ten_file, mime_type, size, ma_tai_san, hop_le, ly_do, ten_khong_duoi, thoi_gian_bat_dau\\n} }];\\n","notice":""},"id":"e2b75cc0-9ab2-4fe9-b3ed-aa607e942209","name":"Tien_Kiem_Tra_Ho_So","type":"n8n-nodes-base.code","typeVersion":2,"position":[6240,1824]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst d = $json;\\nif (!d.hop_le) return [{ json: d }];\\n\\nconst sid = $env.GOOGLE_SHEETS_SPREADSHEET_ID || '';\\n\\nconsole.log('[WF02-ReadSheet] Tra cứu trạng thái phê duyệt cho: ' + d.ma_tai_san);\\n\\n// 1. Tra cứu Trang_Thai_Van_Hanh\\nconst res_tt = await $helpers.httpRequest({\\n  method: 'GET',\\n  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Trang_Thai_Van_Hanh!A2:F`,\\n  authentication: 'predefinedCredentialType',\\n  nodeCredentialType: 'googleSheetsOAuth2Api',\\n});\\nconst rows_tt = res_tt.values || [];\\nconst cau_hinh_duyet = rows_tt.find(r => r[0] === d.ma_tai_san && r[2] === 'van_hanh' && r[3] === 'DA_CONG_BO');\\n\\nif (!cau_hinh_duyet) {\\n  return [{ json: { ...d, hop_le: false, ly_do: `Mẫu tài sản '${d.ma_tai_san}' chưa được duyệt (DA_CONG_BO) hoặc chưa tồn tại.` } }];\\n}\\nconst phien_ban = cau_hinh_duyet[1];\\n\\n// 2. Tra cứu Dang_Ky_Tai_San lấy SHA256 chuẩn\\nconst res_dk = await $helpers.httpRequest({\\n  method: 'GET',\\n  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Dang_Ky_Tai_San!A2:F`,\\n  authentication: 'predefinedCredentialType',\\n  nodeCredentialType: 'googleSheetsOAuth2Api',\\n});\\nconst rows_dk = res_dk.values || [];\\nconst dong_dk = rows_dk.find(r => r[0] === d.ma_tai_san && r[1] === phien_ban);\\n\\nif (!dong_dk) {\\n  return [{ json: { ...d, hop_le: false, ly_do: `Lỗi cơ sở dữ liệu: Không thấy bản ghi đăng ký cho ${d.ma_tai_san} v${phien_ban}.` } }];\\n}\\n\\nreturn [{ json: {\\n  ...d,\\n  phien_ban,\\n  duong_dan_quy_tac: dong_dk[2],\\n  sha256_chuan: dong_dk[3]\\n} }];\\n","notice":""},"id":"427579f4-0a4a-4169-b231-be32ff464170","name":"Kiem_Tra_Trang_Thai_Sheet","type":"n8n-nodes-base.code","typeVersion":2,"position":[6432,1824]},{"parameters":{"conditions":{"boolean":[{"value1":"={{ $json.hop_le }}","operation":"equal","value2":true}]},"combineOperation":"all"},"id":"3ed0672a-aedb-4d1a-9125-25b2bb822473","name":"IF_Da_Phe_Duyet","type":"n8n-nodes-base.if","typeVersion":1,"position":[6640,1824]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst d = $json;\\nconst file_id = d.file_id;\\n\\n// Tìm thư mục Loi_Dinh_Dang\\nconst url_folder = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(\\"name = 'Loi_Dinh_Dang' and mimeType = 'application/vnd.google-apps.folder' and trashed = false\\")}&fields=files(id)`;\\nconst res_folder = await $helpers.httpRequest({\\n  method: 'GET',\\n  url: url_folder,\\n  authentication: 'predefinedCredentialType',\\n  nodeCredentialType: 'googleDriveOAuth2Api',\\n});\\nconst folders = res_folder.files || [];\\nif (folders.length > 0) {\\n  const folder_id = folders[0].id;\\n  const url_file = `https://www.googleapis.com/drive/v3/files/${file_id}?fields=parents`;\\n  const file_metadata = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: url_file,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n  const current_parents = (file_metadata.parents || []).join(',');\\n  await $helpers.httpRequest({\\n    method: 'PATCH',\\n    url: `https://www.googleapis.com/drive/v3/files/${file_id}?addParents=${folder_id}&removeParents=${current_parents}`,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n}\\n\\n// Ghi log lỗi vào Nhat_Ky_Van_Hanh\\nconst sid = $env.GOOGLE_SHEETS_SPREADSHEET_ID || '';\\nconst hang_log = [d.ma_thuc_thi, d.ma_tai_san || 'N/A', 'N/A', '0', '0', 'TU_CHOI_TU_DAU', d.ly_do];\\nawait $helpers.httpRequest({\\n  method: 'POST',\\n  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Nhat_Ky_Van_Hanh!A1:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`,\\n  authentication: 'predefinedCredentialType',\\n  nodeCredentialType: 'googleSheetsOAuth2Api',\\n  body: { values: [hang_log] }\\n});\\n\\n// Telegram cảnh báo\\nconst bot_token = $env.TELEGRAM_BOT_TOKEN;\\nconst chat_id = $env.TELEGRAM_CHAT_ID;\\nif (bot_token && chat_id) {\\n  const msg = `🚨 *HỒ SƠ BỊ TỪ CHỐI*\\\\n\\\\n📄 File: \\\\`${d.ten_file}\\\\`\\\\n⚠️ Lý do: ${d.ly_do}\\\\n🔖 Mã TT: \\\\`${d.ma_thuc_thi}\\\\`\\\\n\\\\n_Tệp đã được di chuyển sang thư mục Loi_Dinh_Dang_`;\\n  try {\\n    await $helpers.httpRequest({\\n      method: 'POST',\\n      url: `https://api.telegram.org/bot${bot_token}/sendMessage`,\\n      body: { chat_id, text: msg, parse_mode: 'Markdown' }\\n    });\\n  } catch(e) {}\\n}\\n\\nreturn [{ json: { status: 'moved_to_error', ma_thuc_thi: d.ma_thuc_thi } }];\\n","notice":""},"id":"9f62779d-4a83-4226-9dc4-5672891a2487","name":"Chuyen_File_Loi_Va_Alert","type":"n8n-nodes-base.code","typeVersion":2,"position":[6832,1952]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nasync function _tim_file_id_tu_ten_file(ten_file) {\\n  const url = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(\\"name = '\\" + ten_file + \\"' and trashed = false\\")}&fields=files(id)`;\\n  const phan_hoi = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: url,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n  const files = phan_hoi.files || [];\\n  if (files.length === 0) throw new Error(\\"Không thấy file \\" + ten_file);\\n  return files[0].id;\\n}\\n\\nasync function _tai_noi_dung_drive(file_id) {\\n  const phan_hoi = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: `https://www.googleapis.com/drive/v3/files/${file_id}?alt=media`,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n  return typeof phan_hoi === 'string' ? phan_hoi : JSON.stringify(phan_hoi);\\n}\\n\\nconst d = $json;\\nconsole.log('[WF02-LoadConfig] Tải cấu hình AI & xác thực SHA256 cho: ' + d.ma_tai_san);\\n\\nconst ten_file_quy_tac = `quy_tac_${d.ma_tai_san}_v3.json`;\\nconst file_id_quy_tac = await _tim_file_id_tu_ten_file(ten_file_quy_tac);\\nconst noi_dung_quy_tac = await _tai_noi_dung_drive(file_id_quy_tac);\\n\\nconst { createHash } = require('crypto');\\nconst sha256_thuc_te = createHash('sha256').update(noi_dung_quy_tac, 'utf8').digest('hex');\\n\\nif (sha256_thuc_te !== d.sha256_chuan) {\\n  const bot_token = $env.TELEGRAM_BOT_TOKEN;\\n  const chat_id = $env.TELEGRAM_CHAT_ID;\\n  if (bot_token && chat_id) {\\n    const msg = `🚨 *VI PHẠM TOÀN VẸN CẤU HÌNH*\\\\n\\\\nTài sản: \\\\`${d.ma_tai_san}\\\\` @ vsub{d.phien_ban}\\\\nFile bị sửa: \\\\`${ten_file_quy_tac}\\\\`\\\\n\\\\n⛔ Ngắt luồng khẩn cấp.`.replace('sub', '');\\n    await $helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot_token}/sendMessage`, body: { chat_id, text: msg, parse_mode: 'Markdown' } });\\n  }\\n  throw new Error(\\"Lỗi an ninh: File cấu hình bị chỉnh sửa trái phép!\\");\\n}\\n\\nconst ten_file_prompt = `cau_hinh_${d.ma_tai_san}_v4.txt`;\\nconst file_id_prompt = await _tim_file_id_tu_ten_file(ten_file_prompt);\\nconst noi_dung_prompt = await _tai_noi_dung_drive(file_id_prompt);\\n\\nreturn [{ json: {\\n  ...d,\\n  prompt_ai: noi_dung_prompt,\\n  quy_tac_obj: JSON.parse(noi_dung_quy_tac)\\n} }];\\n","notice":""},"id":"b253c9cc-fcae-442d-b67d-642e00a0b21b","name":"Tai_Prompt_Quy_Tac_Drive","type":"n8n-nodes-base.code","typeVersion":2,"position":[6832,1712]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst d = $json;\\nconst file_id = d.file_id;\\nconst mime_type = d.mime_type;\\n\\nconsole.log('[WF02-ReadHoSo] Tải hồ sơ khách hàng...');\\n\\nconst LOAI_DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';\\nlet noi_dung_cho_ai;\\nlet phuong_phap;\\nlet mime_gui_gemini;\\n\\nif (mime_type === LOAI_DOCX) {\\n  const url_export = `https://www.googleapis.com/drive/v3/files/${file_id}/export?mimeType=text%2Fplain`;\\n  const van_ban = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: url_export,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n  noi_dung_cho_ai = typeof van_ban === 'string' ? van_ban : JSON.stringify(van_ban);\\n  phuong_phap = 'text';\\n  mime_gui_gemini = 'text/plain';\\n} else {\\n  const url_dl = `https://www.googleapis.com/drive/v3/files/${file_id}?alt=media`;\\n  const res_bin = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: url_dl,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n    encoding: 'arraybuffer',\\n    returnFullResponse: true,\\n  });\\n  const buffer = Buffer.from(res_bin.body);\\n  noi_dung_cho_ai = buffer.toString('base64');\\n  phuong_phap = 'multimodal';\\n  mime_gui_gemini = mime_type;\\n}\\n\\nlet parts = [];\\nif (phuong_phap === 'text') {\\n  parts.push({ text: `${d.prompt_ai}\\\\n\\\\n=== NỘI DUNG TÀI LIỆU ===\\\\n${noi_dung_cho_ai.slice(0, 32000)}` });\\n} else {\\n  parts.push({ text: d.prompt_ai });\\n  parts.push({ inlineData: { mimeType: mime_gui_gemini, data: noi_dung_cho_ai } });\\n}\\n\\nconst gemini_body = {\\n  contents: [{ parts }],\\n  generationConfig: { temperature: 0.0, responseMimeType: 'application/json' }\\n};\\n\\nreturn [{ json: {\\n  ...d,\\n  gemini_body\\n} }];\\n","notice":""},"id":"3b4fe03d-914f-4d35-ab50-d70304b5e83b","name":"Tai_File_Ho_So_Khach","type":"n8n-nodes-base.code","typeVersion":2,"position":[7040,1712]},{"parameters":{"curlImport":"","method":"POST","url":"=https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key={{$env.GEMINI_API_KEY}}","authentication":"none","provideSslCertificates":false,"sendQuery":false,"sendHeaders":false,"sendBody":true,"contentType":"json","specifyBody":"json","jsonBody":"={{ JSON.stringify($json.gemini_body) }}","options":{"timeout":120000},"infoMessage":""},"id":"02fbdc56-be6b-4d28-999a-d548ae1de0e5","name":"Gemini_Extract_Du_Lieu","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[7232,1712]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nfunction chuanHoaNgayThang(chuoi_ngay) {\\n  if (!chuoi_ngay) return null;\\n  const cleaned = chuoi_ngay.trim().replace(/[\\\\/\\\\.]/g, '-');\\n  const r_iso = /^\\\\d{4}-\\\\d{2}-\\\\d{2}$/;\\n  if (r_iso.test(cleaned)) return cleaned;\\n  const r_vn = /^(\\\\d{1,2})-(\\\\d{1,2})-(\\\\d{4})$/;\\n  const match = cleaned.match(r_vn);\\n  if (match) {\\n    return `${match[3]}-${match[2].padStart(2, '0')}-${match[1].padStart(2, '0')}`;\\n  }\\n  return chuoi_ngay;\\n}\\n\\nfunction chuanHoaTienTe(chuoi_tien) {\\n  if (chuoi_tien === null || chuoi_tien === undefined) return null;\\n  if (typeof chuoi_tien === 'number') return Math.round(chuoi_tien);\\n  const cleaned = chuoi_tien.toString().replace(/[^0-9\\\\-]/g, '');\\n  const parsed = parseInt(cleaned, 10);\\n  return isNaN(parsed) ? null : parsed;\\n}\\n\\nfunction kiemTraDuLieu(du_lieu_trich_xuat, quy_tac_json) {\\n  const chi_tiet = {};\\n  let so_truong_dat = 0;\\n  let tong_truong = 0;\\n  const du_lieu_da_chuan_hoa = {};\\n  const ds_quy_tac = quy_tac_json.quy_tac_truong || {};\\n\\n  for (const ten_truong in ds_quy_tac) {\\n    tong_truong++;\\n    const rule = ds_quy_tac[ten_truong];\\n    let val = du_lieu_trich_xuat[ten_truong];\\n    let hop_le = true;\\n    let ghi_chu = '';\\n\\n    if (val !== null && val !== undefined) {\\n      if (rule.kieu === 'date') {\\n        const truoc = val;\\n        val = chuanHoaNgayThang(val);\\n        if (val !== truoc) ghi_chu = `Chuẩn hóa ngày: ${truoc} -> ${val}`;\\n      } else if (rule.kieu === 'currency') {\\n        const truoc = val;\\n        val = chuanHoaTienTe(val);\\n        if (val !== truoc) ghi_chu = `Chuẩn hóa tiền: ${truoc} -> ${val}`;\\n      }\\n    }\\n    du_lieu_da_chuan_hoa[ten_truong] = val;\\n    if (rule.bat_buoc && (val === null || val === undefined || val === '')) {\\n      hop_le = false;\\n      ghi_chu = 'Trường bắt buộc nhưng không tìm thấy.';\\n    }\\n    if (hop_le) so_truong_dat++;\\n    chi_tiet[ten_truong] = { hop_le, ghi_chu, gia_tri: val };\\n  }\\n  const ti_le_dat = tong_truong > 0 ? so_truong_dat / tong_truong : 1.0;\\n  return {\\n    hop_le: ti_le_dat >= 0.8,\\n    ti_le_dat,\\n    so_truong_dat,\\n    tong_truong,\\n    chi_tiet,\\n    du_lieu_da_chuan_hoa\\n  };\\n}\\n\\nconst d = $('Tai_File_Ho_So_Khach').first().json;\\nconst api_text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';\\nconsole.log('[WF02-Validator] Chạy kiểm định dữ liệu...');\\n\\nlet du_lieu_trich_xuat;\\ntry {\\n  du_lieu_trich_xuat = JSON.parse(api_text);\\n} catch(e) {\\n  throw new Error(\\"Gemini trả về không phải JSON: \\" + api_text.slice(0, 100));\\n}\\n\\nconst bao_cao = kiemTraDuLieu(du_lieu_trich_xuat, d.quy_tac_obj);\\nconst token_meta = $json.usageMetadata || {};\\n\\nreturn [{ json: {\\n  ...d,\\n  ket_qua_trich_xuat: bao_cao.du_lieu_da_chuan_hoa,\\n  bao_cao_kiem_tra: {\\n    hop_le: bao_cao.hop_le,\\n    ti_le_dat: bao_cao.ti_le_dat,\\n    so_truong_dat: bao_cao.so_truong_dat,\\n    tong_truong: bao_cao.tong_truong,\\n  },\\n  tokens: token_meta.totalTokenCount || 0\\n} }];\\n","notice":""},"id":"bc3a0cbd-0fa8-4740-861d-6660a8f0fc90","name":"Kiem_Dinh_Validator_JS","type":"n8n-nodes-base.code","typeVersion":2,"position":[7440,1712]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nasync function _luu_ket_qua_drive(ten_file, du_lieu_obj) {\\n  const url_folder = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(\\"name = '03_Ket_Qua_Xu_Ly' and mimeType = 'application/vnd.google-apps.folder' and trashed = false\\")}&fields=files(id)`;\\n  const res_folder = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: url_folder,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n  const folders = res_folder.files || [];\\n  if (folders.length === 0) throw new Error(\\"Không thấy thư mục 03_Ket_Qua_Xu_Ly\\");\\n  const folder_id = folders[0].id;\\n\\n  const metadata = { name: ten_file, parents: [folder_id], mimeType: 'application/json' };\\n  const boundary = '-------314159265358979323846';\\n  const delimiter = `\\\\r\\\\n--${boundary}\\\\r\\\\n`;\\n  const close_delim = `\\\\r\\\\n--${boundary}--`;\\n  const metadata_part = `Content-Type: application/json; charset=UTF-8\\\\r\\\\n\\\\r\\\\n${JSON.stringify(metadata)}`;\\n  const media_part = `Content-Type: application/json\\\\r\\\\n\\\\r\\\\n${JSON.stringify(du_lieu_obj, null, 2)}`;\\n  const multipart_body = `${delimiter}${metadata_part}${delimiter}${media_part}${close_delim}`;\\n\\n  await $helpers.httpRequest({\\n    method: 'POST',\\n    url: 'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart',\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n    headers: { 'Content-Type': `multipart/related; boundary=${boundary}` },\\n    body: multipart_body\\n  });\\n}\\n\\nconst d = $json;\\nconst ten_kq = `ket_qua_${d.ma_thuc_thi}_${d.ten_khong_duoi}.json`;\\nconsole.log('[WF02-SaveResult] Ghi kết quả vào Drive: ' + ten_kq);\\n\\nawait _luu_ket_qua_drive(ten_kq, d.ket_qua_trich_xuat);\\nreturn [{ json: d }];\\n","notice":""},"id":"c7b24192-c118-41fc-98d6-e4a22141d9df","name":"Luu_File_JSON_Drive","type":"n8n-nodes-base.code","typeVersion":2,"position":[7632,1712]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst d = $json;\\nconst sid = $env.GOOGLE_SHEETS_SPREADSHEET_ID || '';\\nconst now_str = new Date().toISOString();\\n\\nconsole.log('[WF02-WriteLog] Ghi log Sheets Nhat_Ky_Van_Hanh...');\\n\\nconst thoi_gian_chay_ms = Date.now() - (d.thoi_gian_bat_dau || Date.now());\\n\\nconst hang_nhat_ky = [\\n  d.ma_thuc_thi,\\n  d.ma_tai_san,\\n  d.phien_ban,\\n  String(thoi_gian_chay_ms),\\n  String(d.tokens),\\n  d.bao_cao_kiem_tra.hop_le ? 'THANH_CONG' : 'KHONG_DAT_YEU_CAU',\\n  d.bao_cao_kiem_tra.hop_le ? '' : `Kiểm định chỉ đạt ${(d.bao_cao_kiem_tra.ti_le_dat * 100).toFixed(0)}%.`\\n];\\n\\nawait $helpers.httpRequest({\\n  method: 'POST',\\n  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Nhat_Ky_Van_Hanh!A1:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`,\\n  authentication: 'predefinedCredentialType',\\n  nodeCredentialType: 'googleSheetsOAuth2Api',\\n  body: { values: [hang_nhat_ky] }\\n});\\n\\nreturn [{ json: d }];\\n","notice":""},"id":"cd5231b3-788b-4a6d-9150-755a35dc0e27","name":"Ghi_Log_Sheets_Van_Hanh","type":"n8n-nodes-base.code","typeVersion":2,"position":[7840,1712]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst d = $json;\\nconst bot_token = $env.TELEGRAM_BOT_TOKEN;\\nconst chat_id = $env.TELEGRAM_CHAT_ID;\\n\\nif (bot_token && chat_id) {\\n  const icon = d.bao_cao_kiem_tra.hop_le ? '🟢' : '🔴';\\n  const msg = \\n    '✅ *XỬ LÝ HỒ SƠ HOÀN THÀNH*\\\\n\\\\n' +\\n    '📄 File: `' + d.ten_file + '`\\\\n' +\\n    '🏷️ Tài sản: `' + d.ma_tai_san + '` @ v' + d.phien_ban + '\\\\n' +\\n    icon + ' Kết quả kiểm định: *' + (d.bao_cao_kiem_tra.hop_le ? 'ĐẠT' : 'KHÔNG ĐẠT') + '* (' + d.bao_cao_kiem_tra.so_truong_dat + '/' + d.bao_cao_kiem_tra.tong_truong + ' trường, ' + (d.bao_cao_kiem_tra.ti_le_dat * 100).toFixed(0) + '%)\\\\n' +\\n    '🔢 Token: ' + d.tokens + '\\\\n' +\\n    '🔖 Mã TT: `' + d.ma_thuc_thi + '`';\\n  try {\\n    await $helpers.httpRequest({\\n      method: 'POST',\\n      url: 'https://api.telegram.org/bot' + bot_token + '/sendMessage',\\n      body: { chat_id, text: msg, parse_mode: 'Markdown' }\\n    });\\n  } catch(e) {}\\n}\\nreturn [{ json: { thanh_cong: true } }];\\n","notice":""},"id":"6f092b36-1f49-425d-86d2-3dc0ef144d40","name":"Bao_Ket_Qua_Telegram","type":"n8n-nodes-base.code","typeVersion":2,"position":[8032,1712]},{"parameters":{"pollTimes":{"item":[{"mode":"everyMinute"}]},"authentication":"triggerOAuth2","documentId":{"__rl":true,"value":"1p4GTkH5IFU10YyEHApLlag-Z-ebPdngNUJJzztTbEyw","mode":"id"},"sheetName":"Yeu_Cau_Quan_Tri","event":"rowAdded","options":{}},"id":"8103f361-1d1e-4177-a125-1e2779b0cd8e","name":"Kich_Hoat_Yeu_Cau_Duyet","type":"n8n-nodes-base.googleSheetsTrigger","typeVersion":1,"position":[6032,2224],"credentials":{"googleSheetsTriggerOAuth2Api":{"id":"iR8G5o9pG8wwHMMg","name":"Google Sheets Trigger account LETRUNG80.HUE"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nfunction _tinh_do_tuong_dong(a, b) {\\n  if (!a && !b) return 1;\\n  if (!a || !b) return 0;\\n  if (a === b) return 1;\\n  const ca = String(a).toLowerCase().trim();\\n  const cb = String(b).toLowerCase().trim();\\n  if (ca === cb) return 1;\\n\\n  const b_a = new Set();\\n  for (let i = 0; i < ca.length - 1; i++) b_a.add(ca.slice(i, i + 2));\\n  const b_b = new Set();\\n  for (let i = 0; i < cb.length - 1; i++) b_b.add(cb.slice(i, i + 2));\\n  let giao = 0;\\n  b_a.forEach(bg => { if (b_b.has(bg)) giao++; });\\n  return (2 * giao) / (b_a.size + b_b.size);\\n}\\n\\nfunction soSanhDoiTuong(ai_obj, golden_obj) {\\n  let ok = 0;\\n  const keys = Object.keys(golden_obj);\\n  for (const k of keys) {\\n    if (ai_obj[k] === golden_obj[k] || _tinh_do_tuong_dong(ai_obj[k], golden_obj[k]) >= 0.90) ok++;\\n  }\\n  return keys.length > 0 ? ok / keys.length : 1.0;\\n}\\n\\nasync function _tim_file_id_tu_ten_file(ten_file) {\\n  const url = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(\\"name = '\\" + ten_file + \\"' and trashed = false\\")}&fields=files(id)`;\\n  const phan_hoi = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: url,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n  const files = phan_hoi.files || [];\\n  if (files.length === 0) throw new Error(\\"Không thấy file \\" + ten_file);\\n  return files[0].id;\\n}\\n\\nasync function _tai_noi_dung_drive(file_id) {\\n  const phan_hoi = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: `https://www.googleapis.com/drive/v3/files/${file_id}?alt=media`,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n  return typeof phan_hoi === 'string' ? phan_hoi : JSON.stringify(phan_hoi);\\n}\\n\\nconst input_row = $json;\\nconst dong_yeu_cau = {\\n  hanh_dong: input_row['hanh_dong'] || input_row['Hành động'] || '',\\n  ma_tai_san: input_row['ma_tai_san'] || input_row['Mã tài sản'] || '',\\n  phien_ban: input_row['phien_ban'] || input_row['Phiên bản'] || '',\\n  moi_truong: input_row['moi_truong'] || input_row['Môi trường'] || 'van_hanh',\\n  nguoi_thuc_hien: input_row['nguoi_thuc_hien'] || input_row['Người thực hiện'] || 'admin',\\n};\\n\\nif (!dong_yeu_cau.hanh_dong || !dong_yeu_cau.ma_tai_san) {\\n  return [{ json: { status: 'skipped', message: 'Dòng trống.' } }];\\n}\\n\\nconsole.log('[WF03-Approval] Bắt đầu duyệt yêu cầu...');\\n\\nconst sid = $env.GOOGLE_SHEETS_SPREADSHEET_ID || '';\\nconst res_sheet_dk = await $helpers.httpRequest({\\n  method: 'GET',\\n  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Dang_Ky_Tai_San!A2:F`,\\n  authentication: 'predefinedCredentialType',\\n  nodeCredentialType: 'googleSheetsOAuth2Api',\\n});\\nconst rows_dk = res_sheet_dk.values || [];\\nconst da_dang_ky = rows_dk.some(r => r[0] === dong_yeu_cau.ma_tai_san && r[1] === dong_yeu_cau.phien_ban);\\nif (!da_dang_ky) {\\n  throw new Error(\\"Phiên bản chưa đăng ký trong Dang_Ky_Tai_San!\\");\\n}\\n\\nlet test_ok = true;\\nlet ti_le_trung_binh = 1.0;\\nlet co_bo_vang = false;\\n\\nif (dong_yeu_cau.hanh_dong === 'CONG_BO_PHIEN_BAN') {\\n  const ten_bo_vang = `bo_du_lieu_vang_${dong_yeu_cau.ma_tai_san}_v${dong_yeu_cau.phien_ban.split('.')[0]}.json`;\\n  let file_id_vang;\\n  try {\\n    file_id_vang = await _tim_file_id_tu_ten_file(ten_bo_vang);\\n    co_bo_vang = true;\\n  } catch(e) {}\\n\\n  if (co_bo_vang && file_id_vang) {\\n    const noi_dung_vang = await _tai_noi_dung_drive(file_id_vang);\\n    const bo_vang = JSON.parse(noi_dung_vang);\\n    const mau_tests = bo_vang.mau_kiem_thu || [];\\n\\n    const ten_prompt = `cau_hinh_${dong_yeu_cau.ma_tai_san}_v4.txt`;\\n    const file_id_prompt = await _tim_file_id_tu_ten_file(ten_prompt);\\n    const prompt = await _tai_noi_dung_drive(file_id_prompt);\\n    const api_key = $env.GEMINI_API_KEY;\\n\\n    let tong = 0;\\n    for (const test_case of mau_tests) {\\n      const f_id = await _tim_file_id_tu_ten_file(test_case.ten_tap_tin);\\n      const res_bin = await $helpers.httpRequest({\\n        method: 'GET', url: `https://www.googleapis.com/drive/v3/files/${f_id}?alt=media`,\\n        authentication: 'predefinedCredentialType', nodeCredentialType: 'googleDriveOAuth2Api',\\n        encoding: 'arraybuffer', returnFullResponse: true\\n      });\\n      const b64 = Buffer.from(res_bin.body).toString('base64');\\n      const res_ai = await $helpers.httpRequest({\\n        method: 'POST', url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${api_key}`,\\n        body: { contents: [{ parts: [{ text: prompt }, { inlineData: { mimeType: 'application/pdf', data: b64 } }] }], generationConfig: { temperature: 0.0, responseMimeType: 'application/json' } }\\n      });\\n      const ai_data = JSON.parse(res_ai?.candidates?.[0]?.content?.parts?.[0]?.text || '{}');\\n      tong += soSanhDoiTuong(ai_data, test_case.ket_qua_chuan);\\n    }\\n    ti_le_trung_binh = mau_tests.length > 0 ? tong / mau_tests.length : 1.0;\\n    test_ok = ti_le_trung_binh >= 0.95;\\n  }\\n}\\n\\nif (!test_ok) {\\n  const bot_token = $env.TELEGRAM_BOT_TOKEN;\\n  const chat_id = $env.TELEGRAM_CHAT_ID;\\n  if (bot_token && chat_id) {\\n    const msg = `🚨 *CHẶN PUBLISH TÀI SẢN*\\\\n\\\\nTài sản: \\\\`${dong_yeu_cau.ma_tai_san}\\\\` @ v${dong_yeu_cau.phien_ban}\\\\n❌ Tỉ lệ chính xác Regression Test: *${(ti_le_trung_binh*100).toFixed(1)}%*\\\\n\\\\n⛔ Thất bại.`;\\n    await $helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${bot_token}/sendMessage`, body: { chat_id, text: msg, parse_mode: 'Markdown' } });\\n  }\\n  throw new Error(\\"Regression test failed!\\");\\n}\\n\\nreturn [{ json: {\\n  ...dong_yeu_cau,\\n  ti_le_test: ti_le_trung_binh,\\n  co_test: co_bo_vang\\n} }];\\n","notice":""},"id":"4a562f10-f1e8-456a-8da4-0e11b8d3eba7","name":"Kiem_Thu_Hoi_Quy_Dice","type":"n8n-nodes-base.code","typeVersion":2,"position":[6240,2224]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst d = $json;\\nconst sid = $env.GOOGLE_SHEETS_SPREADSHEET_ID || '';\\nconst now = new Date().toISOString();\\n\\nconsole.log('[WF03-Approval] Cập nhật Sheets & Ghi Audit Log...');\\n\\n// Lấy giá trị cũ\\nconst res_tt = await $helpers.httpRequest({\\n  method: 'GET',\\n  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Trang_Thai_Van_Hanh!A2:F`,\\n  authentication: 'predefinedCredentialType',\\n  nodeCredentialType: 'googleSheetsOAuth2Api',\\n});\\nconst rows_tt = res_tt.values || [];\\nconst dong_tt_cu = rows_tt.find(r => r[0] === d.ma_tai_san && r[2] === d.moi_truong);\\nconst phien_ban_cu = dong_tt_cu ? dong_tt_cu[1] : 'CHUA_CO';\\n\\nconst MAP_TRANG_THAI = {\\n  'CONG_BO_PHIEN_BAN': 'DA_CONG_BO',\\n  'KHOI_PHUC_PHIEN_BAN': 'DA_CONG_BO',\\n  'TAM_NGUNG': 'TAM_NGUNG',\\n  'THU_HOI': 'DA_THU_HOI',\\n};\\nconst trang_thai_moi = MAP_TRANG_THAI[d.hanh_dong] || 'DA_CONG_BO';\\n\\n// Upsert Trang_Thai_Van_Hanh\\nconst hang_tt = [d.ma_tai_san, d.phien_ban, d.moi_truong, trang_thai_moi, now, d.nguoi_thuc_hien];\\nconst chi_so_tt = rows_tt.findIndex(r => r[0] === d.ma_tai_san && r[2] === d.moi_truong);\\n\\nif (chi_so_tt !== -1) {\\n  const dong = chi_so_tt + 2;\\n  await $helpers.httpRequest({\\n    method: 'PUT',\\n    url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Trang_Thai_Van_Hanh!A${dong}:F${dong}?valueInputOption=USER_ENTERED`,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleSheetsOAuth2Api',\\n    body: { values: [hang_tt] }\\n  });\\n} else {\\n  await $helpers.httpRequest({\\n    method: 'POST',\\n    url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Trang_Thai_Van_Hanh!A1:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleSheetsOAuth2Api',\\n    body: { values: [hang_tt] }\\n  });\\n}\\n\\n// Ghi Audit Log\\nconst hang_audit = [now, d.nguoi_thuc_hien, d.hanh_dong, d.ma_tai_san, phien_ban_cu, d.phien_ban];\\nawait $helpers.httpRequest({\\n  method: 'POST',\\n  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Nhat_Ky_Giam_Sat!A1:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`,\\n  authentication: 'predefinedCredentialType',\\n  nodeCredentialType: 'googleSheetsOAuth2Api',\\n  body: { values: [hang_audit] }\\n});\\n\\nreturn [{ json: {\\n  ...d,\\n  phien_ban_cu,\\n  trang_thai_moi,\\n  ngay_cap_nhat: now\\n} }];\\n","notice":""},"id":"ad75ce71-c848-4da0-b812-894a852849ff","name":"Cap_Nhat_Trang_Thai_Duyet","type":"n8n-nodes-base.code","typeVersion":2,"position":[6432,2224]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst d = $json;\\nconst bot_token = $env.TELEGRAM_BOT_TOKEN;\\nconst chat_id = $env.TELEGRAM_CHAT_ID;\\n\\nif (bot_token && chat_id) {\\n  const emoji = { DA_CONG_BO: '✅', TAM_NGUNG: '⏸️', DA_THU_HOI: '🗑️' }[d.trang_thai_moi] || '📋';\\n  const text_test = d.co_test ? ('\\\\n📊 Tỉ lệ Regression Test: *' + (d.ti_le_test * 100).toFixed(1) + '%*') : '';\\n  const msg = \\n    emoji + ' *QUẢN TRỊ PHÊ DUYỆT TÀI SẢN* ' + emoji + '\\\\n\\\\n' +\\n    '🏷️ Tài sản: `' + d.ma_tai_san + '`\\\\n' +\\n    '📌 Phiên bản mới: *v' + d.phien_ban + '* (Từ: v' + d.phien_ban_cu + ')\\\\n' +\\n    '🌍 Môi trường: ' + d.moi_truong + '\\\\n' +\\n    '👤 Người duyệt: ' + d.nguoi_thuc_hien + '\\\\n' +\\n    '💾 Trạng thái: `' + d.trang_thai_moi + '`' + text_test + '\\\\n\\\\n' +\\n    '_Hồ sơ tiếp nhận của tài sản này sẽ tự động chạy theo phiên bản mới v' + d.phien_ban + '_';\\n  try {\\n    await $helpers.httpRequest({\\n      method: 'POST',\\n      url: 'https://api.telegram.org/bot' + bot_token + '/sendMessage',\\n      body: { chat_id, text: msg, parse_mode: 'Markdown' }\\n    });\\n  } catch(e) {}\\n}\\nreturn [{ json: { thanh_cong: true } }];\\n","notice":""},"id":"d79049fd-6e61-4009-840b-f72213674f7d","name":"Bao_Duyet_Telegram","type":"n8n-nodes-base.code","typeVersion":2,"position":[6640,2224]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst d = $json;\\nconst bot_token = $env.TELEGRAM_BOT_TOKEN;\\nconst chat_id = $env.TELEGRAM_CHAT_ID;\\n\\nif (bot_token && chat_id) {\\n  const msg = \\n    '✅ *AI ĐÃ TỰ HỌC MẪU MỚI THÀNH CÔNG*\\\\n\\\\n' +\\n    '🏷️ Tài sản: `' + d.ma_tai_san + '`\\\\n' +\\n    '📄 Loại tài liệu: *' + d.ten_loai_tai_lieu + '*\\\\n' +\\n    '📊 Số trường tìm thấy: *' + d.so_truong + '*\\\\n' +\\n    '🔒 SHA256 Quy tắc: `' + d.sha256_hash.slice(0, 16) + '...`\\\\n\\\\n' +\\n    '⏸️ *Trạng thái:* `CHO_DUYET`\\\\n' +\\n    '_Vui lòng vào Google Sheet để kiểm tra và duyệt phiên bản hoạt động thành DA_CONG_BO để sử dụng._';\\n  try {\\n    await $helpers.httpRequest({\\n      method: 'POST',\\n      url: 'https://api.telegram.org/bot' + bot_token + '/sendMessage',\\n      body: { chat_id, text: msg, parse_mode: 'Markdown' }\\n    });\\n  } catch(e) {}\\n}\\nreturn [{ json: { thanh_cong: true } }];\\n","notice":""},"id":"2a6c97fc-e558-4161-b85c-32f43312fdbd","name":"Bao_Hoc_Xong_Telegram","type":"n8n-nodes-base.code","typeVersion":2,"position":[7040,1520]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst d = $json;\\nconst sid = $env.GOOGLE_SHEETS_SPREADSHEET_ID || '';\\nconst now = d.ngay_tao;\\n\\nconsole.log('[WF01-Sheets] Đăng ký trạng thái CHO_DUYET...');\\n\\n// 1. Ghi Sổ Đăng Ký\\nconst hang_dk = [d.ma_tai_san, '2.1.0', `99_He_Thong/Quy_Tac_Kiem_Tra/quy_tac_${d.ma_tai_san}_v3.json`, d.sha256_hash, now, 'AI_Auto_Onboarding'];\\nawait $helpers.httpRequest({ \\n  method: 'POST',\\n  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Dang_Ky_Tai_San!A1:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`,\\n  authentication: 'predefinedCredentialType',\\n  nodeCredentialType: 'googleSheetsOAuth2Api',\\n  body: { values: [hang_dk] }\\n});\\n\\n// 2. Upsert Trang_Thai_Van_Hanh\\nconst res_sheet = await $helpers.httpRequest({\\n  method: 'GET',\\n  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Trang_Thai_Van_Hanh!A2:F`,\\n  authentication: 'predefinedCredentialType',\\n  nodeCredentialType: 'googleSheetsOAuth2Api',\\n});\\nconst rows = res_sheet.values || [];\\nconst chi_so = rows.findIndex(r => r[0] === d.ma_tai_san && r[2] === 'van_hanh');\\nconst hang_tt = [d.ma_tai_san, '2.1.0', 'van_hanh', 'CHO_DUYET', now, 'system'];\\n\\nif (chi_so !== -1) {\\n  const dong = chi_so + 2;\\n  await $helpers.httpRequest({\\n    method: 'PUT',\\n    url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Trang_Thai_Van_Hanh!A${dong}:F${dong}?valueInputOption=USER_ENTERED`,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleSheetsOAuth2Api',\\n    body: { values: [hang_tt] }\\n  });\\n} else {\\n  await $helpers.httpRequest({\\n    method: 'POST',\\n    url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values/Trang_Thai_Van_Hanh!A1:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleSheetsOAuth2Api',\\n    body: { values: [hang_tt] }\\n  });\\n}\\n\\nreturn [{ json: d }];\\n","notice":""},"id":"6ab8b94d-bfb8-44e4-9ef5-420b98fc0958","name":"Ghi_Sheets_CHO_DUYET","type":"n8n-nodes-base.code","typeVersion":2,"position":[6832,1520]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nasync function _tim_hoac_tao_thu_muc(ten_thu_muc, parent_id = null) {\\n  let q = `name = '${ten_thu_muc}' and mimeType = 'application/vnd.google-apps.folder' and trashed = false`;\\n  if (parent_id) q += ` and '\\n${parent_id}' in parents`.replace('\\\\n', ''); // Tránh lỗi escape\\n  \\n  const url_search = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(q)}&fields=files(id)`;\\n  const phan_hoi_search = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: url_search,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n  \\n  const folders = phan_hoi_search.files || [];\\n  if (folders.length > 0) return folders[0].id;\\n\\n  const metadata = { name: ten_thu_muc, mimeType: 'application/vnd.google-apps.folder' };\\n  if (parent_id) metadata.parents = [parent_id];\\n\\n  const phan_hoi_create = await $helpers.httpRequest({\\n    method: 'POST',\\n    url: 'https://www.googleapis.com/drive/v3/files',\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n    body: metadata\\n  });\\n  return phan_hoi_create.id;\\n}\\n\\nasync function _ghi_file_txt_drive(ten_file, thu_muc_dich_id, noi_dung) {\\n  const metadata = { name: ten_file, parents: [thu_muc_dich_id], mimeType: 'text/plain' };\\n  const boundary = '-------314159265358979323846';\\n  const delimiter = `\\\\r\\\\n--${boundary}\\\\r\\\\n`;\\n  const close_delim = `\\\\r\\\\n--${boundary}--`;\\n  const metadata_part = `Content-Type: application/json; charset=UTF-8\\\\r\\\\n\\\\r\\\\n${JSON.stringify(metadata)}`;\\n  const media_part = `Content-Type: text/plain; charset=UTF-8\\\\r\\\\n\\\\r\\\\n${noi_dung}`;\\n  const multipart_body = `${delimiter}${metadata_part}${delimiter}${media_part}${close_delim}`;\\n\\n  const url_search = `https://www.googleapis.com/drive/v3/files?q=${encodeURIComponent(\\"name = '\\" + ten_file + \\"' and '\\" + thu_muc_dich_id + \\"' in parents and trashed = false\\")}&fields=files(id)`;\\n  const phan_hoi_search = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: url_search,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n  const files = phan_hoi_search.files || [];\\n\\n  if (files.length > 0) {\\n    await $helpers.httpRequest({\\n      method: 'PATCH',\\n      url: `https://www.googleapis.com/upload/drive/v3/files/${files[0].id}?uploadType=media`,\\n      authentication: 'predefinedCredentialType',\\n      nodeCredentialType: 'googleDriveOAuth2Api',\\n      headers: { 'Content-Type': 'text/plain; charset=UTF-8' },\\n      body: noi_dung\\n    });\\n  } else {\\n    await $helpers.httpRequest({\\n      method: 'POST',\\n      url: 'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart',\\n      authentication: 'predefinedCredentialType',\\n      nodeCredentialType: 'googleDriveOAuth2Api',\\n      headers: { 'Content-Type': `multipart/related; boundary=${boundary}` },\\n      body: multipart_body\\n    });\\n  }\\n}\\n\\nconst input = $('AI_Prep_File_Mau').first().json;\\nconst api_text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';\\nconst phan_tich_obj = JSON.parse(api_text);\\nconst ma_tai_san = input.ma_tai_san;\\n\\nconsole.log('[WF01-Save] Lưu cấu hình lên Drive...');\\n\\nconst ten_prompt = `cau_hinh_${ma_tai_san}_v4.txt`;\\nconst ten_quy_tac = `quy_tac_${ma_tai_san}_v3.json`;\\n\\nconst sys_folder_id = await _tim_hoac_tao_thu_muc('99_He_Thong');\\nconst config_folder_id = await _tim_hoac_tao_thu_muc('Cau_hinh_AI', sys_folder_id);\\nconst rule_folder_id = await _tim_hoac_tao_thu_muc('Quy_Tac_Kiem_Tra', sys_folder_id);\\n\\nconst quy_tac_file_content = {\\n  ma_tai_san: ma_tai_san,\\n  phien_ban: '2.1.0',\\n  ten_loai_tai_lieu: phan_tich_obj.ten_loai_tai_lieu || ma_tai_san,\\n  quy_tac_truong: phan_tich_obj.quy_tac_truong\\n};\\n\\nconst str_prompt = phan_tich_obj.prompt_trich_xuat;\\nconst str_quy_tac = JSON.stringify(quy_tac_file_content, null, 2);\\n\\nawait _ghi_file_txt_drive(ten_prompt, config_folder_id, str_prompt);\\nawait _ghi_file_txt_drive(ten_quy_tac, rule_folder_id, str_quy_tac);\\n\\nconst { createHash } = require('crypto');\\nconst sha256_hash = createHash('sha256').update(str_quy_tac, 'utf8').digest('hex');\\n\\nreturn [{ json: {\\n  ma_tai_san,\\n  ten_loai_tai_lieu: quy_tac_file_content.ten_loai_tai_lieu,\\n  so_truong: Object.keys(phan_tich_obj.quy_tac_truong || {}).length,\\n  sha256_hash,\\n  ngay_tao: new Date().toISOString()\\n} }];\\n","notice":""},"id":"d2889d78-8ca3-4b77-a794-9a93527b587b","name":"Ghi_Cau_Hinh_Drive","type":"n8n-nodes-base.code","typeVersion":2,"position":[6640,1520]},{"parameters":{"curlImport":"","method":"POST","url":"=https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key={{$env.GEMINI_API_KEY}}","authentication":"none","provideSslCertificates":false,"sendQuery":false,"sendHeaders":false,"sendBody":true,"contentType":"json","specifyBody":"json","jsonBody":"={{ JSON.stringify($json.gemini_body) }}","options":{"timeout":120000},"infoMessage":""},"id":"52c897d6-b4df-448e-8bbf-1566e487ce4d","name":"Gemini_Phan_Tich_Mau","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[6432,1520]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst payload = $json;\\nconst file_id = payload.id || '';\\nconst ten_file = payload.name || '';\\nconst mime_type = payload.mimeType || '';\\n\\nconsole.log('[WF01-Prep] Đọc file mẫu: ' + ten_file);\\n\\nconst LOAI_DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';\\nlet noi_dung_cho_ai;\\nlet phuong_phap;\\nlet mime_gui_gemini;\\n\\nif (mime_type === LOAI_DOCX) {\\n  const url_export = `https://www.googleapis.com/drive/v3/files/${file_id}/export?mimeType=text%2Fplain`;\\n  const van_ban = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: url_export,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n  });\\n  noi_dung_cho_ai = typeof van_ban === 'string' ? van_ban : JSON.stringify(van_ban);\\n  phuong_phap = 'text';\\n  mime_gui_gemini = 'text/plain';\\n} else {\\n  const url_dl = `https://www.googleapis.com/drive/v3/files/${file_id}?alt=media`;\\n  const res_bin = await $helpers.httpRequest({\\n    method: 'GET',\\n    url: url_dl,\\n    authentication: 'predefinedCredentialType',\\n    nodeCredentialType: 'googleDriveOAuth2Api',\\n    encoding: 'arraybuffer',\\n    returnFullResponse: true,\\n  });\\n  const buffer = Buffer.from(res_bin.body);\\n  noi_dung_cho_ai = buffer.toString('base64');\\n  phuong_phap = 'multimodal';\\n  mime_gui_gemini = mime_type;\\n}\\n\\nconst ten_khong_duoi = ten_file.replace(/\\\\.[^.]+$/, '');\\nconst vi_tri = ten_khong_duoi.indexOf('__');\\nif (vi_tri === -1) {\\n  throw new Error('Tên file mẫu không đúng định dạng. Cần dạng: <ma_tai_san>__template.pdf');\\n}\\nconst ma_tai_san = ten_khong_duoi.substring(0, vi_tri);\\n\\nconst prompt_phan_tich = `Bạn là một chuyên gia thiết kế hệ thống và kỹ sư Prompt chuyên nghiệp. Đọc kỹ văn bản mẫu được cung cấp dưới đây.\\nNhiệm vụ của bạn là phân tích tài liệu này để tự động thiết kế cấu trúc dữ liệu cần trích xuất và tạo System Prompt trích xuất tối ưu.\\n\\nQUY TẮC BẮT BUỘC:\\n- Đề xuất các trường quan trọng nhất trong tài liệu (như Họ tên, Ngày tháng, Số tiền, Mã số, Địa chỉ,...).\\n- Trong \\"quy_tac_truong\\": các trường kiểu ngày tháng phải set kieu=\\"date\\", số tiền set kieu=\\"currency\\", văn bản set kieu=\\"text\\".\\n- Viết một \\"prompt_trich_xuat\\" thật chi tiết để hướng dẫn AI khác đọc tài liệu này và trích xuất đúng các trường đã định nghĩa.\\n\\nTrả về một JSON hợp lệ (KHÔNG có markdown, KHÔNG có giải thích ngoài JSON) theo đúng cấu trúc sau:\\n{\\n  \\"ten_loai_tai_lieu\\": \\"Tên loại tài liệu tiếng Việt (ví dụ: Hợp đồng Lao động)\\",\\n  \\"quy_tac_truong\\": {\\n    \\"ten_truong_1\\": { \\"bat_buoc\\": true, \\"kieu\\": \\"text\\", \\"mo_ta\\": \\"Mô tả trường này\\" },\\n    \\"ten_truong_2\\": { \\"bat_buoc\\": true, \\"kieu\\": \\"date\\", \\"mo_ta\\": \\"Mô tả trường ngày tháng\\" },\\n    \\"ten_truong_3\\": { \\"bat_buoc\\": false, \\"kieu\\": \\"currency\\", \\"mo_ta\\": \\"Mô tả trường số tiền\\" }\\n  },\\n  \\"prompt_trich_xuat\\": \\"System prompt chi tiết...\\"\\n}`;\\n\\nlet parts = [];\\nif (phuong_phap === 'text') {\\n  parts.push({ text: `${prompt_phan_tich}\\\\n\\\\n=== NỘI DUNG TÀI LIỆU ===\\\\n${noi_dung_cho_ai.slice(0, 32000)}` });\\n} else {\\n  parts.push({ text: prompt_phan_tich });\\n  parts.push({ inlineData: { mimeType: mime_gui_gemini, data: noi_dung_cho_ai } });\\n}\\n\\nconst gemini_body = {\\n  contents: [{ parts }],\\n  generationConfig: { temperature: 0.2, responseMimeType: 'application/json' }\\n};\\n\\nreturn [{ json: {\\n  file_id, ten_file, mime_type, ma_tai_san, gemini_body\\n} }];\\n","notice":""},"id":"5a8eceec-8074-4cb1-a7d5-fa3c00cb812e","name":"AI_Prep_File_Mau","type":"n8n-nodes-base.code","typeVersion":2,"position":[6240,1520]},{"parameters":{"pollTimes":{"item":[{"mode":"everyMinute"}]},"authentication":"oAuth2","triggerOn":"specificFolder","folderToWatch":{"__rl":true,"value":"1-Ti14cE-ziCd3_ZZuTkBWpPQ3c7IE2rs","mode":"id"},"event":"watchFolderUpdated"},"id":"56084fa9-7788-48c6-b240-a387d8901152","name":"Kich_Hoat_Mau_Moi","type":"n8n-nodes-base.googleDriveTrigger","typeVersion":1,"position":[6032,1520],"credentials":{"googleDriveOAuth2Api":{"id":"rTUSZlOSjhGVDCDG","name":"Google Drive account LETRUNG80.HUE"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst payload = $json;\\nconst file_id = payload.id || '';\\nconst ten_file = payload.name || '';\\nconst mime_type = payload.mimeType || '';\\n\\nconst ten_khong_duoi = ten_file.replace(/\\\\.[^.]+$/, '');\\nconst vi_tri = ten_khong_duoi.indexOf('__');\\nif (vi_tri === -1) {\\n  throw new Error('Tên file mẫu không đúng định dạng. Cần dạng: <ma_tai_san>__template.pdf');\\n}\\nconst ma_tai_san = ten_khong_duoi.substring(0, vi_tri);\\nconst is_docx = mime_type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';\\n\\nconst url_download = is_docx\\n  ? `https://www.googleapis.com/drive/v3/files/${file_id}/export?mimeType=text%2Fplain`\\n  : `https://www.googleapis.com/drive/v3/files/${file_id}?alt=media`;\\n\\nreturn [{ json: {\\n  file_id, ten_file, mime_type, ma_tai_san, is_docx, url_download\\n} }];\\n","notice":""},"id":"88974dae-dd3a-4ff7-9455-687048a32932","name":"Phan_Tich_Ten_File","type":"n8n-nodes-base.code","typeVersion":2,"position":[6240,1248]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst meta = $('Phan_Tich_Ten_File').first().json;\\nconst binary_data = $binary.data;\\n\\nlet parts = [];\\nconst prompt_phan_tich = `Bạn là một chuyên gia thiết kế hệ thống và kỹ sư Prompt chuyên nghiệp. Đọc kỹ văn bản mẫu được cung cấp dưới đây.\\nNhiệm vụ của bạn là phân tích tài liệu này để tự động thiết kế cấu trúc dữ liệu cần trích xuất và tạo System Prompt trích xuất tối ưu.\\n\\nQUY TẮC BẮT BUỘC:\\n- Đề xuất các trường quan trọng nhất trong tài liệu (như Họ tên, Ngày tháng, Số tiền, Mã số, Địa chỉ,...).\\n- Trong \\"quy_tac_truong\\": các trường kiểu ngày tháng phải set kieu=\\"date\\", số tiền set kieu=\\"currency\\", văn bản set kieu=\\"text\\".\\n- Viết một \\"prompt_trich_xuat\\" thật chi tiết để hướng dẫn AI khác đọc tài liệu này và trích xuất đúng các trường đã định nghĩa.\\n\\nTrả về một JSON hợp lệ (KHÔNG có markdown, KHÔNG có giải thích ngoài JSON) theo đúng cấu trúc sau:\\n{\\n  \\"ten_loai_tai_lieu\\": \\"Tên loại tài liệu tiếng Việt (ví dụ: Hợp đồng Lao động)\\",\\n  \\"quy_tac_truong\\": {\\n    \\"ten_truong_1\\": { \\"bat_buoc\\": true, \\"kieu\\": \\"text\\", \\"mo_ta\\": \\"Mô tả trường này\\" },\\n    \\"ten_truong_2\\": { \\"bat_buoc\\": true, \\"kieu\\": \\"date\\", \\"mo_ta\\": \\"Mô tả trường ngày tháng\\" },\\n    \\"ten_truong_3\\": { \\"bat_buoc\\": false, \\"kieu\\": \\"currency\\", \\"mo_ta\\": \\"Mô tả trường số tiền\\" }\\n  },\\n  \\"prompt_trich_xuat\\": \\"System prompt chi tiết...\\"\\n}`;\\n\\nif (meta.is_docx) {\\n  const noi_dung_text = Buffer.from(binary_data.data, 'base64').toString('utf8');\\n  parts.push({ text: `${prompt_phan_tich}\\\\n\\\\n=== NỘI DUNG TÀI LIỆU ===\\\\n${noi_dung_text.slice(0, 32000)}` });\\n} else {\\n  parts.push({ text: prompt_phan_tich });\\n  parts.push({ inlineData: { mimeType: meta.mime_type, data: binary_data.data } });\\n}\\n\\nconst gemini_body = {\\n  contents: [{ parts }],\\n  generationConfig: { temperature: 0.2, responseMimeType: 'application/json' }\\n};\\n\\nreturn [{ json: {\\n  ...meta,\\n  gemini_body\\n} }];\\n","notice":""},"id":"81ac7b81-c165-49cd-bd76-ee225069764a","name":"AI_Prep_Gemini_Body","type":"n8n-nodes-base.code","typeVersion":2,"position":[6640,1248]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"\\nconst input = $('AI_Prep_Gemini_Body').first().json;\\nconst api_text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';\\nconst phan_tich_obj = JSON.parse(api_text);\\nconst ma_tai_san = input.ma_tai_san;\\n\\nconst quy_tac_file_content = {\\n  ma_tai_san: ma_tai_san,\\n  phien_ban: '2.1.0',\\n  ten_loai_tai_lieu: phan_tich_obj.ten_loai_tai_lieu || ma_tai_san,\\n  quy_tac_truong: phan_tich_obj.quy_tac_truong\\n};\\n\\nconst str_prompt = phan_tich_obj.prompt_trich_xuat;\\nconst str_quy_tac = JSON.stringify(quy_tac_file_content, null, 2);\\n\\nconst { createHash } = require('crypto');\\nconst sha256_hash = createHash('sha256').update(str_quy_