A256 Quy tắc: `' + d.sha256_hash.slice(0, 16) + '...`\\\\n\\\\n' +\\n    '⏸️ *Trạng thái:* `CHO_DUYET`\\\\n' +\\n    '_Vui lòng kiểm tra thông số thiết lập trên hệ thống._';\\n  try {\\n    await fetch('https://api.telegram.org/bot' + bot_token + '/sendMessage', {\\n      method: 'POST',\\n      headers: { 'Content-Type': 'application/json' },\\n      body: JSON.stringify({ chat_id, text: msg, parse_mode: 'Markdown' })\\n    });\\n  } catch(e) {}\\n}\\nreturn [{ json: { thanh_cong: true, ma_tai_san: d.ma_tai_san } }];\\n","notice":""},"id":"c56a8a56-0055-4291-8fc0-bb7f3f0a8ac9","name":"Bao_Hoc_Xong_Telegram1","type":"n8n-nodes-base.code","typeVersion":2,"position":[7248,1248]},{"parameters":{"curlImport":"","method":"POST","url":"=https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key={{$env.GEMINI_API_KEY}}","authentication":"none","provideSslCertificates":false,"sendQuery":false,"sendHeaders":false,"sendBody":true,"contentType":"json","specifyBody":"json","jsonBody":"={{ JSON.stringify($json.gemini_body) }}","options":{"timeout":120000},"infoMessage":""},"id":"32c9088e-74e9-41fb-bbb2-0429e7aaf0f1","name":"Gemini_Phan_Tich_Mau2","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[6448,1136]},{"parameters":{"pollTimes":{"item":[{"mode":"everyMinute"}]},"authentication":"oAuth2","triggerOn":"specificFolder","folderToWatch":{"__rl":true,"value":"1-Ti14cE-ziCd3_ZZuTkBWpPQ3c7IE2rs","mode":"id"},"event":"folderUpdated","asas":""},"id":"e4fefbfe-4e20-4644-bee9-3016377a73a2","name":"01_Trigger_Mau_Moi","type":"n8n-nodes-base.googleDriveTrigger","typeVersion":1,"position":[6000,944],"credentials":{"googleDriveOAuth2Api":{"id":"rTUSZlOSjhGVDCDG","name":"Google Drive account LETRUNG80.HUE"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const payload = $json;\\nconst file_id = payload.id || '';\\nconst ten_file = payload.name || '';\\nconst mime_type = payload.mimeType || '';\\n\\nconsole.log('[WF01-Prep] Đọc file mẫu: ' + ten_file);\\n\\n// Lấy tên không chứa đuôi file (.pdf, .docx, ...)\\nconst ten_khong_duoi = ten_file.replace(/\\\\.[^.]+$/, '');\\n\\n// Regex bóc tách mã tài sản (Hỗ trợ cả '__template', '_template' hoặc file thường)\\nlet ma_tai_san = '';\\nconst match = ten_khong_duoi.match(/^(.+?)(?:__|_)template$/i);\\n\\nif (match && match[1] && match[1].trim() !== '') {\\n  ma_tai_san = match[1].trim();\\n} else {\\n  // Nếu đặt tên không theo chuẩn __template, lấy luôn tên file làm Mã tài sản\\n  ma_tai_san = ten_khong_duoi.replace(/(?:__|_)template$/i, '').trim();\\n  if (!ma_tai_san) {\\n    ma_tai_san = 'MAU_TAI_SAN_' + Date.now().toString().slice(-4);\\n  }\\n}\\n\\n// Chuẩn hóa mã tài sản thành chữ hoa không khoảng trắng\\nma_tai_san = ma_tai_san.toUpperCase().replace(/\\\\s+/g, '_');\\n\\nconst is_docx = mime_type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';\\n\\nconst url_download = is_docx\\n  ? `https://www.googleapis.com/drive/v3/files/${file_id}/export?mimeType=text%2Fplain`\\n  : `https://www.googleapis.com/drive/v3/files/${file_id}?alt=media`;\\n\\nreturn [{ json: {\\n  file_id, ten_file, mime_type, ma_tai_san, is_docx, url_download\\n} }];","notice":""},"id":"b3223e2e-b53e-4821-ac31-6b5c0ef5b539","name":"02_Parse_Metadata","type":"n8n-nodes-base.code","typeVersion":2,"position":[6224,944]},{"parameters":{"curlImport":"","method":"GET","url":"={{ $json.url_download }}","authentication":"predefinedCredentialType","nodeCredentialType":"googleDriveOAuth2Api","provideSslCertificates":false,"sendQuery":false,"sendHeaders":false,"sendBody":false,"options":{"response":{"response":{"fullResponse":false,"neverError":false,"responseFormat":"file","outputPropertyName":"data"}}},"infoMessage":""},"id":"c002a660-a6f4-479f-8dcc-c312dea4caf2","name":"03_Tai_File_Tu_Drive","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[6448,944],"credentials":{"googleDriveOAuth2Api":{"id":"rTUSZlOSjhGVDCDG","name":"Google Drive account LETRUNG80.HUE"}}},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const meta = $('02_Parse_Metadata').first().json;\\nconst binary_data = $binary.data;\\n\\nconst prompt_phan_tich = `Bạn là một chuyên gia thiết kế hệ thống và kỹ sư Prompt chuyên nghiệp. Đọc kỹ văn bản mẫu được cung cấp dưới đây.\\nNhiệm vụ của bạn là phân tích tài liệu này để tự động thiết kế cấu trúc dữ liệu cần trích xuất và tạo System Prompt trích xuất tối ưu.\\n\\nQUY TẮC BẮT BUỘC:\\n- Đề xuất các trường quan trọng nhất trong tài liệu (như Họ tên, Ngày tháng, Số tiền, Mã số, Địa chỉ,...).\\n- Trong \\"quy_tac_truong\\": các trường kiểu ngày tháng phải set kieu=\\"date\\", số tiền set kieu=\\"currency\\", văn bản set kieu=\\"text\\".\\n- Viết một \\"prompt_trich_xuat\\" thật chi tiết để hướng dẫn AI khác đọc tài liệu này và trích xuất đúng các trường đã định nghĩa.\\n\\nTrả về một JSON hợp lệ (KHÔNG có markdown, KHÔNG có giải thích ngoài JSON) theo đúng cấu trúc sau:\\n{\\n  \\"ten_loai_tai_lieu\\": \\"Tên loại tài liệu tiếng Việt (ví dụ: Hợp đồng Lao động)\\",\\n  \\"quy_tac_truong\\": {\\n    \\"ten_truong_1\\": { \\"bat_buoc\\": true, \\"kieu\\": \\"text\\", \\"mo_ta\\": \\"Mô tả trường này\\" },\\n    \\"ten_truong_2\\": { \\"bat_buoc\\": true, \\"kieu\\": \\"date\\", \\"mo_ta\\": \\"Mô tả trường ngày tháng\\" },\\n    \\"ten_truong_3\\": { \\"bat_buoc\\": false, \\"kieu\\": \\"currency\\", \\"mo_ta\\": \\"Mô tả trường số tiền\\" }\\n  },\\n  \\"prompt_trich_xuat\\": \\"System prompt chi tiết...\\"\\n}`;\\n\\nlet parts = [];\\nif (meta.is_docx) {\\n  const noi_dung_text = Buffer.from(binary_data.data, 'base64').toString('utf8');\\n  parts.push({ text: `${prompt_phan_tich}\\\\n\\\\n=== NỘI DUNG TÀI LIỆU ===\\\\n${noi_dung_text.slice(0, 32000)}` });\\n} else {\\n  parts.push({ text: prompt_phan_tich });\\n  parts.push({ inlineData: { mimeType: meta.mime_type, data: binary_data.data } });\\n}\\n\\nconst gemini_body = {\\n  contents: [{ parts }],\\n  generationConfig: { temperature: 0.2, responseMimeType: 'application/json' }\\n};\\n\\nreturn [{ json: { ...meta, gemini_body } }];","notice":""},"id":"4e81102d-42fe-43d6-8d74-f8cf35b55740","name":"04_Dung_Gemini_Payload","type":"n8n-nodes-base.code","typeVersion":2,"position":[6672,944]},{"parameters":{"curlImport":"","method":"POST","url":"=https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key={{$env.GEMINI_API_KEY}}","authentication":"none","provideSslCertificates":false,"sendQuery":false,"sendHeaders":false,"sendBody":true,"contentType":"json","specifyBody":"json","jsonBody":"={{ JSON.stringify($json.gemini_body) }}","options":{"timeout":120000},"infoMessage":""},"id":"0a3b2b37-b9f9-47b6-b3bc-ebc7efc1efc3","name":"05_Gemini_Phan_Tich_Mau","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[6880,944]},{"parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const input = $('04_Dung_Gemini_Payload').first().json;\\nconst api_text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';\\nconst phan_tich_obj = JSON.parse(api_text);\\nconst ma_tai_san = input.ma_tai_san;\\n\\nconst quy_tac_file_content = {\\n  ma_tai_san: ma_tai_san,\\n  phien_ban: '2.1.0',\\n  ten_loai_tai_lieu: phan_tich_obj.ten_loai_tai_lieu || ma_tai_san,\\n  quy_tac_truong: phan_tich_obj.quy_tac_truong\\n};\\n\\nconst str_prompt = phan_tich_obj.prompt_trich_xuat;\\nconst str_quy_tac = JSON.stringify(quy_tac_file_content, null, 2);\\n\\nconst { createHash } = require('crypto');\\nconst sha256_hash = createHash('sha256').update(str_quy_tac, 'utf8').digest('hex');\\n\\nreturn [{ json: {\\n  ma_tai_san,\\n  ten_loai_tai_lieu: quy_tac_file_content.ten_loai_tai_lieu,\\n  so_truong: Object.keys(phan_tich_obj.quy_tac_truong || {}).length,\\n  sha256_hash,\\n  str_prompt,\\n  str_quy_tac,\\n  ngay_tao: new Date().toISOString()\\n} }];","notice":""},"id":"5caae14f-fd02-4524-add2-30ccab865f89","name":"06_Tao_Config_Va_SHA2