Make_Audio(PASS)	f	[{"parameters":{},"id":"9f99b66d-f028-46c8-af33-dc468fa7443c","name":"On Error","type":"n8n-nodes-base.errorTrigger","typeVersion":1,"position":[400,256]},{"parameters":{"mode":"runOnceForEachItem","jsCode":"const fs = require('fs'); function countWav(dir){ try{ return fs.readdirSync(dir,{withFileTypes:true}).filter(d=>d.isFile() && d.name.endsWith('.wav')).length; }catch(e){ return 0; } } const speakersRoot = `${$json.jobSpeakers}`; const rvcRoot = `${$json.jobRoot}/rvc`; return { json: { stem: $json.stem, jobRoot: $json.jobRoot, vocals: $json.demucsVocals, rttm: $json.rttmPath, srt: $json.srtPath, speakersWav: countWav(speakersRoot), rvcWav: countWav(rvcRoot), status: 'COMPLETED' } };"},"id":"e447ffd8-152f-49ed-8c79-052936521b16","name":"Summary Report","type":"n8n-nodes-base.code","typeVersion":2,"position":[1664,352]},{"parameters":{},"id":"2cdefcf8-86e1-4b0d-83f6-02fd62c63e0e","name":"Done","type":"n8n-nodes-base.noOp","typeVersion":1,"position":[1504,352]},{"parameters":{"command":"bash -lc '\\\\nset -euo pipefail\\\\nROOT={{ JSON.stringify($json.jobSpeakers) }}\\\\nOUTROOT={{ JSON.stringify($json.jobRoot) }}/rvc\\\\nmkdir -p \\"$OUTROOT\\"\\\\nshopt -s nullglob\\\\nfor wav in \\"$ROOT\\"/SPEAKER_*/speaker_*.wav; do\\\\n  [ -s \\"$wav\\" ] || continue\\\\n  bn=$(basename \\"$wav\\" .wav)\\\\n  spdir=$(basename \\"$(dirname \\"$wav\\")\\")\\\\n  outdir=\\"$OUTROOT/$spdir\\"\\\\n  mkdir -p \\"$outdir\\"\\\\n  out=\\"$outdir/${bn}_rvc.wav\\"\\\\n  {{ $json.pythonExe || \\"python3\\" }} {{ JSON.stringify($json.rvcPy) }} --input \\"$wav\\" --output \\"$out\\" --model {{ JSON.stringify($json.rvcModel) }} --index {{ JSON.stringify($json.rvcIndex) }} --f0method {{ JSON.stringify($json.rvcF0Method) }} --transpose {{ JSON.stringify($json.rvcTranspose) }}\\\\ndone\\\\nprintf \\"RVC_DONE\\"'\\\\n"},"id":"4e82fdc2-0388-4b7d-92b5-710c7e15b694","name":"RVC Convert","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1344,160]},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":1},"conditions":[{"leftValue":"={{ $json.enableRVC }}","rightValue":"","operator":{"type":"boolean","operation":"isTrue"},"id":"enable-rvc-bool"},{"id":"02f047da-ecdc-4344-9044-deed41606e8c","leftValue":"","rightValue":"","operator":{"type":"string","operation":"equals","name":"filter.operator.equals"}}],"combinator":"and"},"options":{}},"id":"6133c8a9-e719-42e5-a5fa-c84112913009","name":"Enable RVC?","type":"n8n-nodes-base.if","typeVersion":2,"position":[1232,336]},{"parameters":{"content":"STEP: workflow n8n ","height":780,"width":2032,"color":4},"id":"f3591300-b26f-4af1-82bd-b2d5f90c9a36","name":"Sticky Note","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[192,624]},{"parameters":{"command":"=bash -c '\\nset -euo pipefail\\n\\nIN={{ JSON.stringify($json.src) }}\\nOUT={{ JSON.stringify($json.inputWav) }}\\nFF={{ JSON.stringify($json.ffmpegCmd || \\"ffmpeg\\") }}\\n\\n# === Bước 1: Skip nếu file có sẵn và >5KB ===\\nif [ -f \\"$OUT\\" ] && [ \\"$(stat -c%s \\"$OUT\\")\\" -gt 5120 ]; then\\n  echo \\"[FFMPEG][INFO] Found existing output: $OUT, skip re-extract.\\" >&2\\n  printf \\"%s\\\\n\\" \\"$OUT\\"\\n  exit 0\\nfi\\n\\n# === Bước 2: Thiết lập thread cố định ===\\nTHREADS=32\\nmkdir -p \\"$(dirname \\"$OUT\\")\\"\\n\\necho \\"[FFMPEG][INFO] Using THREADS=$THREADS for conversion.\\" >&2\\n\\n# === Chuyển đổi audio ===\\nif \\"$FF\\" -hide_banner -loglevel error -nostdin -y \\\\\\n   -i \\"$IN\\" -vn -ar 16000 -ac 1 -threads \\"$THREADS\\" \\"$OUT\\"; then\\n  echo \\"[FFMPEG][SUCCESS] Converted: $OUT\\" >&2\\nelse\\n  echo \\"[FFMPEG][WARN] Retry without thread limit\\" >&2\\n  if \\"$FF\\" -hide_banner -loglevel error -nostdin -y \\\\\\n      -i \\"$IN\\" -vn -ar 16000 -ac 1 \\"$OUT\\"; then\\n    echo \\"[FFMPEG][SUCCESS] Converted (retry): $OUT\\" >&2\\n  else\\n    echo \\"[FFMPEG][ERROR] Failed to convert: $IN\\" >&2\\n    exit 1\\n  fi\\nfi\\n\\n# === Verify output format bằng ffprobe ===\\nRATE=$(\\n  ffprobe -v quiet -select_streams a:0 \\\\\\n    -show_entries stream=sample_rate,channels \\\\\\n    -of csv=p=0 \\"$OUT\\" 2>/dev/null | xargs\\n)\\necho \\"[FFMPEG][DEBUG] Output format check (sample_rate,channels): $RATE\\" >&2\\n\\nprintf \\"%s\\\\n\\" \\"$OUT\\"\\n'\\n"},"id":"992495d9-7f17-4b68-b18f-46322850b9c2","name":"Extract 16k Mono WAV - Optimized","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1296,784]},{"parameters":{"command":"=bash -lc 'find {{ JSON.stringify($(\\"Set Config\\").item.json.inDir) }} -maxdepth 1 -type f \\\\( -iname \\"*.mp4\\" -o -iname \\"*.mkv\\" -o -iname \\"*.mov\\" -o -iname \\"*.wav\\" -o -iname \\"*.mp3\\" -o -iname \\"*.m4a\\" \\\\) -printf \\"%f||%p\\\\n\\"'"},"id":"9d24c31b-af7b-44a5-96ac-b81f11dbe9ae","name":"List Input Files","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[832,784]},{"parameters":{"keepOnlySet":true,"values":{"string":[{"name":"inDir","value":"/files/voice/input"},{"name":"outDir","value":"/files/voice/output"},{"name":"demucsCmd","value":"demucs"},{"name":"ffmpegCmd","value":"ffmpeg"},{"name":"pythonExe","value":"python3"},{"name":"Diarize_Pyannote","value":"/scripts/diarize_pyannote.py"},{"name":"Diarpy_Silero","value":"/scripts/diarize_silero.py"},{"name":"separateSpeakersPy","value":"/scripts/separate_speakers.py"},{"name":"rvcPy","value":"/scripts/batch_rvc.py"},{"name":"mergePy","value":"/scripts/merge.py"},{"name":"rvcModel","value":"/rvc-models/jackie.pth"},{"name":"rvcIndex","value":"/rvc-models/jackie.index"},{"name":"rvcF0Method","value":"harvest"},{"name":"rvcTranspose","value":"0"},{"name":"whisperUrl","value":"http://whisper:9000/asr?task=transcribe&language=vi"}],"boolean":[{"name":"Enable Pyannote ","value":true},{"name":"enableRVC","value":true}]},"options":{}},"id":"7f80d971-5a8b-4896-a9f3-f592e586b747","name":"Set Config","type":"n8n-nodes-base.set","typeVersion":2,"position":[608,784]},{"parameters":{},"id":"6121dd38-a821-468d-a2a8-eb1359ff5999","name":"Start","type":"n8n-nodes-base.manualTrigger","typeVersion":1,"position":[256,784],"disabled":true},{"parameters":{"jsCode":"// Build per-file job workspace name: name, name1, name2...\\nconst lines = String($json.stdout || '').split(/\\\\r?\\\\n/).map(s=>s.trim()).filter(Boolean);\\nif (!lines.length) return [];\\n\\nconst cfg = $('Set Config').first().json;\\n\\nreturn lines.map(row=>{\\n  const [base, full] = row.split('||');\\n  const stemRaw = (base || '').replace(/\\\\.[^.]+$/, '');\\n  \\n  // Cải tiến: Sử dụng regex mạnh hơn để loại bỏ tất cả các ký tự không an toàn\\n  // và giới hạn độ dài tối đa 100 ký tự để tránh lỗi string quá dài\\n  let stem = stemRaw.replace(/[^a-zA-Z0-9-]/g, '_')\\n                   .replace(/_{2,}/g, '_')\\n                   .replace(/^_+|_+$/g, '');\\n  \\n  // Giới hạn độ dài tối đa 100 ký tự\\n  if (stem.length > 20) {\\n    stem = stem.substring(0, 20);\\n  }\\n\\n  const jobRoot = `${cfg.outDir}/${stem}`;\\n  const inputWav = `${jobRoot}/htdemucs_6s/input_16k_mono.wav`;\\n  const demucsVocals = `${jobRoot}/htdemucs_6s/input_16k_mono/vocals.wav`;\\n  const rttmPath = `${jobRoot}/htdemucs_6s/input_16k_mono/vocals.rttm`;\\n  const jobWhisper = `${jobRoot}/whisper`;\\n  const jobSpeakers = `${jobRoot}/speakers`;\\n  const srtPath = `${jobWhisper}/${stem}.srt`;\\n\\n  return { json: {\\n    src: full,\\n    base,\\n    stem,\\n    jobRoot,\\n    jobWhisper,\\n    jobSpeakers,\\n    inputWav,\\n    demucsVocals,\\n    rttmPath,\\n    srtPath,\\n    inDir: cfg.inDir,\\n    outDir: cfg.outDir,\\n    demucsCmd: cfg.demucsCmd,\\n    ffmpegCmd: cfg.ffmpegCmd,\\n    pythonExe: cfg.pythonExe,\\n    Diarize_Pyannote: cfg.Diarize_Pyannote,\\n    Diarpy_Silero: cfg.Diarpy_Silero,\\n    separateSpeakersPy: cfg.separateSpeakersPy,\\n    rvcPy: cfg.rvcPy,\\n    mergePy: cfg.mergePy,\\n    rvcModel: cfg.rvcModel,\\n    rvcIndex: cfg.rvcIndex,\\n    rvcF0Method: cfg.rvcF0Method,\\n    rvcTranspose: cfg.rvcTranspose,\\n    whisperUrl: cfg.whisperUrl,\\n    enableRVC: cfg.enableRVC === undefined ? true : !!cfg.enableRVC\\n  }};\\n});"},"id":"a2f21f10-93fc-433f-872f-7ced7507140d","name":"Prepare Job","type":"n8n-nodes-base.code","typeVersion":2,"position":[1056,784]},{"parameters":{"chatId":"5584954476","text":"=Công việc tách speaker đã hoàn tất !","additionalFields":{}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[1680,992],"id":"994a11b7-3267-4ee3-85ae-7d9052e349da","name":"Send a text message1","webhookId":"5fac44f4-b22a-4893-af7a-3d87e013787d","credentials":{"telegramApi":{"id":"3dY6VmwOtXaErnPU","name":"Telegram account"}}},{"parameters":{"options":{}},"id":"1105ab53-6bf9-4489-8b71-161b995ef2bf","name":"Loop Segments","type":"n8n-nodes-base.splitInBatches","typeVersion":3,"position":[800,1152]},{"parameters":{"mode":"runOnceForEachItem","jsCode":"function fmt(t) {\\n  const h = String(Math.floor(t / 3600)).padStart(2, '0');\\n  const m = String(Math.floor((t % 3600) / 60)).padStart(2, '0');\\n  const s = String(Math.floor(t % 60)).padStart(2, '0');\\n  return `${h}:${m}:${s},000`;\\n}\\n\\n// === Lấy transcript ===\\nconst text = $json.text \\n          || $json.transcription \\n          || $json.data?.text \\n          || $json.data \\n          || '';\\n\\nif (!text.trim()) {\\n  return { json: { skip: true } };\\n}\\n\\n// === Metadata gốc từ Loop Segments ===\\nconst seg = $('Loop Segments').item.json;\\nconst st = parseFloat(seg.start);\\nconst dur = parseFloat(seg.duration);\\n\\nif (isNaN(st) || isNaN(dur) || dur <= 0) {\\n  return { json: { skip: true } };\\n}\\n\\nconst et = st + dur;\\nconst idx = seg.index || 1;   // lấy index từ Build Segments\\n\\n// === Hàm chuẩn hóa slug ===\\nfunction slugify(str) {\\n  if (typeof str !== 'string') return '';\\n\\n  return str\\n    .normalize('NFD') // Tách base + dấu\\n    .replace(/[\\\\u0300-\\\\u036f]/g, '') // Bỏ dấu\\n    .replace(/[đĐ]/g, m => m === 'đ' ? 'd' : 'D') // Xử lý đ/Đ\\n    .replace(/['’`\\".,!?;:(){}[\\\\]<>]/g, ' ') // Bỏ dấu câu\\n    .replace(/[^\\\\p{L}\\\\p{N} ]/gu, ' ') // Giữ chữ cái, số, khoảng trắng\\n    .trim()\\n    .replace(/\\\\s+/g, ' ') // Gom nhiều space\\n    .split(' ')\\n    .filter((word, i, arr) => {\\n      if (!word) return false;\\n      // Loại bỏ từ trùng liên tiếp (so sánh không phân biệt hoa thường)\\n      if (i > 0 && word.toLowerCase() === arr[i - 1].toLowerCase()) return false;\\n      return true;\\n    })\\n    .slice(0, 20)\\n    .join('_');\\n}\\n\\n\\nconst snippet = slugify(text) || \\"segment\\";\\n\\n// === Tạo tên file mới ===\\nconst dir = seg.segFile.replace(/\\\\/[\\\\w.-]+$/, '');\\nconst base = `Start_${st.toFixed(3)}s-End_${et.toFixed(3)}s-${snippet}_${idx}`;\\n\\nconst newWav = `${dir}/${base}.wav`;\\nconst newTxt = `${dir}/${base}.txt`;\\nconst segFile = $('Read Segment').item.json.stdout;\\nconst txtContent = text.replace(/\\\\r?\\\\n/g, \\" \\");\\n\\n// === Entry SRT ===\\nconst srt = `${idx}\\n${fmt(st)} --> ${fmt(et)}\\n${text}\\n\\n`;\\n\\n// === Output JSON đầy đủ ===\\nreturn {\\n  json: {\\n    ...seg,            // giữ metadata gốc\\n    index: idx,        // luôn có index\\n    start: st,\\n    duration: dur,\\n    segFile: segFile,\\n\\n    srtEntry: srt,\\n    wavFile: newWav,\\n    txtFile: newTxt,\\n    transcript: text,\\n    txtContent\\n  }\\n};\\n"},"id":"e2d3a4b7-fe59-4716-bce7-5bab44afe62d","name":"Build SRT Entry","type":"n8n-nodes-base.code","typeVersion":2,"position":[1696,1152]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\nOUT_DIR=\\"{{ $(\\"Prepare Job\\").item.json.jobWhisper }}\\"\\nOUT_FILE=\\"$OUT_DIR/{{ $(\\"Prepare Job\\").item.json.stem }}.srt\\"\\nmkdir -p \\"$OUT_DIR\\"\\n\\nNEW_WAV=\\"{{ $json.wavFile }}\\"\\nNEW_TXT=\\"{{ $json.txtFile }}\\"\\nOLD_WAV=\\"{{ $json.segFile }}\\"\\n# ✅ thay vì gán trực tiếp, dùng cat <<'EOF'\\nSRT_ENTRY=$(cat <<'EOF'\\n{{ $json.srtEntry || \\"\\" }}\\nEOF\\n)\\n\\nTXT_CONTENT=$(cat <<'EOF'\\n{{ $json.txtContent || \\"\\" }}\\nEOF\\n)\\n\\nSTART={{ $json.start }}\\nDUR={{ $json.duration }}\\nEND=$(awk \\"BEGIN{print $START+$DUR}\\")\\nSPEAKER=\\"{{ $json.speaker || \\"unknown\\" }}\\"\\n\\n# 📝 Debug\\necho \\"[DEBUG] TXT_CONTENT = $TXT_CONTENT\\" >&2\\necho \\"[DEBUG] Ghi đè file TXT: $NEW_TXT\\" >&2\\n\\n# 📝 ghi file TXT\\nprintf \\"Start: %s\\\\nEnd: %s\\\\nDuration: %s\\\\nSpeaker: %s\\\\n\\\\nTranscript:\\\\n%s\\\\n\\" \\\\\\n  \\"$START\\" \\"$END\\" \\"$DUR\\" \\"$SPEAKER\\" \\"$TXT_CONTENT\\" > \\"$NEW_TXT\\"\\n\\n# 🔄 Rename WAV\\nif [ -n \\"$NEW_WAV\\" ] && [ -f \\"$OLD_WAV\\" ]; then\\n  echo \\"[DEBUG] Rename WAV: $OLD_WAV -> $NEW_WAV\\" >&2\\n  mv -f \\"$OLD_WAV\\" \\"$NEW_WAV\\"\\nelse\\n  echo \\"[DEBUG] WAV rename skipped: OLD_WAV=$OLD_WAV, NEW_WAV=$NEW_WAV\\" >&2\\nfi\\n\\n# 🔄 Append SRT (luôn thêm dòng trắng sau entry)\\nif [ -n \\"$SRT_ENTRY\\" ] && [ -n \\"$OUT_FILE\\" ]; then\\n  printf \\"%s\\\\n\\\\n\\" \\"$SRT_ENTRY\\" >> \\"$OUT_FILE\\"\\n  echo \\"[DEBUG] Append SRT entry -> $OUT_FILE\\" >&2\\nfi\\n\\necho \\"$OUT_FILE\\"\\n'\\n"},"id":"56152a47-9aa3-4309-ba11-63499251a833","name":"Append to SRT","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1856,1152],"alwaysOutputData":true},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\n# 🚫 Vô hiệu hóa kết nối mạng HuggingFace\\nexport HF_HUB_OFFLINE=1\\nexport TRANSFORMERS_OFFLINE=1\\nexport PYANNOTE_DONT_USE_HF_TRANSFORMERS_CACHE=1\\n\\nPY={{ $(\\"Prepare Job\\").item.json.pythonExe || \\"python3\\" }}\\nSCR={{ $(\\"Prepare Job\\").item.json.separateSpeakersPy }}\\nRTTM={{ $(\\"Prepare Job\\").item.json.rttmPath }}\\nSRT={{ $(\\"Prepare Job\\").item.json.srtPath}}\\nAUDIO={{ $(\\"Prepare Job\\").item.json.demucsVocals }}\\nOUT={{ $(\\"Prepare Job\\").item.json.jobSpeakers }}\\n\\n# 🔄 SRT fallback\\nif [ -z \\"$SRT\\" ] || [ ! -s \\"$SRT\\" ]; then\\n  JOBROOT=\\"${AUDIO%/htdemucs/*}\\"\\n  STEM=\\"$(basename \\"$JOBROOT\\")\\"\\n  CAND1=\\"$JOBROOT/whisper/$STEM.srt\\"\\n  if [ -s \\"$CAND1\\" ]; then\\n    SRT=\\"$CAND1\\"\\n  else\\n    CAND2=\\"$(find \\"$JOBROOT/whisper\\" -type f -name \\"*.srt\\" -print -quit 2>/dev/null || true)\\"\\n    [ -n \\"$CAND2\\" ] && [ -s \\"$CAND2\\" ] && SRT=\\"$CAND2\\"\\n  fi\\nfi\\n\\n# 🔄 RTTM fallback\\nif [ -z \\"$RTTM\\" ] || [ ! -s \\"$RTTM\\" ]; then\\n  RTDIR=\\"$(dirname \\"$AUDIO\\")\\"\\n  RTALT=\\"$RTDIR/vocals.rttm\\"\\n  [ -s \\"$RTALT\\" ] && RTTM=\\"$RTALT\\"\\nfi\\n\\n# ✅ Kiểm tra input\\n[ -f \\"$SCR\\" ]  || { echo \\"[SEP][ERR] separate_speakers.py missing: $SCR\\" >&2; exit 1; }\\n[ -s \\"$RTTM\\" ] || { echo \\"[SEP][ERR] RTTM missing: $RTTM\\" >&2; exit 1; }\\n[ -s \\"$SRT\\" ]  || { echo \\"[SEP][ERR] SRT missing: $SRT\\" >&2; exit 1; }\\n[ -s \\"$AUDIO\\" ]|| { echo \\"[SEP][ERR] audio missing: $AUDIO\\" >&2; exit 1; }\\n\\nmkdir -p \\"$OUT\\"\\n\\n# === Giới hạn threads tối đa từ Prepare Job ===\\nMAX_THREADS=32\\n\\n# === Lấy tổng core thực tế ===\\nTOTAL=$(nproc --all)\\n\\n# === Đo CPU usage trong 1 giây ===\\nread cpu a b c idle rest < /proc/stat\\ntotal1=$((a+b+c+idle))\\nidle1=$idle\\nsleep 1\\nread cpu a b c idle rest < /proc/stat\\ntotal2=$((a+b+c+idle))\\nidle2=$idle\\ndiff_total=$((total2-total1))\\ndiff_idle=$((idle2-idle1))\\nUSAGE=$(( (100*(diff_total-diff_idle))/diff_total ))\\n\\n# === Tính số core rảnh ===\\nFREE=$(( TOTAL * (100 - USAGE) / 100 ))\\n\\n# === Chọn threads: free nhưng không vượt MAX_THREADS ===\\nif [ \\"$FREE\\" -gt \\"$MAX_THREADS\\" ]; then\\n  THREADS=$MAX_THREADS\\nelse\\n  THREADS=$FREE\\nfi\\nTHREADS=$(( THREADS > 0 ? THREADS : 1 ))\\n\\nexport OMP_NUM_THREADS=$THREADS\\nexport MKL_NUM_THREADS=$THREADS\\nexport OPENBLAS_NUM_THREADS=$THREADS\\nexport NUMEXPR_NUM_THREADS=$THREADS\\n\\necho \\"[SEP][INFO] Total cores=$TOTAL, load=${USAGE}%, free=$FREE, limit=$MAX_THREADS → dùng THREADS=$THREADS\\" >&2\\n\\n# 🚀 Chạy\\ntimeout 600 \\"$PY\\" \\"$SCR\\" --rttm \\"$RTTM\\" --srt \\"$SRT\\" --input_audio \\"$AUDIO\\" --output_dir \\"$OUT\\"\\n\\nprintf \\"%s\\" \\"$OUT\\"\\n'"},"id":"d8e55351-400f-479f-83b3-56fa7ba5ceab","name":"Separate Speakers - Optimized1","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1328,992]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\nRTTM={{ $(\\"Prepare Job\\").item.json.rttmPath }}\\n\\nawk '\\\\''$1==\\"SPEAKER\\" {print $4 \\"||\\" $5 \\"||\\" $8}'\\\\'' \\"$RTTM\\"\\n'\\n"},"id":"f50831c3-db61-42d9-8985-ae7701e1638e","name":"Parse RTTM","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[288,1152]},{"parameters":{"jsCode":"const pj = $('Prepare Job').item.json;\\nconst lines = String($json.stdout || '').split(/\\\\n/).filter(Boolean);\\n\\nreturn lines.map((l,i)=>{\\n  const [start,dur,spk] = l.split('||');\\n  const s = parseFloat(start);\\n  const d = parseFloat(dur);\\n  const e = s + d;\\n\\n  const segName = `Start_${s.toFixed(2)}s-End_${e.toFixed(2)}s-segment_${i}`;\\n\\n  return { \\n    json: { \\n      index: i + 1,   // ✅ gán số thứ tự ở đây\\n      start: s, \\n      duration: d, \\n      speaker: spk, \\n      segFile: `${pj.jobRoot}/segments/${segName}.wav`, \\n      txtFile: `${pj.jobRoot}/segments/${segName}.txt`\\n    }\\n  };\\n});\\n"},"id":"9c349a1c-c5f9-4f86-8b4c-612905ff3732","name":"Build Segments","type":"n8n-nodes-base.code","typeVersion":2,"position":[448,1152]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\nVOC={{ JSON.stringify($(\\"Prepare Job\\").item.json.demucsVocals) }}\\nSRT={{$('Prepare Job').item.json.srtPath}}\\n\\n[ -n \\"$VOC\\" ] && [ -s \\"$VOC\\" ] || { echo \\"[CHECK][ERR] Missing vocals.wav: $VOC\\" >&2; exit 1; }\\n[ -n \\"$SRT\\" ] && [ -s \\"$SRT\\" ] || { echo \\"[CHECK][ERR] Missing SRT: $SRT\\" >&2; exit 1; }\\n\\nRTTM_DIR=\\"$(dirname \\"$VOC\\")\\"\\nRTTM=\\"$RTTM_DIR/vocals.rttm\\"\\n[ -s \\"$RTTM\\" ] || { echo \\"[CHECK][ERR] Missing vocals.rttm: $RTTM\\" >&2; exit 1; }\\n\\nprintf \\"OK\\\\n\\"\\n'\\n"},"id":"1d74164f-e5fe-41ab-81bd-73a99d1332f9","name":"Check Inputs","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[992,992]},{"parameters":{"filePath":"={{ $json.stdout }}","dataPropertyName":"audioData"},"id":"467d1182-7be4-4c6a-8083-2f40e4844e9d","name":"Read Segment","type":"n8n-nodes-base.readBinaryFile","typeVersion":1,"position":[1152,1168]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\nIN={{ $(\\"Prepare Job\\").item.json.demucsVocals }}\\nSTART={{ $json.start }}\\nDUR={{ $json.duration }}\\nSPEAKER={{ $json.speaker || \\"unknown\\" }}\\n\\n# 🔢 Tính END\\nEND=$(awk \\"BEGIN{print $START+$DUR}\\")\\n\\nOUT_DIR=\\"$(dirname {{ $json.segFile }})\\"\\nmkdir -p \\"$OUT_DIR\\"\\n\\nBASE=\\"Start_${START}s-End_${END}s-segment\\"\\nWAV_OUT=\\"$OUT_DIR/${BASE}.wav\\"\\nTXT_OUT=\\"$OUT_DIR/${BASE}.txt\\"\\n\\n# 🎵 Cắt audio\\nffmpeg -hide_banner -loglevel error -y -i \\"$IN\\" -ss \\"$START\\" -t \\"$DUR\\" -ar 16000 -ac 1 \\"$WAV_OUT\\"\\n\\n# 📝 Metadata TXT (placeholder Transcript)\\n#{\\n # echo \\"Start: $START\\"\\n  #echo \\"End: $END\\"\\n  #echo \\"Duration: $DUR\\"\\n  #echo \\"Speaker: $SPEAKER\\"\\n  #echo \\"\\"\\n  #echo \\"Transcript:\\"\\n#} > \\"$TXT_OUT\\"\\n\\n# 👉 Xuất đường dẫn WAV cho Whisper\\necho \\"$WAV_OUT\\"\\n'\\n"},"id":"c92c3f5c-ebb1-4f4a-bc3d-8247b55395ef","name":"Cut Segment","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[976,1168]},{"parameters":{"method":"POST","url":"={{ $('Prepare Job').item.json.whisperUrl }}","sendBody":true,"contentType":"multipart-form-data","bodyParameters":{"parameters":[{"parameterType":"formBinaryData","name":"audio_file","inputDataFieldName":"audioData"}]},"options":{"timeout":600000}},"id":"7ea09e25-0792-4548-98b3-56063bd44dab","name":"Whisper","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[1328,1168],"retryOnFail":true,"waitBetweenTries":5000,"executeOnce":true},{"parameters":{},"type":"n8n-nodes-base.noOp","name":"Replace Me","typeVersion":1,"position":[2016,1152],"id":"e77143ff-0ef3-4623-9a16-f8e766f41d1c"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"id":"66f024c4-f76e-41c6-9aa5-8380995cdf36","leftValue":"={{ $json.data }}","rightValue":"","operator":{"type":"string","operation":"notEmpty","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.2,"position":[1504,1168],"id":"c7e4cbab-725e-4022-add9-c37306ab2f5d","name":"If"},{"parameters":{"jsCode":"// Lấy tất cả items từ index 360 trở đi\\nconst allItems = $input.all();\\nconst startFromIndex = 669;\\n\\nconst filteredItems = allItems.filter((item, index) => index >= startFromIndex);\\n\\n// ✅ Trả về json + giữ pairedItem\\nreturn filteredItems.map((item, index) => ({\\n  json: item.json,\\n  pairedItem: {\\n    item: item.pairedItem?.item ?? index  // giữ link tới item gốc\\n  }\\n}));\\n"},"id":"e0fa21fa-8254-4260-b2be-87e7fd404080","name":"StartLoop at","type":"n8n-nodes-base.code","typeVersion":2,"position":[608,1040]},{"parameters":{"chatId":"5584954476","text":"=🚨 **LỖI WORKFLOW** 🚨\\n\\n📋 **Chi tiết:**\\n• **Workflow:** {{ $json.workflow }}\\n• **Node lỗi:** {{ $json.node }}\\n• **Thời gian:** {{ $json.timestamp }}\\n• **ID thực thi:** {{ $json.executionId }}\\n\\n❌ **Thông báo lỗi:**\\n```\\n{{ $json.message }}\\n```\\n\\n🔍 **Stack trace:**\\n```\\n{{ $json.stack.substring(0, 500) }}{{ $json.stack.length > 500 ? '...' : '' }}\\n```\\n\\n⚡ *Được gửi từ n8n Error Handler*","additionalFields":{"parse_mode":"Markdown"}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[800,256],"id":"903dfc74-bd6c-4eca-977a-6a3054ce0be8","name":"Send Error Notification","webhookId":"898e9846-a753-43d5-b60d-de93dc28fdad","credentials":{"telegramApi":{"id":"3dY6VmwOtXaErnPU","name":"Telegram account"}}},{"parameters":{"mode":"runOnceForEachItem","jsCode":"// Log lỗi vào console để debug\\nconst errorData = $json;\\nconsole.log('=== N8N ERROR LOG ===');\\nconsole.log('Timestamp:', errorData.timestamp);\\nconsole.log('Workflow:', errorData.workflow);\\nconsole.log('Node:', errorData.node);\\nconsole.log('Message:', errorData.message);\\nconsole.log('Execution ID:', errorData.executionId);\\nconsole.log('Stack:', errorData.stack);\\nconsole.log('=====================');\\n\\nreturn { json: errorData };"},"id":"8e84216c-a102-4a90-8a51-38f46839680e","name":"Log Error","type":"n8n-nodes-base.code","typeVersion":2,"position":[800,384]},{"parameters":{"mode":"runOnceForEachItem","jsCode":"const e = $json;\\nconst errorData = {\\n  error: true,\\n  message: e.message || e.execution?.error?.message || 'Lỗi không xác định',\\n  node: e.execution?.error?.node?.name || 'Không rõ node',\\n  workflow: e.execution?.workflowData?.name || 'Workflow không rõ',\\n  executionId: e.execution?.id || 'N/A',\\n  timestamp: new Date().toLocaleString('vi-VN', {\\n    timeZone: 'Asia/Ho_Chi_Minh',\\n    year: 'numeric',\\n    month: '2-digit',\\n    day: '2-digit',\\n    hour: '2-digit',\\n    minute: '2-digit',\\n    second: '2-digit'\\n  }),\\n  stack: e.stack || e.execution?.error?.stack || 'Không có stack trace'\\n};\\n\\nreturn { json: errorData };"},"id":"60b2469b-5d82-458b-87c9-4f33e1b37440","name":"Error Handler1","type":"n8n-nodes-base.code","typeVersion":2,"position":[608,256]},{"parameters":{"content":"STEP:\\nNẾU LỖI THÌ THIẾT LẬP LẠI","height":220,"width":160,"color":3},"id":"8aaa65d1-2d52-4d85-9ea6-a03c187e41c3","name":"Sticky Note1","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[576,960]},{"parameters":{"content":"STEP: Nối nhiều file .wav thành 1 file","height":268,"width":1216,"color":4},"id":"b08e9a7e-6757-41c2-b3fc-ef8db8d5fa0f","name":"Sticky Note2","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[192,1456]},{"parameters":{"jsCode":"const fs = require('fs');\\nconst path = require('path');\\n\\nconst fileList = $input.first().json.stdout\\n  .trim()\\n  .split('\\\\n')\\n  .filter(f => f.length > 0)\\n  .map(line => {\\n    const parts = line.split('||');\\n    return parts.length === 2 ? parts[1] : line;\\n  });\\n\\nconst cfg = $('Set Config1').first().json;\\nconst outputPrefix = cfg.OutputDirectory;\\n\\n// ✅ Tạo thư mục cha nếu chưa có\\nfs.mkdirSync(outputPrefix, { recursive: true });\\n\\n// Build output path\\nconst outputPath = path.join(outputPrefix, 'combined.wav');\\n\\nreturn [{\\n  json: {\\n    files: fileList,\\n    outputPath,       // bắt buộc\\n    outputPrefix      // giữ lại nếu cần\\n  }\\n}];\\n"},"id":"59f6f14e-1b4c-4be4-8c90-2a1e0c1286d6","name":"Prepare File List","type":"n8n-nodes-base.code","typeVersion":2,"position":[848,1536]},{"parameters":{"command":"=bash -lc 'python3 {{ $(\\"Set Config1\\").item.json.concat_wav }} '\\\\''{{ JSON.stringify($json) }}'\\\\'''\\n"},"id":"b7d6a490-5e1a-4569-bbf5-f1682cc199a0","name":"Validate WAV Files","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1088,1536]},{"parameters":{"command":"=bash -lc 'find {{ JSON.stringify($(\\"Set Config1\\").item.json.inputDirectory) }} -maxdepth 1 -type f \\\\( -iname \\"*.mp4\\" -o -iname \\"*.mkv\\" -o -iname \\"*.mov\\" -o -iname \\"*.wav\\" -o -iname \\"*.mp3\\" -o -iname \\"*.m4a\\" \\\\) -printf \\"%f||%p\\\\n\\"'"},"id":"8f0e20c4-0bac-469f-9089-ee1fb792e61d","name":"List Input Files1","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[656,1536]},{"parameters":{"keepOnlySet":true,"values":{"string":[{"name":"inputDirectory","value":"/files/voice/OK"},{"name":"OutputDirectory","value":"/files/voice/OK/OK"},{"name":"concat_wav","value":"/scripts/concat_wav.py"}]},"options":{}},"id":"c81a2de4-df8a-41d9-ad78-1b45f2f8c9cd","name":"Set Config1","type":"n8n-nodes-base.set","typeVersion":2,"position":[464,1536]},{"parameters":{"command":"=bash -c '\\nset -euo pipefail\\n\\nAP=\\"{{ $json.stdout }}\\"                              # input .wav\\nOUT=\\"{{ $('Prepare Job').item.json.jobRoot }}\\"       # job root\\nCheck_OUT=\\"{{ $('Prepare Job').item.json.demucsVocals }}\\"  # file vocals.wav mong muốn\\nDEM=demucs\\n\\n# === Bước 1: Skip nếu file có sẵn và >5KB ===\\nif [ -f \\"$Check_OUT\\" ] && [ \\"$(stat -c%s \\"$Check_OUT\\")\\" -gt 5120 ]; then\\n  echo \\"[DEM][INFO] Found existing file: $Check_OUT, skip separation.\\" >&2\\n  printf \\"%s\\\\n\\" \\"$Check_OUT\\"\\n  exit 0\\nfi\\n\\n# === Bước 2: Thiết lập thread cố định ===\\nTHREADS=32\\nexport OMP_NUM_THREADS=$THREADS\\nexport MKL_NUM_THREADS=$THREADS\\nexport OPENBLAS_NUM_THREADS=$THREADS\\nexport NUMEXPR_NUM_THREADS=$THREADS\\nJOBS=\\"-j $THREADS\\"\\n\\nOUTDIR=$(dirname \\"$OUT\\")\\nmkdir -p \\"$OUTDIR\\"\\n\\n# Ép TMPDIR vào thư mục host đã mount\\nTMPROOT=\\"/files/voice/temp/demucs_cache\\"\\nmkdir -p \\"$TMPROOT\\"\\nTMPDIR=$(mktemp -d -p \\"$TMPROOT\\")\\n\\necho \\"[DEM][INFO] Running Demucs on $AP → TMPDIR=$TMPDIR\\" >&2\\nDEMUCS_OUTPUT=$(\\"$DEM\\" -d cpu -n htdemucs_6s --two-stems=vocals $JOBS \\"$AP\\" -o \\"$TMPDIR\\" 2>&1 || true)\\n\\nVOC=$(find \\"$TMPDIR\\" -type f -iname vocals.wav -print -quit 2>/dev/null || true)\\n\\nif [ ! -s \\"$VOC\\" ]; then\\n  echo \\"[DEM][ERR] vocals.wav not found in TMPDIR=$TMPDIR\\" >&2\\n  echo \\"[DEM][DEBUG] Demucs output was: $DEMUCS_OUTPUT\\" >&2\\n  rm -rf \\"$TMPDIR\\"\\n  exit 1\\nfi\\n\\n# === Move kết quả về đúng Check_OUT ===\\nmkdir -p \\"$(dirname \\"$Check_OUT\\")\\"\\nmv -f \\"$VOC\\" \\"$Check_OUT\\"\\n\\n# Dọn dẹp TMPDIR\\nrm -rf \\"$TMPDIR\\"\\n\\nprintf \\"%s\\\\n\\" \\"$Check_OUT\\"\\n'"},"id":"df753e52-0dfc-4b20-9dc5-cfe0f8f5a8bf","name":"Demucs Separate - Optimized","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1488,784]},{"parameters":{"command":"=bash -c '\\nset -euo pipefail\\n\\nVOC=\\"{{ $json.stdout }}\\"\\nPY=\\"{{ $(\\"Prepare Job\\").item.json.pythonExe }}\\"\\nSCR=\\"{{ $(\\"Prepare Job\\").item.json.Diarize_Pyannote }}\\"\\nHF_TOKEN=\\"$HUGGINGFACE_ACCESS_TOKEN\\"\\n\\nOUTDIR=\\"$(dirname \\"$VOC\\")\\"\\nmkdir -p \\"$OUTDIR\\"\\nRTTM_FILE=\\"$OUTDIR/vocals.rttm\\"\\n\\n# === Skip nếu RTTM có sẵn và >5KB ===\\nif [ -f \\"$RTTM_FILE\\" ] && [ \\"$(stat -c%s \\"$RTTM_FILE\\")\\" -gt 5120 ]; then\\n  echo \\"[DIAR][INFO] Found valid RTTM (>5KB): $RTTM_FILE, skip diarization.\\" >&2\\n  printf \\"%s\\\\n\\" \\"$RTTM_FILE\\"\\n  exit 0\\nfi\\n\\n# === Giới hạn threads tối đa ===\\nMAX_THREADS=32\\n\\n# === Lấy số core thực tế ===\\nTOTAL=$(nproc --all)\\n\\n# === Đo CPU usage trong 1 giây ===\\nread cpu a b c idle rest < /proc/stat\\ntotal1=$((a+b+c+idle))\\nidle1=$idle\\nsleep 1\\nread cpu a b c idle rest < /proc/stat\\ntotal2=$((a+b+c+idle))\\nidle2=$idle\\ndiff_total=$((total2-total1))\\ndiff_idle=$((idle2-idle1))\\nUSAGE=$(( (100*(diff_total-diff_idle))/diff_total ))\\n\\n# === Tính số core rảnh ===\\nFREE=$(( TOTAL * (100 - USAGE) / 100 ))\\n\\n# === Chọn threads: free nhưng không vượt MAX_THREADS ===\\nif [ \\"$FREE\\" -gt \\"$MAX_THREADS\\" ]; then\\n  THREADS=$MAX_THREADS\\nelse\\n  THREADS=$FREE\\nfi\\nif [ \\"$THREADS\\" -le 0 ]; then\\n  THREADS=1\\nfi\\n\\necho \\"[DIAR][INFO] Total cores=$TOTAL, CPU load=${USAGE}%, free=$FREE, limit=$MAX_THREADS → chọn THREADS=$THREADS\\" >&2\\n\\n# === Xuất env cho PyTorch ===\\nexport OMP_NUM_THREADS=$THREADS\\nexport MKL_NUM_THREADS=$THREADS\\nexport OPENBLAS_NUM_THREADS=$THREADS\\nexport NUMEXPR_NUM_THREADS=$THREADS\\n\\n# === Kiểm tra script tồn tại ===\\nif [ ! -f \\"$SCR\\" ]; then\\n  echo \\"[DIAR][ERR] Missing diarize script: $SCR\\" >&2\\n  exit 1\\nfi\\n\\n# === Chạy diarization ===\\ntimeout 10800 \\"$PY\\" -u \\"$SCR\\" --input \\"$VOC\\" --out_dir \\"$OUTDIR\\" --token \\"$HF_TOKEN\\"\\n\\n# === Fallback RTTM nếu diarization thất bại ===\\nif [ ! -s \\"$RTTM_FILE\\" ]; then\\n  DURATION=$(ffprobe -v quiet -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 \\"$VOC\\" 2>/dev/null || echo \\"60\\")\\n  echo \\"SPEAKER vocals 1 0.000 $DURATION <NA> <NA> SPEAKER_00 <NA> <NA>\\" > \\"$RTTM_FILE\\"\\n  echo \\"[DIAR][WARN] RTTM fallback created\\" >&2\\nfi\\n\\nprintf \\"%s\\\\n\\" \\"$RTTM_FILE\\"\\n'\\n"},"id":"f7538085-1414-4ab1-94a1-d3c323e9318c","name":"Diarization by CPU (pyannote)","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[2096,768]},{"parameters":{"command":"=bash -c '\\nset -euo pipefail\\n\\nRAW_OUTPUT=\\"{{ $json.stdout }}\\"\\nVOC=$(echo \\"$RAW_OUTPUT\\" | grep -o \\"/files/.*/vocals\\\\.wav\\" || echo \\"$RAW_OUTPUT\\")\\n\\nPY=\\"{{ $('Prepare Job').item.json.pythonExe }}\\"\\nSCR=\\"{{ $('Prepare Job').item.json.Diarpy_Silero }}\\"\\n\\n# Kiểm tra file vocals.wav tồn tại\\nif [ ! -s \\"$VOC\\" ]; then\\n  echo \\"[DIAR][ERR] vocals.wav missing or empty: $VOC\\" >&2\\n  echo \\"[DIAR][DEBUG] Raw output was: $RAW_OUTPUT\\" >&2\\n  exit 1\\nfi\\n\\n# Kiểm tra script diarize_silero.py tồn tại\\nif [ ! -f \\"$SCR\\" ]; then\\n  echo \\"[DIAR][ERR] diarize_silero.py missing: $SCR\\" >&2\\n  exit 1\\nfi\\n\\nOUTDIR=\\"$(dirname \\"$VOC\\")\\"\\nmkdir -p \\"$OUTDIR\\"\\n\\n# === Bước 2: Thiết lập thread cố định ===\\nif [ -n \\"${NODE_THREADS:-}\\" ]; then\\n  THREADS=\\"$NODE_THREADS\\"\\nelse\\n  TOTAL=$(nproc --all 2>/dev/null || echo 4)\\n  THREADS=$(( TOTAL / 2 ))\\n  [ \\"$THREADS\\" -lt 1 ] && THREADS=1\\nfi\\n\\nexport OMP_NUM_THREADS=$THREADS\\nexport MKL_NUM_THREADS=$THREADS\\nexport OPENBLAS_NUM_THREADS=$THREADS\\nexport NUMEXPR_NUM_THREADS=$THREADS\\nexport VECLIB_MAXIMUM_THREADS=$THREADS\\n\\necho \\"[DIAR][INFO] Using $THREADS threads (total CPU: $(nproc --all))\\" >&2\\n\\n# Thiết lập cache\\nNUMBA_CACHE_DIR=\\"/files/voice/tmp/silero_cache/numba\\"\\nHF_HOME=\\"/files/voice/tmp/silero_cache/hf\\"\\nTORCH_HOME=\\"/files/voice/tmp/silero_cache/torch\\"\\nmkdir -p \\"$NUMBA_CACHE_DIR\\" \\"$HF_HOME\\" \\"$TORCH_HOME\\"\\nexport NUMBA_CACHE_DIR HF_HOME TORCH_HOME\\n\\n# Chạy diarization\\nCMD=(\\"$PY\\" -u \\"$SCR\\" --input \\"$VOC\\" --out_dir \\"$OUTDIR\\" --num-threads \\"$THREADS\\")\\n\\necho \\"[DIAR][INFO] Running Silero diarization for: $VOC\\" >&2\\ntimeout 7200 \\"${CMD[@]}\\"\\n\\n# Kiểm tra kết quả\\nRTTM_FILE=\\"$OUTDIR/vocals.rttm\\"\\nif [ ! -s \\"$RTTM_FILE\\" ]; then\\n  echo \\"[DIAR][ERR] RTTM not created, fallback to single speaker\\" >&2\\n  DURATION=$(ffprobe -v quiet -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 \\"$VOC\\" 2>/dev/null || echo \\"60\\")\\n  echo \\"SPEAKER vocals 1 0.000 $DURATION <NA> <NA> SPEAKER_00 <NA> <NA>\\" > \\"$RTTM_FILE\\"\\nfi\\n\\necho \\"[DIAR][SUCCESS] RTTM ready: $RTTM_FILE\\" >&2\\n# 👉 Output clean chỉ có đường dẫn RTTM\\necho \\"$RTTM_FILE\\"\\n'\\n"},"id":"fa978627-fa01-4125-af99-1b752d277653","name":"Diarization (Silero) - CPU Optimized","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1872,800]},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"id":"66f024c4-f76e-41c6-9aa5-8380995cdf36","leftValue":"={{ $('Set Config').item.json['Enable Pyannote '] }}","rightValue":"","operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.2,"position":[1664,784],"id":"835fd6e3-4dc7-4789-8cfd-547a025277dd","name":"Enable pyannote ?"},{"parameters":{"command":"==bash -c '\\nset -euo pipefail\\n\\nVOC=\\"{{ $json.stdout }}\\"\\nPY=\\"{{ $(\\"Prepare Job\\").item.json.pythonExe }}\\"\\nSCR=\\"/scripts/diarize_whisperx.py\\"\\n\\nOUTDIR=\\"$(dirname \\"$VOC\\")\\"\\nmkdir -p \\"$OUTDIR\\"\\nRTTM_FILE=\\"$OUTDIR/vocals.rttm\\"\\n\\n# === Skip nếu RTTM có sẵn và >5KB ===\\nif [ -f \\"$RTTM_FILE\\" ] && [ \\"$(stat -c%s \\"$RTTM_FILE\\")\\" -gt 5120 ]; then\\n  echo \\"[WHISPERX][INFO] Found valid RTTM (>5KB): $RTTM_FILE, skip diarization.\\" >&2\\n  printf \\"%s\\\\n\\" \\"$RTTM_FILE\\"\\n  exit 0\\nfi\\n\\n# === Chạy WhisperX ===\\necho \\"[WHISPERX][INFO] Running WhisperX diarization...\\" >&2\\ntimeout 10800 \\"$PY\\" -u \\"$SCR\\" --