ers":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":1},"conditions":[{"leftValue":"={{ $json.enableRVC }}","rightValue":"","operator":{"type":"boolean","operation":"isTrue"},"id":"enable-rvc-bool"},{"id":"02f047da-ecdc-4344-9044-deed41606e8c","leftValue":"","rightValue":"","operator":{"type":"string","operation":"equals","name":"filter.operator.equals"}}],"combinator":"and"},"options":{}},"id":"35d5dd90-e245-49b3-a516-c92049e3a656","name":"Enable RVC?","type":"n8n-nodes-base.if","typeVersion":2,"position":[1232,336]},{"parameters":{"content":"STEP: workflow n8n ","height":780,"width":2032,"color":4},"id":"e8573cbd-ddac-4a98-83e0-bdc45efdeece","name":"Sticky Note","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[192,624]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\nIN={{ JSON.stringify($json.src) }}\\nOUT={{ JSON.stringify($json.inputWav) }}\\nFF={{ JSON.stringify($json.ffmpegCmd || \\"ffmpeg\\") }}\\n\\n# === Skip nếu file có sẵn và >5KB ===\\n# Kiểm tra file tồn tại và kích thước >5KB thì skip\\nif [ -f \\"$OUT\\" ]; then\\n  size=$(wc -c \\\\< \\"$OUT\\" 2>/dev/null || echo 0)\\n  if [ \\"$size\\" -gt 5120 ]; then\\n    echo \\"[FFMPEG][INFO] Found existing output: $OUT, skip re-extract.\\" >&2\\n    printf \\"%s\\\\n\\" \\"$OUT\\"\\n    exit 0\\n  fi\\nfi\\n\\nMAX_THREADS=32\\nTOTAL=$(nproc --all 2>/dev/null || echo 1)\\n\\n# === Đo CPU usage qua /proc/stat ===\\nif [ -r /proc/stat ]; then\\n  read cpu a b c idle rest < /proc/stat\\n  total1=$((a+b+c+idle)); idle1=$idle\\n  sleep 1\\n  read cpu a b c idle rest < /proc/stat\\n  total2=$((a+b+c+idle)); idle2=$idle\\n  diff_total=$((total2-total1)); diff_idle=$((idle2-idle1))\\n  if [ \\"$diff_total\\" -gt 0 ]; then\\n    USAGE=$(( (100*(diff_total-diff_idle))/diff_total ))\\n  else\\n    USAGE=0\\n  fi\\n  FREE=$(( TOTAL * (100 - USAGE) / 100 ))\\nelse\\n  USAGE=0; FREE=$TOTAL\\nfi\\n\\nif [ \\"$FREE\\" -gt \\"$MAX_THREADS\\" ]; then THREADS=$MAX_THREADS; else THREADS=$FREE; fi\\nif [ \\"$THREADS\\" -le 0 ]; then THREADS=1; fi\\n\\n# Tạo thư mục output nếu chưa có\\nmkdir -p \\"$(dirname \\"$OUT\\")\\"\\n\\necho \\"[FFMPEG][INFO] Total=$TOTAL, load=${USAGE}%, free=$FREE → THREADS=$THREADS\\" >&2\\n\\n# Chuyển đổi audio\\nif \\"$FF\\" -hide_banner -loglevel error -nostdin -y \\\\\\n   -i \\"$IN\\" -vn -ar 16000 -ac 1 -threads \\"$THREADS\\" \\"$OUT\\"; then\\n  echo \\"[FFMPEG][SUCCESS] Converted: $OUT\\" >&2\\nelse\\n  echo \\"[FFMPEG][WARN] Retry without thread limit\\" >&2\\n  if \\"$FF\\" -hide_banner -loglevel error -nostdin -y \\\\\\n      -i \\"$IN\\" -vn -ar 16000 -ac 1 \\"$OUT\\"; then\\n    echo \\"[FFMPEG][SUCCESS] Converted (retry): $OUT\\" >&2\\n  else\\n    echo \\"[FFMPEG][ERROR] Failed to convert: $IN\\" >&2\\n    exit 1\\n  fi\\nfi\\n\\necho \\"$OUT\\"\\nprintf \\"%s\\\\n\\" \\"$VOC\\"\\n'"},"id":"97ed61c0-6f29-4e8d-a9ae-1b50437acc08","name":"Extract 16k Mono WAV - Optimized","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1296,656]},{"parameters":{"command":"=bash -lc 'find {{ JSON.stringify($(\\"Set Config\\").item.json.inDir) }} -maxdepth 1 -type f \\\\( -iname \\"*.mp4\\" -o -iname \\"*.mkv\\" -o -iname \\"*.mov\\" -o -iname \\"*.wav\\" -o -iname \\"*.mp3\\" -o -iname \\"*.m4a\\" \\\\) -printf \\"%f||%p\\\\n\\"'"},"id":"212d9b2c-3ce7-40cb-af05-3cd88a827561","name":"List Input Files","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[832,784]},{"parameters":{"keepOnlySet":true,"values":{"string":[{"name":"inDir","value":"/files/voice/input"},{"name":"outDir","value":"/files/voice/output"},{"name":"demucsCmd","value":"demucs"},{"name":"ffmpegCmd","value":"ffmpeg"},{"name":"pythonExe","value":"python3"},{"name":"diarPy","value":"/scripts/diarize.py"},{"name":"separateSpeakersPy","value":"/scripts/separate_speakers.py"},{"name":"rvcPy","value":"/scripts/batch_rvc.py"},{"name":"mergePy","value":"/scripts/merge.py"},{"name":"rvcModel","value":"/rvc-models/jackie.pth"},{"name":"rvcIndex","value":"/rvc-models/jackie.index"},{"name":"rvcF0Method","value":"harvest"},{"name":"rvcTranspose","value":"0"},{"name":"whisperUrl","value":"http://whisper:9000/asr?task=transcribe&language=vi"}],"boolean":[{"name":"enableRVC","value":true}]},"options":{}},"id":"ad777e7a-93d1-406a-bb13-86207af7000e","name":"Set Config","type":"n8n-nodes-base.set","typeVersion":2,"position":[608,784]},{"parameters":{},"id":"36adeff5-8cbe-467b-bb54-8a83b60fb430","name":"Start","type":"n8n-nodes-base.manualTrigger","typeVersion":1,"position":[256,784],"disabled":true},{"parameters":{"jsCode":"// Build per-file job workspace name: name, name1, name2...\\nconst lines = String($json.stdout || '').split(/\\\\r?\\\\n/).map(s=>s.trim()).filter(Boolean);\\nif (!lines.length) return [];\\n\\nconst cfg = $('Set Config').first().json;\\n\\nreturn lines.map(row=>{\\n  const [base, full] = row.split('||');\\n  const stemRaw = (base || '').replace(/\\\\.[^.]+$/, '');\\n  \\n  // Cải tiến: Sử dụng regex mạnh hơn để loại bỏ tất cả các ký tự không an toàn\\n  // và giới hạn độ dài tối đa 100 ký tự để tránh lỗi string quá dài\\n  let stem = stemRaw.replace(/[^a-zA-Z0-9-]/g, '_')\\n                   .replace(/_{2,}/g, '_')\\n                   .replace(/^_+|_+$/g, '');\\n  \\n  // Giới hạn độ dài tối đa 100 ký tự\\n  if (stem.length > 20) {\\n    stem = stem.substring(0, 20);\\n  }\\n\\n  const jobRoot = `${cfg.outDir}/${stem}`;\\n  const inputWav = `${jobRoot}/htdemucs_6s/input_16k_mono.wav`;\\n  const demucsVocals = `${jobRoot}/htdemucs_6s/input_16k_mono/vocals.wav`;\\n  const rttmPath = `${jobRoot}/htdemucs_6s/input_16k_mono/vocals.rttm`;\\n  const jobWhisper = `${jobRoot}/whisper`;\\n  const jobSpeakers = `${jobRoot}/speakers`;\\n  const srtPath = `${jobWhisper}/${stem}.srt`;\\n\\n  return { json: {\\n    src: full,\\n    base,\\n    stem,\\n    jobRoot,\\n    jobWhisper,\\n    jobSpeakers,\\n    inputWav,\\n    demucsVocals,\\n    rttmPath,\\n    srtPath,\\n    inDir: cfg.inDir,\\n    outDir: cfg.outDir,\\n    demucsCmd: cfg.demucsCmd,\\n    ffmpegCmd: cfg.ffmpegCmd,\\n    pythonExe: cfg.pythonExe,\\n    diarPy: cfg.diarPy,\\n    separateSpeakersPy: cfg.separateSpeakersPy,\\n    rvcPy: cfg.rvcPy,\\n    mergePy: cfg.mergePy,\\n    rvcModel: cfg.rvcModel,\\n    rvcIndex: cfg.rvcIndex,\\n    rvcF0Method: cfg.rvcF0Method,\\n    rvcTranspose: cfg.rvcTranspose,\\n    whisperUrl: cfg.whisperUrl,\\n    enableRVC: cfg.enableRVC === undefined ? true : !!cfg.enableRVC\\n  }};\\n});"},"id":"967e068b-f4a1-4dd7-a514-686b54fe0046","name":"Prepare Job","type":"n8n-nodes-base.code","typeVersion":2,"position":[1056,784]},{"parameters":{"chatId":"5584954476","text":"=Công việc tách speaker đã hoàn tất !","additionalFields":{},"path":"bb9f3f8b-0e3e-44c0-a93c-9071d472406a"},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[1680,992],"id":"3503af73-1d41-4148-9c5c-66d44437656a","name":"Send a text message1","webhookId":"bb9f3f8b-0e3e-44c0-a93c-9071d472406a","credentials":{"telegramApi":{"id":"3dY6VmwOtXaErnPU","name":"Telegram account"}}},{"parameters":{"options":{}},"id":"f98804c4-99e1-4d89-b22b-2d7828fe0a5f","name":"Loop Segments","type":"n8n-nodes-base.splitInBatches","typeVersion":3,"position":[800,1152]},{"parameters":{"mode":"runOnceForEachItem","jsCode":"function fmt(t) {\\n  const h = String(Math.floor(t / 3600)).padStart(2, '0');\\n  const m = String(Math.floor((t % 3600) / 60)).padStart(2, '0');\\n  const s = String(Math.floor(t % 60)).padStart(2, '0');\\n  return `${h}:${m}:${s},000`;\\n}\\n\\n// === Lấy transcript ===\\nconst text = $json.text \\n          || $json.transcription \\n          || $json.data?.text \\n          || $json.data \\n          || '';\\n\\nif (!text.trim()) {\\n  return { json: { skip: true } };\\n}\\n\\n// === Metadata gốc từ Loop Segments ===\\nconst seg = $('Loop Segments').item.json;\\nconst st = parseFloat(seg.start);\\nconst dur = parseFloat(seg.duration);\\n\\nif (isNaN(st) || isNaN(dur) || dur <= 0) {\\n  return { json: { skip: true } };\\n}\\n\\nconst et = st + dur;\\nconst idx = seg.index || 1;   // lấy index từ Build Segments\\n\\n// === Hàm chuẩn hóa slug ===\\nfunction slugify(str) {\\n  if (typeof str !== 'string') return ''; // Xử lý đầu vào không phải string\\n\\n  return str\\n    .normalize('NFD') // Tách ký tự thành base và dấu\\n    .replace(/[\\\\u0300-\\\\u036f]/g, '') // Loại bỏ dấu\\n    .replace(/[đĐ]/g, (match) => match === 'đ' ? 'd' : 'D') // Xử lý đ/Đ\\n    .replace(/['’`]/g, '') // Loại bỏ dấu apostrophe\\n    .replace(/[^\\\\p{L}\\\\p{N} ]/gu, ' ') // Giữ lại chỉ chữ cái, số và khoảng trắng (Unicode property escapes)\\n    .trim()\\n    .replace(/\\\\s+/g, ' ') // Gom nhiều khoảng trắng\\n    .split(' ')\\n    .filter(word => word.length > 0) // Lọc từ rỗng\\n    .slice(0, 20)\\n    .join('_');\\n}\\n\\nconst snippet = slugify(text) || \\"segment\\";\\n\\n// === Tạo tên file mới ===\\nconst dir = seg.segFile.replace(/\\\\/[\\\\w.-]+$/, '');\\nconst base = `Start_${st.toFixed(3)}s-End_${et.toFixed(3)}s-${snippet}_${idx}`;\\n\\nconst newWav = `${dir}/${base}.wav`;\\nconst newTxt = `${dir}/${base}.txt`;\\nconst segFile = $('Read Segment').item.json.stdout;\\nconst txtContent = text.replace(/\\\\r?\\\\n/g, \\" \\");\\n\\n// === Entry SRT ===\\nconst srt = `${idx}\\n${fmt(st)} --> ${fmt(et)}\\n${text}\\n\\n`;\\n\\n// === Output JSON đầy đủ ===\\nreturn {\\n  json: {\\n    ...seg,            // giữ metadata gốc\\n    index: idx,        // luôn có index\\n    start: st,\\n    duration: dur,\\n    segFile: segFile,\\n\\n    srtEntry: srt,\\n    wavFile: newWav,\\n    txtFile: newTxt,\\n    transcript: text,\\n    txtContent\\n  }\\n};\\n"},"id":"88ccfea5-fb93-45de-a644-c47f70bd24a4","name":"Build SRT Entry","type":"n8n-nodes-base.code","typeVersion":2,"position":[1696,1152]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\nOUT_DIR=\\"{{ $(\\"Prepare Job\\").item.json.jobWhisper }}\\"\\nOUT_FILE=\\"$OUT_DIR/{{ $(\\"Prepare Job\\").item.json.stem }}.srt\\"\\nmkdir -p \\"$OUT_DIR\\"\\n\\nNEW_WAV=\\"{{ $json.wavFile }}\\"\\nNEW_TXT=\\"{{ $json.txtFile }}\\"\\nOLD_WAV=\\"{{ $json.segFile }}\\"\\n# ✅ thay vì gán trực tiếp, dùng cat <<'EOF'\\nSRT_ENTRY=$(cat <<'EOF'\\n{{ $json.srtEntry || \\"\\" }}\\nEOF\\n)\\n\\nTXT_CONTENT=$(cat <<'EOF'\\n{{ $json.txtContent || \\"\\" }}\\nEOF\\n)\\n\\nSTART={{ $json.start }}\\nDUR={{ $json.duration }}\\nEND=$(awk \\"BEGIN{print $START+$DUR}\\")\\nSPEAKER=\\"{{ $json.speaker || \\"unknown\\" }}\\"\\n\\n# 📝 Debug\\necho \\"[DEBUG] TXT_CONTENT = $TXT_CONTENT\\" >&2\\necho \\"[DEBUG] Ghi đè file TXT: $NEW_TXT\\" >&2\\n\\n# 📝 ghi file TXT\\nprintf \\"Start: %s\\\\nEnd: %s\\\\nDuration: %s\\\\nSpeaker: %s\\\\n\\\\nTranscript:\\\\n%s\\\\n\\" \\\\\\n  \\"$START\\" \\"$END\\" \\"$DUR\\" \\"$SPEAKER\\" \\"$TXT_CONTENT\\" > \\"$NEW_TXT\\"\\n\\n# 🔄 Rename WAV\\nif [ -n \\"$NEW_WAV\\" ] && [ -f \\"$OLD_WAV\\" ]; then\\n  echo \\"[DEBUG] Rename WAV: $OLD_WAV -> $NEW_WAV\\" >&2\\n  mv -f \\"$OLD_WAV\\" \\"$NEW_WAV\\"\\nelse\\n  echo \\"[DEBUG] WAV rename skipped: OLD_WAV=$OLD_WAV, NEW_WAV=$NEW_WAV\\" >&2\\nfi\\n\\n# 🔄 Append SRT (luôn thêm dòng trắng sau entry)\\nif [ -n \\"$SRT_ENTRY\\" ] && [ -n \\"$OUT_FILE\\" ]; then\\n  printf \\"%s\\\\n\\\\n\\" \\"$SRT_ENTRY\\" >> \\"$OUT_FILE\\"\\n  echo \\"[DEBUG] Append SRT entry -> $OUT_FILE\\" >&2\\nfi\\n\\necho \\"$OUT_FILE\\"\\n'\\n"},"id":"eec4732e-f3ae-46cb-8e8f-b608bbc7e9ee","name":"Append to SRT","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1856,1152],"alwaysOutputData":true},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\n# 🚫 Vô hiệu hóa kết nối mạng HuggingFace\\nexport HF_HUB_OFFLINE=1\\nexport TRANSFORMERS_OFFLINE=1\\nexport PYANNOTE_DONT_USE_HF_TRANSFORMERS_CACHE=1\\n\\nPY={{ $(\\"Prepare Job\\").item.json.pythonExe || \\"python3\\" }}\\nSCR={{ $(\\"Prepare Job\\").item.json.separateSpeakersPy }}\\nRTTM={{ $(\\"Prepare Job\\").item.json.rttmPath }}\\nSRT={{ $(\\"Prepare Job\\").item.json.srtPath}}\\nAUDIO={{ $(\\"Prepare Job\\").item.json.demucsVocals }}\\nOUT={{ $(\\"Prepare Job\\").item.json.jobSpeakers }}\\n\\n# 🔄 SRT fallback\\nif [ -z \\"$SRT\\" ] || [ ! -s \\"$SRT\\" ]; then\\n  JOBROOT=\\"${AUDIO%/htdemucs/*}\\"\\n  STEM=\\"$(basename \\"$JOBROOT\\")\\"\\n  CAND1=\\"$JOBROOT/whisper/$STEM.srt\\"\\n  if [ -s \\"$CAND1\\" ]; then\\n    SRT=\\"$CAND1\\"\\n  else\\n    CAND2=\\"$(find \\"$JOBROOT/whisper\\" -type f -name \\"*.srt\\" -print -quit 2>/dev/null || true)\\"\\n    [ -n \\"$CAND2\\" ] && [ -s \\"$CAND2\\" ] && SRT=\\"$CAND2\\"\\n  fi\\nfi\\n\\n# 🔄 RTTM fallback\\nif [ -z \\"$RTTM\\" ] || [ ! -s \\"$RTTM\\" ]; then\\n  RTDIR=\\"$(dirname \\"$AUDIO\\")\\"\\n  RTALT=\\"$RTDIR/vocals.rttm\\"\\n  [ -s \\"$RTALT\\" ] && RTTM=\\"$RTALT\\"\\nfi\\n\\n# ✅ Kiểm tra input\\n[ -f \\"$SCR\\" ]  || { echo \\"[SEP][ERR] separate_speakers.py missing: $SCR\\" >&2; exit 1; }\\n[ -s \\"$RTTM\\" ] || { echo \\"[SEP][ERR] RTTM missing: $RTTM\\" >&2; exit 1; }\\n[ -s \\"$SRT\\" ]  || { echo \\"[SEP][ERR] SRT missing: $SRT\\" >&2; exit 1; }\\n[ -s \\"$AUDIO\\" ]|| { echo \\"[SEP][ERR] audio missing: $AUDIO\\" >&2; exit 1; }\\n\\nmkdir -p \\"$OUT\\"\\n\\n# === Giới hạn threads tối đa từ Prepare Job ===\\nMAX_THREADS=32\\n\\n# === Lấy tổng core thực tế ===\\nTOTAL=$(nproc --all)\\n\\n# === Đo CPU usage trong 1 giây ===\\nread cpu a b c idle rest < /proc/stat\\ntotal1=$((a+b+c+idle))\\nidle1=$idle\\nsleep 1\\nread cpu a b c idle rest < /proc/stat\\ntotal2=$((a+b+c+idle))\\nidle2=$idle\\ndiff_total=$((total2-total1))\\ndiff_idle=$((idle2-idle1))\\nUSAGE=$(( (100*(diff_total-diff_idle))/diff_total ))\\n\\n# === Tính số core rảnh ===\\nFREE=$(( TOTAL * (100 - USAGE) / 100 ))\\n\\n# === Chọn threads: free nhưng không vượt MAX_THREADS ===\\nif [ \\"$FREE\\" -gt \\"$MAX_THREADS\\" ]; then\\n  THREADS=$MAX_THREADS\\nelse\\n  THREADS=$FREE\\nfi\\nTHREADS=$(( THREADS > 0 ? THREADS : 1 ))\\n\\nexport OMP_NUM_THREADS=$THREADS\\nexport MKL_NUM_THREADS=$THREADS\\nexport OPENBLAS_NUM_THREADS=$THREADS\\nexport NUMEXPR_NUM_THREADS=$THREADS\\n\\necho \\"[SEP][INFO] Total cores=$TOTAL, load=${USAGE}%, free=$FREE, limit=$MAX_THREADS → dùng THREADS=$THREADS\\" >&2\\n\\n# 🚀 Chạy\\ntimeout 600 \\"$PY\\" \\"$SCR\\" --rttm \\"$RTTM\\" --srt \\"$SRT\\" --input_audio \\"$AUDIO\\" --output_dir \\"$OUT\\"\\n\\nprintf \\"%s\\" \\"$OUT\\"\\n'"},"id":"ac470239-2378-4cd3-80bc-b9a55477b355","name":"Separate Speakers - Optimized1","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1328,992]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\nRTTM={{ $(\\"Prepare Job\\").item.json.rttmPath }}\\n\\nawk '\\\\''$1==\\"SPEAKER\\" {print $4 \\"||\\" $5 \\"||\\" $8}'\\\\'' \\"$RTTM\\"\\n'\\n"},"id":"93e0223f-0158-4c0d-88bb-cd127fcf5f29","name":"Parse RTTM","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[288,1152]},{"parameters":{"jsCode":"const pj = $('Prepare Job').item.json;\\nconst lines = String($json.stdout || '').split(/\\\\n/).filter(Boolean);\\n\\nreturn lines.map((l,i)=>{\\n  const [start,dur,spk] = l.split('||');\\n  const s = parseFloat(start);\\n  const d = parseFloat(dur);\\n  const e = s + d;\\n\\n  const segName = `Start_${s.toFixed(2)}s-End_${e.toFixed(2)}s-segment_${i}`;\\n\\n  return { \\n    json: { \\n      index: i + 1,   // ✅ gán số thứ tự ở đây\\n      start: s, \\n      duration: d, \\n      speaker: spk, \\n      segFile: `${pj.jobRoot}/segments/${segName}.wav`, \\n      txtFile: `${pj.jobRoot}/segments/${segName}.txt`\\n    }\\n  };\\n});\\n"},"id":"278c51fd-bfbf-42ca-9bd4-afec258ab072","name":"Build Segments","type":"n8n-nodes-base.code","typeVersion":2,"position":[448,1152]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\nVOC={{ JSON.stringify($(\\"Prepare Job\\").item.json.demucsVocals) }}\\nSRT={{$('Prepare Job').item.json.srtPath}}\\n\\n[ -n \\"$VOC\\" ] && [ -s \\"$VOC\\" ] || { echo \\"[CHECK][ERR] Missing vocals.wav: $VOC\\" >&2; exit 1; }\\n[ -n \\"$SRT\\" ] && [ -s \\"$SRT\\" ] || { echo \\"[CHECK][ERR] Missing SRT: $SRT\\" >&2; exit 1; }\\n\\nRTTM_DIR=\\"$(dirname \\"$VOC\\")\\"\\nRTTM=\\"$RTTM_DIR/vocals.rttm\\"\\n[ -s \\"$RTTM\\" ] || { echo \\"[CHECK][ERR] Missing vocals.rttm: $RTTM\\" >&2; exit 1; }\\n\\nprintf \\"OK\\\\n\\"\\n'\\n"},"id":"f8701578-4276-4a87-9b18-5713a8daf438","name":"Check Inputs","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[992,992]},{"parameters":{"filePath":"={{ $json.stdout }}","dataPropertyName":"audioData"},"id":"9aec102e-a326-420c-85d2-cdd8ac25cfec","name":"Read Segment","type":"n8n-nodes-base.readBinaryFile","typeVersion":1,"position":[1152,1168]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\nIN={{ $(\\"Prepare Job\\").item.json.demucsVocals }}\\nSTART={{ $json.start }}\\nDUR={{ $json.duration }}\\nSPEAKER={{ $json.speaker || \\"unknown\\" }}\\n\\n# 🔢 Tính END\\nEND=$(awk \\"BEGIN{print $START+$DUR}\\")\\n\\nOUT_DIR=\\"$(dirname {{ $json.segFile }})\\"\\nmkdir -p \\"$OUT_DIR\\"\\n\\nBASE=\\"Start_${START}s-End_${END}s-segment\\"\\nWAV_OUT=\\"$OUT_DIR/${BASE}.wav\\"\\nTXT_OUT=\\"$OUT_DIR/${BASE}.txt\\"\\n\\n# 🎵 Cắt audio\\nffmpeg -hide_banner -loglevel error -y -i \\"$IN\\" -ss \\"$START\\" -t \\"$DUR\\" -ar 16000 -ac 1 \\"$WAV_OUT\\"\\n\\n# 📝 Metadata TXT (placeholder Transcript)\\n#{\\n # echo \\"Start: $START\\"\\n  #echo \\"End: $END\\"\\n  #echo \\"Duration: $DUR\\"\\n  #echo \\"Speaker: $SPEAKER\\"\\n  #echo \\"\\"\\n  #echo \\"Transcript:\\"\\n#} > \\"$TXT_OUT\\"\\n\\n# 👉 Xuất đường dẫn WAV cho Whisper\\necho \\"$WAV_OUT\\"\\n'\\n"},"id":"e1b918c3-aaaf-457c-8d24-e7806ceba36a","name":"Cut Segment","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[976,1168]},{"parameters":{"method":"POST","url":"={{ $('Prepare Job').item.json.whisperUrl }}","sendBody":true,"contentType":"multipart-form-data","bodyParameters":{"parameters":[{"parameterType":"formBinaryData","name":"audio_file","inputDataFieldName":"audioData"}]},"options":{"timeout":600000}},"id":"ed008412-1871-4256-9514-e6fdfb29e436","name":"Whisper","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[1328,1168],"retryOnFail":true,"waitBetweenTries":5000,"executeOnce":true},{"parameters":{},"type":"n8n-nodes-base.noOp","name":"Replace Me","typeVersion":1,"position":[2016,1152],"id":"b369773f-c93e-416e-b635-a3716b5ad77f"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"id":"66f024c4-f76e-41c6-9aa5-8380995cdf36","leftValue":"={{ $json.data }}","rightValue":"","operator":{"type":"string","operation":"notEmpty","singleValue":true}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.2,"position":[1504,1168],"id":"34a83019-35ae-46d8-adbb-ff878e42486a","name":"If"},{"parameters":{"jsCode":"// Lấy tất cả items từ index 360 trở đi\\nconst allItems = $input.all();\\nconst startFromIndex = 669;\\n\\nconst filteredItems = allItems.filter((item, index) => index >= startFromIndex);\\n\\n// ✅ Trả về json + giữ pairedItem\\nreturn filteredItems.map((item, index) => ({\\n  json: item.json,\\n  pairedItem: {\\n    item: item.pairedItem?.item ?? index  // giữ link tới item gốc\\n  }\\n}));\\n"},"id":"9ea1ee90-720f-4144-8ec4-5571e22fffc1","name":"StartLoop at","type":"n8n-nodes-base.code","typeVersion":2,"position":[608,1040]},{"parameters":{"chatId":"5584954476","text":"=🚨 **LỖI WORKFLOW** 🚨\\n\\n📋 **Chi tiết:**\\n• **Workflow:** {{ $json.workflow }}\\n• **Node lỗi:** {{ $json.node }}\\n• **Thời gian:** {{ $json.timestamp }}\\n• **ID thực thi:** {{ $json.executionId }}\\n\\n❌ **Thông báo lỗi:**\\n```\\n{{ $json.message }}\\n```\\n\\n🔍 **Stack trace:**\\n```\\n{{ $json.stack.substring(0, 500) }}{{ $json.stack.length > 500 ? '...' : '' }}\\n```\\n\\n⚡ *Được gửi từ n8n Error Handler*","additionalFields":{"parse_mode":"Markdown"},"path":"b2008c92-42c3-4c03-9fcf-d6372912f5c2"},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[800,256],"id":"f90ab4d5-af1f-41ab-8936-33d57bacb7f4","name":"Send Error Notification","webhookId":"b2008c92-42c3-4c03-9fcf-d6372912f5c2","credentials":{"telegramApi":{"id":"3dY6VmwOtXaErnPU","name":"Telegram account"}}},{"parameters":{"mode":"runOnceForEachItem","jsCode":"// Log lỗi vào console để debug\\nconst errorData = $json;\\nconsole.log('=== N8N ERROR LOG ===');\\nconsole.log('Timestamp:', errorData.timestamp);\\nconsole.log('Workflow:', errorData.workflow);\\nconsole.log('Node:', errorData.node);\\nconsole.log('Message:', errorData.message);\\nconsole.log('Execution ID:', errorData.executionId);\\nconsole.log('Stack:', errorData.stack);\\nconsole.log('=====================');\\n\\nreturn { json: errorData };"},"id":"c879a5da-68f1-4002-8840-04d84523ef6c","name":"Log Error","type":"n8n-nodes-base.code","typeVersion":2,"position":[800,384]},{"parameters":{"mode":"runOnceForEachItem","jsCode":"const e = $json;\\nconst errorData = {\\n  error: true,\\n  message: e.message || e.execution?.error?.message || 'Lỗi không xác định',\\n  node: e.execution?.error?.node?.name || 'Không rõ node',\\n  workflow: e.execution?.workflowData?.name || 'Workflow không rõ',\\n  executionId: e.execution?.id || 'N/A',\\n  timestamp: new Date().toLocaleString('vi-VN', {\\n    timeZone: 'Asia/Ho_Chi_Minh',\\n    year: 'numeric',\\n    month: '2-digit',\\n    day: '2-digit',\\n    hour: '2-digit',\\n    minute: '2-digit',\\n    second: '2-digit'\\n  }),\\n  stack: e.stack || e.execution?.error?.stack || 'Không có stack trace'\\n};\\n\\nreturn { json: errorData };"},"id":"0ba95b9c-88a2-4817-a921-f42b185a6eb7","name":"Error Handler1","type":"n8n-nodes-base.code","typeVersion":2,"position":[608,256]},{"parameters":{"content":"STEP:\\nNẾU LỖI THÌ THIẾT LẬP LẠI","height":220,"width":160,"color":3},"id":"d7ba937d-6af0-46ad-8d72-de5123fa80aa","name":"Sticky Note1","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[576,960]},{"parameters":{"content":"STEP: Nối nhiều file .wav thành 1 file","height":268,"width":1216,"color":4},"id":"845da914-4809-4887-9338-a9e68e31b954","name":"Sticky Note2","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[192,1456]},{"parameters":{"jsCode":"const fs = require('fs');\\nconst path = require('path');\\n\\nconst fileList = $input.first().json.stdout\\n  .trim()\\n  .split('\\\\n')\\n  .filter(f => f.length > 0)\\n  .map(line => {\\n    const parts = line.split('||');\\n    return parts.length === 2 ? parts[1] : line;\\n  });\\n\\nconst cfg = $('Set Config1').first().json;\\nconst outputPrefix = cfg.OutputDirectory;\\n\\n// ✅ Tạo thư mục cha nếu chưa có\\nfs.mkdirSync(outputPrefix, { recursive: true });\\n\\n// Build output path\\nconst outputPath = path.join(outputPrefix, 'combined.wav');\\n\\nreturn [{\\n  json: {\\n    files: fileList,\\n    outputPath,       // bắt buộc\\n    outputPrefix      // giữ lại nếu cần\\n  }\\n}];\\n"},"id":"65bdd113-89e9-4546-8cde-239168149e1f","name":"Prepare File List","type":"n8n-nodes-base.code","typeVersion":2,"position":[848,1536]},{"parameters":{"command":"=bash -lc 'python3 {{ $(\\"Set Config1\\").item.json.concat_wav }} '\\\\''{{ JSON.stringify($json) }}'\\\\'''\\n"},"id":"ec1bb026-112d-49e4-a59d-2483f9045206","name":"Validate WAV Files","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1088,1536]},{"parameters":{"command":"=bash -lc 'find {{ JSON.stringify($(\\"Set Config1\\").item.json.inputDirectory) }} -maxdepth 1 -type f \\\\( -iname \\"*.mp4\\" -o -iname \\"*.mkv\\" -o -iname \\"*.mov\\" -o -iname \\"*.wav\\" -o -iname \\"*.mp3\\" -o -iname \\"*.m4a\\" \\\\) -printf \\"%f||%p\\\\n\\"'"},"id":"fc257e7e-5445-4381-9d38-0a32167fe6c2","name":"List Input Files1","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[656,1536]},{"parameters":{"keepOnlySet":true,"values":{"string":[{"name":"inputDirectory","value":"/files/voice/OK"},{"name":"OutputDirectory","value":"/files/voice/OK/OK"},{"name":"concat_wav","value":"/scripts/concat_wav.py"}]},"options":{}},"id":"262a7d2b-3c0e-45bb-8aae-c092bd2fde74","name":"Set Config1","type":"n8n-nodes-base.set","typeVersion":2,"position":[464,1536]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\nAP=\\"{{ $json.stdout }}\\"\\nOUT=\\"{{ $('Prepare Job').item.json.demucsVocals}}\\"\\nDEM=demucs\\n\\n# Kiểm tra file tồn tại và kích thước >5KB thì skip\\nif [ -f \\"$OUT\\" ]; then\\n  size=$(wc -c \\\\< \\"$OUT\\" 2>/dev/null || echo 0)\\n  if [ \\"$size\\" -gt 5120 ]; then\\n    echo \\"[FFMPEG][INFO] Found existing output: $OUT, skip re-extract.\\" >&2\\n    printf \\"%s\\\\n\\" \\"$OUT\\"\\n    exit 0\\n  fi\\nfi\\n\\n# === Giới hạn threads tối đa ===\\nMAX_THREADS=32\\n\\n# === Lấy tổng core thực tế ===\\nTOTAL=$(nproc --all)\\n\\n# === Đo CPU usage trong 1 giây ===\\nread cpu a b c idle rest < /proc/stat\\ntotal1=$((a+b+c+idle))\\nidle1=$idle\\nsleep 1\\nread cpu a b c idle rest < /proc/stat\\ntotal2=$((a+b+c+idle))\\nidle2=$idle\\ndiff_total=$((total2-total1))\\ndiff_idle=$((idle2-idle1))\\nUSAGE=$(( (100*(diff_total-diff_idle))/diff_total ))\\n\\n# === Tính số core rảnh ===\\nFREE=$(( TOTAL * (100 - USAGE) / 100 ))\\n\\n# === Chọn threads: free nhưng không vượt MAX_THREADS ===\\nif [ \\"$FREE\\" -gt \\"$MAX_THREADS\\" ]; then\\n  THREADS=$MAX_THREADS\\nelse\\n  THREADS=$FREE\\nfi\\nTHREADS=$(( THREADS > 0 ? THREADS : 1 ))\\n\\nif [ -z \\"$OUT\\" ]; then\\n  echo \\"[DEM][ERR] empty OUT\\" >&2\\n  exit 1\\nfi\\n\\nmkdir -p \\"$OUT\\"\\nexport DEMUCS_CACHE=\\"/files/voice/temp/demucs_cache\\"\\nmkdir -p \\"$DEMUCS_CACHE\\"\\n\\necho \\"[DEM][INFO] Total cores=$TOTAL, load=${USAGE}%, free=$FREE, limit=$MAX_THREADS → dùng THREADS=$THREADS\\" >&2\\n\\nexport OMP_NUM_THREADS=$THREADS\\nexport MKL_NUM_THREADS=$THREADS\\nexport OPENBLAS_NUM_THREADS=$THREADS\\nexport NUMEXPR_NUM_THREADS=$THREADS\\nJOBS=\\"-j $THREADS\\"\\n\\nDEMUCS_OUTPUT=$(\\"$DEM\\" -d cpu -n htdemucs_6s --two-stems=vocals $JOBS \\"$AP\\" -o \\"$OUT\\" 2>&1)\\nVOC=$(echo \\"$DEMUCS_OUTPUT\\" | tail -1 | grep -o \\"/files/.*/vocals\\\\.wav\\" || true)\\nif [ -z \\"$VOC\\" ]; then\\n  VOC=$(find \\"$OUT\\" -type f -iname vocals.wav -print -quit 2>/dev/null || true)\\nfi\\n\\nif [ ! -s \\"$VOC\\" ]; then\\n  echo \\"[DEM][ERR] vocals.wav not found under $OUT\\" >&2\\n  echo \\"[DEM][DEBUG] Demucs output was: $DEMUCS_OUTPUT\\" >&2\\n  exit 1\\nfi\\n\\n# cleanup temp trong cache, giữ model\\nfind \\"$DEMUCS_CACHE\\" -type f ! -name \\"*.pt\\" ! -name \\"*.json\\" -delete || true\\nprintf \\"%s\\\\n\\" \\"$VOC\\"\\n'"},"id":"4c34bf07-b0e1-40e7-8a0d-30bc7b2430cd","name":"Demucs Separate - Optimized","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1488,784]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\nVOC=\\"{{ $json.stdout }}\\"\\nPY=\\"{{ $(\\"Prepare Job\\").item.json.pythonExe }}\\"\\nSCR=\\"{{ $(\\"Prepare Job\\").item.json.diarPy }}\\"\\nHF_TOKEN=\\"$HUGGINGFACE_ACCESS_TOKEN\\"\\n\\nOUTDIR=\\"$(dirname \\"$VOC\\")\\"\\nmkdir -p \\"$OUTDIR\\"\\nRTTM_FILE=\\"$OUTDIR/vocals.rttm\\"\\n\\n# === Skip nếu RTTM có sẵn và >5KB ===\\nif [ -f \\"$RTTM_FILE\\" ] && [ \\"$(stat -c%s \\"$RTTM_FILE\\")\\" -gt 5120 ]; then\\n  echo \\"[DIAR][INFO] Found valid RTTM (>5KB): $RTTM_FILE, skip diarization.\\" >&2\\n  printf \\"%s\\\\n\\" \\"$RTTM_FILE\\"\\n  exit 0\\nfi\\n\\n# === Giới hạn threads tối đa (theo .wslconfig hoặc mong muốn) ===\\nMAX_THREADS=32\\n\\n# === Lấy số core thực tế ===\\nTOTAL=$(nproc --all)\\n\\n# === Đo CPU usage trong 1 giây ===\\nread cpu a b c idle rest < /proc/stat\\ntotal1=$((a+b+c+idle))\\nidle1=$idle\\nsleep 1\\nread cpu a b c idle rest < /proc/stat\\ntotal2=$((a+b+c+idle))\\nidle2=$idle\\ndiff_total=$((total2-total1))\\ndiff_idle=$((idle2-idle1))\\nUSAGE=$(( (100*(diff_total-diff_idle))/diff_total ))\\n\\n# === Tính số core rảnh ===\\nFREE=$(( TOTAL * (100 - USAGE) / 100 ))\\n\\n# === Chọn threads: free nhưng không vượt MAX_THREADS ===\\nif [ \\"$FREE\\" -gt \\"$MAX_THREADS\\" ]; then\\n  THREADS=$MAX_THREADS\\nelse\\n  THREADS=$FREE\\nfi\\nTHREADS=$(( THREADS > 0 ? THREADS : 1 ))\\n\\necho \\"[DIAR][INFO] Total cores=$TOTAL, CPU load=${USAGE}%, free=$FREE, limit=$MAX_THREADS → chọn THREADS=$THREADS\\" >&2\\n\\n# === Xuất env cho PyTorch ===\\nexport OMP_NUM_THREADS=$THREADS\\nexport MKL_NUM_THREADS=$THREADS\\nexport OPENBLAS_NUM_THREADS=$THREADS\\nexport NUMEXPR_NUM_THREADS=$THREADS\\n\\n# === Chạy diarization ===\\ntimeout 10800 \\"$PY\\" -u \\"$SCR\\" --input \\"$VOC\\" --out_dir \\"$OUTDIR\\" --hf_token \\"$HF_TOKEN\\"\\n\\n# === Fallback RTTM nếu diarization thất bại ===\\nif [ ! -s \\"$RTTM_FILE\\" ]; then\\n  DURATION=$(ffprobe -v quiet -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 \\"$VOC\\" 2>/dev/null || echo \\"60\\")\\n  echo \\"SPEAKER vocals 1 0.000 $DURATION <NA> <NA> SPEAKER_00 <NA> <NA>\\" > \\"$RTTM_FILE\\"\\n  echo \\"[DIAR][WARN] RTTM fallback created\\" >&2\\nfi\\n\\nprintf \\"%s\\\\n\\" \\"$RTTM_FILE\\"\\n'"},"id":"86210def-40c6-4235-877a-e312841dafb2","name":"Diarization by CPU (pyannote)","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1744,608]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\n# Lấy output từ node trước và chỉ giữ lại đường dẫn file\\nRAW_OUTPUT=\\"{{ $json.stdout }}\\"\\nVOC=$(echo \\"$RAW_OUTPUT\\" | grep -o '/files/.*/vocals\\\\.wav' || echo \\"$RAW_OUTPUT\\")\\nPY=\\"{{ $('Prepare Job').item.json.pythonExe}}\\"\\nSCR=\\"/scripts/diarize_silero.py\\"\\n\\n# === Skip nếu RTTM có sẵn và >5KB ===\\nif [ -f \\"$RTTM_FILE\\" ] && [ \\"$(stat -c%s \\"$RTTM_FILE\\")\\" -gt 5120 ]; then\\n  echo \\"[DIAR][INFO] Found valid RTTM (>5KB): $RTTM_FILE, skip diarization.\\" >&2\\n  printf \\"%s\\\\n\\" \\"$RTTM_FILE\\"\\n  exit 0\\nfi\\n\\n# Kiểm tra file vocals.wav tồn tại\\nif [ ! -s \\"$VOC\\" ]; then\\n  echo \\"[DIAR][ERR] vocals.wav missing or empty: $VOC\\" >&2\\n  echo \\"[DIAR][DEBUG] Raw output was: $RAW_OUTPUT\\" >&2\\n  exit 1\\nfi\\n\\n# Kiểm tra script diarize.py tồn tại\\nif [ ! -f \\"$SCR\\" ]; then\\n  echo \\"[DIAR][ERR] diarize.py missing: $SCR\\" >&2\\n  exit 1\\nfi\\n\\nOUTDIR=\\"$(dirname \\"$VOC\\")\\"\\nmkdir -p \\"$OUTDIR\\"\\n\\n# === Giới hạn threads tối đa (theo .wslconfig hoặc mong muốn) ===\\nMAX_THREADS=32\\n\\n# === Lấy số core thực tế ===\\nTOTAL=$(nproc --all)\\n\\n# === Đo CPU usage trong 1 giây ===\\nread cpu a b c idle rest < /proc/stat\\ntotal1=$((a+b+c+idle))\\nidle1=$idle\\nsleep 1\\nread cpu a b c idle rest < /proc/stat\\ntotal2=$((a+b+c+idle))\\nidle2=$idle\\ndiff_total=$((total2-total1))\\ndiff_idle=$((idle2-idle1))\\nUSAGE=$(( (100*(diff_total-diff_idle))/diff_total ))\\n\\n# === Tính số core rảnh ===\\nFREE=$(( TOTAL * (100 - USAGE) / 100 ))\\n\\n# === Chọn threads: free nhưng không vượt MAX_THREADS ===\\nif [ \\"$FREE\\" -gt \\"$MAX_THREADS\\" ]; then\\n  THREADS=$MAX_THREADS\\nelse\\n  THREADS=$FREE\\nfi\\nTHREADS=$(( THREADS > 0 ? THREADS : 1 ))\\n\\necho \\"[DIAR][INFO] Total cores=$TOTAL, CPU load=${USAGE}%, free=$FREE, limit=$MAX_THREADS → chọn THREADS=$THREADS\\" >&2\\n\\n# === Xuất env cho PyTorch ===\\nexport OMP_NUM_THREADS=\\"$THREADS\\"\\nexport MKL_NUM_THREADS=\\"$THREADS\\"\\nexport OPENBLAS_NUM_THREADS=\\"$THREADS\\"\\nexport NUMEXPR_NUM_THREADS=\\"$THREADS\\"\\nexport VECLIB_MAXIMUM_THREADS=\\"$THREADS\\"\\n\\n# Thiết lập cache\\nNUMBA_CACHE_DIR=\\"/files/voice/tmp/silero_cache/numba\\"\\nHF_HOME=\\"/files/voice/tmp/silero_cache/hf\\"\\nTORCH_HOME=\\"/files/voice/tmp/silero_cache/torch\\"\\nmkdir -p \\"$NUMBA_CACHE_DIR\\" \\"$HF_HOME\\" \\"$TORCH_HOME\\"\\nexport NUMBA_CACHE_DIR HF_HOME TORCH_HOME\\n\\n# Chuẩn bị lệnh\\nCMD=(\\"$PY\\" -u \\"$SCR\\" --input \\"$VOC\\" --out_dir \\"$OUTDIR\\" --method \\"silero\\")\\n\\n# Chạy diarization\\necho \\"[DIAR][INFO] Running Silero VAD diarization for: $VOC\\" >&2\\ntimeout 7200 \\"${CMD[@]}\\"\\n\\n# Kiểm tra kết quả\\nRTTM_FILE=\\"$OUTDIR/vocals.rttm\\"\\nif [ ! -s \\"$RTTM_FILE\\" ]; then\\n  echo \\"[DIAR][ERR] RTTM not created, fallback to single speaker\\" >&2\\n  DURATION=$(ffprobe -v quiet -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 \\"$VOC\\" 2>/dev/null || echo \\"60\\")\\n  echo \\"SPEAKER vocals 1 0.000 $DURATION <NA> <NA> SPEAKER_00 <NA> <NA>\\" > \\"$RTTM_FILE\\"\\nfi\\n\\necho \\"[DIAR][SUCCESS] RTTM ready: $RTTM_FILE\\" >&2\\n# 👉 Output clean chỉ có đường dẫn RTTM\\necho \\"$RTTM_FILE\\"\\n'"},"id":"65cca3d9-194e-4569-a742-fb5fb0ae554c","name":"Diarization (Silero) - CPU Optimized","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1680,784]}]	{"On Error":{"main":[[{"node":"Error Handler1","type":"main","index":0}]]},"Done":{"main":[[{"node":"Summary Report","type":"main","index":0}]]},"RVC Convert":{"main":[[{"node":"Done","type":"main","index":0}]]},"Enable RVC?":{"main":[[{"node":"RVC Convert","type":"main","index":0}],[{"node":"Done","type":"main","index":0}]]},"Extract 16k Mono WAV - Optimized":{"main":[[{"node":"Demucs Separate - Optimized","type":"main","index":0}]]},"List Input Files":{"main":[[{"node":"Prepare Job","type":"main","index":0}]]},"Set Config":{"main":[[{"node":"List Input Files","type":"main","index":0}]]},"Start":{"main":[[{"node":"Set Config","type":"main","index":0}]]},"Prepare Job":{"main":[[{"node":"Extract 16k Mono WAV - Optimized","type":"main","index":0}]]},"Build SRT Entry":{"main":[[{"node":"Append to SRT","type":"main","index":0}]]},"Append to SRT":{"main":[[{"node":"Replace Me","type":"main","index":0}]]},"Loop Segments":{"main":[[{"node":"Check Inputs","type":"main","index":0}],[{"node":"Cut Segment","type":"main","index":0}]]},"Separate Speakers - Optimized1":{"main":[[{"node":"Send a text message1","type":"main","index":0}]]},"Parse RTTM":{"main":[[{"node":"Build Segments","type":"main","index":0}]]},"Build Segments":{"main":[[{"node":"Loop Segments","type":"main","index":0}]]},"Check Inputs":{"main":[[{"node":"Separate Speakers - Optimized1","type":"main","index":0}]]},"Read Segment":{"main":[[{"node":"Whisper","type":"main","index":0}]]},"Cut Segment":{"main":[[{"node":"Read Segment","type":"main","index":0}]]},"Whisper":{"main":[[{"node":"If","type":"main","index":0}]]},"Replace Me":{"main":[[{"node":"Loop Segments","type":"main","index":0}]]},"If":{"main":[[{"node":"Build SRT Entry","type":"main","index":0}],[{"node":"Loop Segments","type":"main","index":0}]]},"StartLoop at":{"main":[[{"node":"Loop Segments","type":"main","index":0}]]},"Error Handler1":{"main":[[{"node":"Send Error Notification","type":"main","index":0},{"node":"Log Error","type":"main","index":0}]]},"Prepare File List":{"main":[[{"node":"Validate WAV Files","type":"main","index":0}]]},"List Input Files1":{"main":[[{"node":"Prepare File List","type":"main","index":0}]]},"Set Config1":{"main":[[{"node":"List Input Files1","type":"main","index":0}]]},"Demucs Separate - Optimized":{"main":[[{"node":"Diarization (Silero) - CPU Optimized","type":"main","index":0}]]},"Diarization by CPU (pyannote)":{"main":[[]]},"Diarization (Silero) - CPU Optimized":{"main":[[{"node":"Parse RTTM","type":"main","index":0}]]}}	2025-08-26 12:36:30.626+00	2025-08-26 12:36:30.626+00	{"executionOrder":"v1"}	\N	{}	b3abaa54-e3fb-45ab-b46d-48cb8cc44307	0	roGwBDJ7Nrh0IERD	{"templateCredsSetupCompleted":true}	\N	f	3	\N	\N	[]	\N
LUU SDLC 7-Step Enterprise AI Team v4	f	[{"parameters":{"content":"## 🏭 SDLC 7-Step Enterprise AI Team\\n\\n**Quy trình:** Chat Trigger → 7 bước SDLC → Final Output\\n\\n**Mỗi bước gồm 3 node:**\\n- 🔵 **Executor** — thực thi nhiệm vụ\\n- 🟡 **Critic** — phản biện, tìm lỗi\\n- 🟢 **Synthesizer** — tổng hợp kết quả tối ưu\\n- ✅ **Quality Gate** — kiểm tra trước khi sang bước kế\\n\\n**Models:**\\n- Executor: `mistral-nemo` (nhanh)\\n- Critic: `qwen2.5:7b` (nhẹ)\\n- Synthesizer: `deepseek-r1:32b` (chất lượng cao)\\n- Coder: `qwen2.5-coder:14b` (chuyên code)","height":320,"width":400,"color":7},"id":"290e940c-bc6f-4fb9-8614-52434d405a71","name":"Sticky Note","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[2544,1680]},{"parameters":{"options":{}},"id":"487494dd-8851-4a71-a2c6-293a018a80a8","name":"When chat message received","type":"@n8n/n8n-nodes-langchain.chatTrigger","typeVersion":1.1,"position":[3024,1808],"webhookId":"sdlc-ai-team"},{"parameters":{"content":"### 📥 Input\\nNhập yêu cầu vào cửa sổ chat.\\nVí dụ:\\n*\\"Viết script Python scan port 80/443 dải 192.168.1.0/24\\"*","height":100,"width":300,"color":6},"id":"5666ad15-9950-468f-bd19-03a5beb7f0ab","name":"Sticky Note1","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[2976,1680]},{"parameters":{"values":{"string":[{"name":"task_id","value":"={{ $now.format('X') }}"},{"name":"description","value":"={{ $json.chatInput }}"}]},"options":{}},"id":"2d4564df-ced7-4c0d-84b8-eb7e3940ce93","name":"Set Task","type":"n8n-nodes-base.set","typeVersion":2,"position":[3248,1808]},{"parameters":{"jsCode":"let retry = 0;\\ntry { retry = $('Logic Control').item.retry_count + 1; } catch (e) { retry = 0; }\\nif (retry > 2) throw new Error('SDLC failed after 2 retries.');\\nreturn { retry_count: retry, is_retrying: retry > 0 };"},"id":"99d28778-b8eb-4f48-ab8f-4bb46ad6bf4e","name":"Logic Control","type":"n8n-nodes-base.code","typeVersion":2,"position":[3472,1808]},{"parameters":{"content":"### 🔄 Retry Logic\\nNếu Quality Gate thất bại, workflow tự retry tối đa **2 lần** trước khi dừng và báo lỗi.","height":100,"width":260,"color":3},"id":"d6dd5ccf-a8f3-4a6d-a2b3-51bd912b9013","name":"Sticky Note2","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[3392,1680]},{"parameters":{"content":"### Step 1: Idea Generation\\nPhân tích tính khả thi, xác định rủi ro và các module cần có.\\n\\n**Executor:** `mistral-nemo:latest`  \\n**Critic:** `qwen2.5:7b`  \\n**Synthesizer:** `deepseek-coder-v2:16b`","height":146,"width":760,"color":5},"id":"699322b0-e6ae-448d-ab74-af60180bec1c","name":"Sticky Note Step1","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[3616,1888]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'mistral-nemo:latest', prompt: 'VAI TRO: IDEA ANALYST\\\\nINPUT:\\\\n' + $('Set Task').first().json.description + '\\\\n\\\\nPhan tich yeu cau va danh gia tinh kha thi:\\\\n1. Mo ta y tuong cot loi (1 doan)\\\\n2. Van de can giai quyet\\\\n3. 3-5 tinh nang chinh\\\\n4. Tinh kha thi ky thuat: De/Trung binh/Kho + ly do\\\\n5. Rui ro tiem an va cach xu ly', stream: false }) }}","options":{}},"id":"56df1b55-562e-4be5-9704-0d42fa441721","name":"Step1 Executor","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3632,2048]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'qwen2.5:7b', prompt: 'VAI TRO: IDEA CRITIC\\\\nY TUONG DA PHAN TICH:\\\\n' + $('Step1 Executor').last().json.response + '\\\\n\\\\nPhan bien y tuong:\\\\n1. Luan diem nao chua thuyet phuc?\\\\n2. Rui ro nao bi bo sot?\\\\n3. Feasibility co duoc danh gia chinh xac?\\\\n4. Co giai phap don gian hon?\\\\n5. Diem manh nao can giu lai?', stream: false }) }}","options":{}},"id":"2d2696f6-b6d4-406a-b4b6-1b9dd99b7592","name":"Step1 Critic","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3872,2048]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'deepseek-coder-v2:16b', prompt: 'SYNTHESIZER - BUOC 1: Idea Generation\\\\n\\\\nBAN THUC THI:\\\\n' + $('Step1 Executor').last().json.response + '\\\\n\\\\nPHAN BIEN:\\\\n' + $('Step1 Critic').last().json.response + '\\\\n\\\\nNHIEM VU TONG HOP:\\\\nTong hop BAN MO TA Y TUONG CUOI CUNG:\\\\n- Vision statement (1 cau)\\\\n- Core features (bullet)\\\\n- Feasibility verdict\\\\n- Key risks & mitigations\\\\nSan sang cho Requirement Analysis.', stream: false }) }}","options":{}},"id":"11ab0a9c-25f6-441c-82c6-d228e13ea864","name":"Step1 Synthesizer","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[4112,2048]},{"parameters":{"jsCode":"const synth = $('Step1 Synthesizer').last().json.response || '';\\nif (!synth || synth.length < 50) throw new Error('Quality Gate 1 FAIL: output too short');\\nreturn { step1_result: synth, step1_passed: true };"},"id":"b7bc35ce-3881-4d31-a612-6ef7c659e4e0","name":"Quality Gate 1","type":"n8n-nodes-base.code","typeVersion":2,"position":[4352,2048]},{"parameters":{"content":"### Step 2: Requirement Analysis\\nChuyển ý tưởng thành tài liệu yêu cầu rõ ràng, đo lường được.\\n\\n**Executor:** `mistral-nemo:latest`  \\n**Critic:** `qwen2.5:7b`  \\n**Synthesizer:** `deepseek-coder-v2:16b`","height":146,"width":760,"color":5},"id":"696f6740-31fc-4755-854d-7a9af9b1c0a9","name":"Sticky Note Step2","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[3616,2208]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'mistral-nemo:latest', prompt: 'VAI TRO: BUSINESS ANALYST\\\\nINPUT:\\\\n' + $('Step1 Synthesizer').last().json.response + '\\\\n\\\\nViet SRS dua tren y tuong da duoc phe duyet:\\\\n1. Functional Requirements (FR) - liet ke day du\\\\n2. Non-Functional Requirements (NFR) voi con so cu the\\\\n3. User Stories: As a... I want... So that...\\\\n4. Acceptance Criteria tung tinh nang\\\\n5. Out of scope (nhung gi KHONG lam)', stream: false }) }}","options":{}},"id":"b5732104-b729-44c2-9170-941200732185","name":"Step2 Executor","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3632,2352]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'qwen2.5:7b', prompt: 'VAI TRO: REQUIREMENT CRITIC\\\\nTAI LIEU CAN PHAN BIEN:\\\\n' + $('Step2 Executor').last().json.response + '\\\\n\\\\nReview tai lieu yeu cau:\\\\n1. FR nao con mo ho, khong do luong duoc?\\\\n2. NFR nao thieu con so cu the?\\\\n3. User story nao thieu acceptance criteria?\\\\n4. Co conflict giua requirements?\\\\n5. Thieu edge case nao quan trong?', stream: false }) }}","options":{}},"id":"73ce4f2c-5287-4e8a-9887-a36366974c1f","name":"Step2 Critic","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3872,2352]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'deepseek-coder-v2:16b', prompt: 'SYNTHESIZER - BUOC 2: Requirement Analysis\\\\n\\\\nBAN THUC THI:\\\\n' + $('Step2 Executor').last().json.response + '\\\\n\\\\nPHAN BIEN:\\\\n' + $('Step2 Critic').last().json.response + '\\\\n\\\\nNHIEM VU TONG HOP:\\\\nTao SRS CUOI CUNG:\\\\nFR list | NFR list | User Stories | Acceptance Criteria | Constraints\\\\nDu chi tiet de Architect thiet ke khong can hoi them.', stream: false }) }}","options":{}},"id":"3f76c987-147f-41c6-8e8b-7875b802cc89","name":"Step2 Synthesizer","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[4112,2352]},{"parameters":{"jsCode":"const synth = $('Step2 Synthesizer').last().json.response || '';\\nif (!synth || synth.length < 50) throw new Error('Quality Gate 2 FAIL: output too short');\\nreturn { step2_result: synth, step2_passed: true };"},"id":"a178a7f1-fbed-48e5-95aa-e41454e08834","name":"Quality Gate 2","type":"n8n-nodes-base.code","typeVersion":2,"position":[4352,2352]},{"parameters":{"content":"### Step 3: Product Design\\nQuyết định tech stack, kiến trúc, thư viện trước khi code.\\n\\n**Executor:** `deepseek-coder-v2:16b`  \\n**Critic:** `qwen2.5:7b`  \\n**Synthesizer:** `deepseek-coder-v2:16b`","height":130,"width":760,"color":4},"id":"d618e758-ad54-4061-97d8-e613706f0863","name":"Sticky Note Step3","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[3616,2512]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'deepseek-coder-v2:16b', prompt: 'VAI TRO: SOLUTION ARCHITECT\\\\nINPUT:\\\\n' + $('Step2 Synthesizer').last().json.response + '\\\\n\\\\nThiet ke giai phap ky thuat dua tren SRS:\\\\n1. Tech stack: ngon ngu, framework, thu vien chinh (giai thich ly do chon vs lua chon khac)\\\\n2. System architecture: modules va interfaces\\\\n3. Data structures & schemas chinh\\\\n4. Security & performance decisions\\\\n5. Thu tu implementation', stream: false }) }}","options":{}},"id":"de62c9c9-436a-4115-bff6-19c546cccd21","name":"Step3 Executor","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3632,2640]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'qwen2.5:7b', prompt: 'VAI TRO: DESIGN CRITIC\\\\nTAI LIEU CAN PHAN BIEN:\\\\n' + $('Step3 Executor').last().json.response + '\\\\n\\\\nPhan bien thiet ke:\\\\n1. Tech stack phu hop voi NFR chua?\\\\n2. Over-engineering hoac under-engineering?\\\\n3. Single points of failure?\\\\n4. Thu vien co van de license/maintenance?\\\\n5. Security vulnerabilities trong thiet ke?', stream: false }) }}","options":{}},"id":"1ae89e02-6f98-4021-bda6-274d61be7c7d","name":"Step3 Critic","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3872,2640]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'deepseek-coder-v2:16b', prompt: 'SYNTHESIZER - BUOC 3: Product Design\\\\n\\\\nBAN THUC THI:\\\\n' + $('Step3 Executor').last().json.response + '\\\\n\\\\nPHAN BIEN:\\\\n' + $('Step3 Critic').last().json.response + '\\\\n\\\\nNHIEM VU TONG HOP:\\\\nTao TECHNICAL DESIGN DOCUMENT:\\\\n- Final tech stack (justified)\\\\n- Architecture overview\\\\n- Module breakdown voi interfaces\\\\n- Data models\\\\n- Implementation order\\\\nDu chi tiet de Coder triet khai ngay.', stream: false }) }}","options":{}},"id":"072c72f8-524d-4972-9639-4db696e2b634","name":"Step3 Synthesizer","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[4112,2640]},{"parameters":{"jsCode":"const synth = $('Step3 Synthesizer').last().json.response || '';\\nif (!synth || synth.length < 50) throw new Error('Quality Gate 3 FAIL: output too short');\\nreturn { step3_result: synth, step3_passed: true };"},"id":"45365460-9024-4edd-93e5-b56dc6ecd5c7","name":"Quality Gate 3","type":"n8n-nodes-base.code","typeVersion":2,"position":[4352,2640]},{"parameters":{"content":"### Step 4: Product Development\\nViết code theo đúng thiết kế. Critic dùng mistral-nemo để hiểu code tốt hơn.\\n\\n**Executor:** `qwen2.5-coder:14b`  \\n**Critic:** `mistral-nemo:latest`  \\n**Synthesizer:** `deepseek-coder-v2:16b`","height":130,"width":760,"color":2},"id":"1c7a78db-62ab-4f1a-98ec-357ff45f666d","name":"Sticky Note Step4","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[3616,2800]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'qwen2.5-coder:14b', prompt: 'VAI TRO: SENIOR DEVELOPER\\\\nINPUT:\\\\n' + $('Step3 Synthesizer').last().json.response + '\\\\n\\\\nViet code hoan chinh theo Technical Design Document:\\\\n- Tuan thu dung tech stack da phe duyet\\\\n- Error handling day du\\\\n- Logging co cau truc\\\\n- Docstrings cho logic phuc tap\\\\n- KHONG them thu vien ngoai danh sach\\\\nChi tra ve code, khong giai thich.', stream: false }) }}","options":{}},"id":"1b24f012-6cad-479e-8f6b-226b9086e443","name":"Step4 Executor","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3632,2944]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'mistral-nemo:latest', prompt: 'VAI TRO: CODE REVIEWER\\\\nTAI LIEU CAN PHAN BIEN:\\\\n' + $('Step4 Executor').last().json.response + '\\\\n\\\\nReview code theo checklist:\\\\nSECURITY: injection, path traversal, input validation, secrets in code\\\\nPERFORMANCE: memory leaks, blocking calls, inefficient loops\\\\nRELIABILITY: unhandled exceptions, race conditions\\\\nMAINTAINABILITY: duplication, naming\\\\nDanh gia: PASS / NEEDS_FIX voi danh sach van de cu the.', stream: false }) }}","options":{}},"id":"229750fb-6588-4e8f-844d-ad5bc03175e7","name":"Step4 Critic","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3872,2944]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'deepseek-coder-v2:16b', prompt: 'SYNTHESIZER - BUOC 4: Product Development\\\\n\\\\nBAN THUC THI:\\\\n' + $('Step4 Executor').last().json.response + '\\\\n\\\\nPHAN BIEN:\\\\n' + $('Step4 Critic').last().json.response + '\\\\n\\\\nNHIEM VU TONG HOP:\\\\nFix CRITICAL/HIGH issues tu review. Tra ve JSON:\\\\n{\\"code\\": \\"...\\", \\"filename\\": \\"...\\", \\"dependencies\\": [...], \\"run_command\\": \\"...\\"}', stream: false }) }}","options":{}},"id":"48f8b7cd-ed63-4c59-afbd-e21d94673846","name":"Step4 Synthesizer","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[4112,2944]},{"parameters":{"jsCode":"const synth = $('Step4 Synthesizer').last().json.response || '';\\nif (!synth || synth.length < 50) throw new Error('Quality Gate 4 FAIL: output too short');\\nreturn { step4_result: synth, step4_passed: true };"},"id":"54fb0ff2-ec0f-449d-bd8c-747dc1b53519","name":"Quality Gate 4","type":"n8n-nodes-base.code","typeVersion":2,"position":[4352,2944]},{"parameters":{"content":"### Step 5: Integration & Testing\\nViết test cases thực tế (pytest), không chỉ mô tả.\\n\\n**Executor:** `mistral-nemo:latest`  \\n**Critic:** `qwen2.5:7b`  \\n**Synthesizer:** `deepseek-coder-v2:16b`","height":130,"width":760,"color":3},"id":"fb8b6287-56f3-4208-89d0-9f3834c65665","name":"Sticky Note Step5","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[3616,3104]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'mistral-nemo:latest', prompt: 'VAI TRO: QA ENGINEER\\\\nINPUT:\\\\n' + $('Step4 Synthesizer').last().json.response + '\\\\n\\\\nViet test suite (pytest) day du:\\\\n1. Unit tests tung function chinh\\\\n2. Integration test scenarios\\\\n3. Edge cases & boundary conditions\\\\n4. Performance test scenarios\\\\n5. Security test cases\\\\nViet code test thuc te, khong chi mo ta.', stream: false }) }}","options":{}},"id":"73d5e876-1ed8-4508-83d0-8e4908afe88a","name":"Step5 Executor","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3632,3248]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'qwen2.5:7b', prompt: 'VAI TRO: QA CRITIC\\\\nTAI LIEU CAN PHAN BIEN:\\\\n' + $('Step5 Executor').last().json.response + '\\\\n\\\\nReview test suite:\\\\n1. Test coverage du (uoc tinh %)?\\\\n2. Thieu test case nao quan trong?\\\\n3. Test nao fragile/false positive?\\\\n4. Edge case nao bi bo sot?\\\\n5. Test data co realistic?', stream: false }) }}","options":{}},"id":"23a2303c-8794-4568-9063-462a74fc38fa","name":"Step5 Critic","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3872,3248]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'deepseek-coder-v2:16b', prompt: 'SYNTHESIZER - BUOC 5: Integration & Testing\\\\n\\\\nBAN THUC THI:\\\\n' + $('Step5 Executor').last().json.response + '\\\\n\\\\nPHAN BIEN:\\\\n' + $('Step5 Critic').last().json.response + '\\\\n\\\\nNHIEM VU TONG HOP:\\\\nTao FINAL TEST SUITE:\\\\n{\\"test_code\\": \\"...\\", \\"test_count\\": N, \\"coverage_estimate\\": \\"X%\\", \\"critical_paths_tested\\": [...]}', stream: false }) }}","options":{}},"id":"f3fe1f79-40ca-43ab-bc78-fcbe9b8352e5","name":"Step5 Synthesizer","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[4112,3248]},{"parameters":{"jsCode":"const synth = $('Step5 Synthesizer').last().json.response || '';\\nif (!synth || synth.length < 50) throw new Error('Quality Gate 5 FAIL: output too short');\\nreturn { step5_result: synth, step5_passed: true };"},"id":"954347f5-8031-4883-a059-60d2711afffc","name":"Quality Gate 5","type":"n8n-nodes-base.code","typeVersion":2,"position":[4352,3248]},{"parameters":{"content":"### Step 6: Deployment\\nTạo Dockerfile, docker-compose, rollback plan và health checks.\\n\\n**Executor:** `deepseek-coder-v2:16b`  \\n**Critic:** `qwen2.5:7b`  \\n**Synthesizer:** `deepseek-coder-v2:16b`","height":130,"width":760,"color":6},"id":"d18d2ec5-9b8e-412c-ab71-69e10712c145","name":"Sticky Note Step6","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[3616,3408]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'deepseek-coder-v2:16b', prompt: 'VAI TRO: DEVOPS ENGINEER\\\\nINPUT:\\\\n' + $('Step5 Synthesizer').last().json.response + '\\\\n\\\\nTao deployment package:\\\\n1. Dockerfile (optimized, non-root user)\\\\n2. docker-compose.yml\\\\n3. Environment variables (.env template)\\\\n4. Deploy steps chi tiet\\\\n5. Rollback procedure\\\\n6. Health check & smoke test sau deploy', stream: false }) }}","options":{}},"id":"63396193-5cdd-4d78-a08b-64517dad6731","name":"Step6 Executor","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3632,3552]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'qwen2.5:7b', prompt: 'VAI TRO: DEPLOYMENT CRITIC\\\\nTAI LIEU CAN PHAN BIEN:\\\\n' + $('Step6 Executor').last().json.response + '\\\\n\\\\nReview deployment:\\\\n1. Security: exposed ports, run as root, secrets in image?\\\\n2. Missing health checks?\\\\n3. Rollback co thuc te tren production?\\\\n4. Resource limits (CPU/memory) duoc set?\\\\n5. Co gi gay downtime khong?', stream: false }) }}","options":{}},"id":"e56a3226-b8e9-4c59-9c96-6d0105883fec","name":"Step6 Critic","type":"n8n-nodes-base.httpRequest","typeVersion":4.1,"position":[3872,3552]},{"parameters":{"method":"POST","url":"http://host.docker.internal:11434/api/generate","sendBody":true,"specifyBody":"json","jsonBody":"={{ JSON.stringify({ model: 'deepseek-coder-v2:16b', prompt: 'SYNTHESIZER - BUOC 6: Deployment\\\\n\\\\nBAN THUC THI:\\\\n' + $('Step6 Executor').last().json.response + '\\\\n\\\\nPHAN BIEN:\\\\n' + $('Step6 Critic').last().json.response + '\\\\n\\\\nNHIEM VU TONG HOP:\\\\nTao FINAL DEPLOY PACKAGE:\\\\n{\\"dockerfile\\": \\"...\\", \\"docker_compose\\": \\"...\\", \\"env_template\\": \\"...\\", \\"deploy_steps\\": [...], \\"rollback_steps\\": [...], \\"health_check_url\\": \\"...\\"}', stream: false }) }}","options":{}},"id":"dfd331a6-bfc3-451