🤖 AI Debate - ChatGPT vs Gemini + Claude Judge (HTTP)	f	[{"parameters":{"options":{}},"id":"cf18a61f-cc1b-420d-9e2c-f0ce38d9da87","name":"💬 Chat","type":"@n8n/n8n-nodes-langchain.chatTrigger","typeVersion":1.1,"position":[-2480,1376],"webhookId":"debate-http-v1"},{"parameters":{"jsCode":"const msg = ($input.first().json.chatInput || '').trim();\\n\\nif (!msg) {\\n  return [{ json: { type: 'reply', output: '❓ Nhập chủ đề để bắt đầu tranh luận.' } }];\\n}\\n\\nif (msg.toLowerCase() === '/help') {\\n  return [{ json: { type: 'reply', output: '📋 Hướng dẫn:\\\\n• Nhập chủ đề → tranh luận 3 vòng\\\\n• chủ đề | 5 → 5 vòng (tối đa 10)\\\\n• /help → hướng dẫn\\\\n\\\\n🟢 ChatGPT = ỦNG HỘ\\\\n🔵 Gemini = PHẢN ĐỐI\\\\n⚖️ Claude = TRỌNG TÀI' } }];\\n}\\n\\nlet topic = msg;\\nlet maxRounds = 3;\\nif (msg.includes('|')) {\\n  const parts = msg.split('|');\\n  topic = parts[0].trim();\\n  const n = parseInt(parts[1]);\\n  if (!isNaN(n) && n > 0) maxRounds = Math.min(n, 10);\\n}\\n\\nreturn [{ json: {\\n  type: 'debate',\\n  topic,\\n  maxRounds,\\n  currentRound: 1,\\n  rounds: []\\n} }];"},"id":"7adeb98f-44c4-4b35-8997-8e272cf453aa","name":"⚙️ Parse Input","type":"n8n-nodes-base.code","typeVersion":2,"position":[-2240,1376]},{"parameters":{"conditions":{"options":{"typeValidation":"loose"},"conditions":[{"id":"cond-debate","leftValue":"={{ $json.type }}","rightValue":"debate","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"id":"edc54f34-9e1d-45fc-800a-0f1d6766594a","name":"❓ Is Debate?","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-2000,1376]},{"parameters":{"jsCode":"return [{ json: { output: $json.output } }];"},"id":"206727cd-b82d-4a57-84e1-1c5ae589a9d2","name":"💬 Command Reply","type":"n8n-nodes-base.code","typeVersion":2,"position":[-1760,1440]},{"parameters":{"jsCode":"const d = $input.first().json;\\nconst hist = (d.rounds || []).slice(-2)\\n  .map(r => `Vòng ${r.round}: ỦNG_HỘ=${r.pro} | PHẢN_ĐỐI=${r.con}`)\\n  .join('\\\\n') || 'Đây là vòng đầu tiên.';\\n\\nconst body = {\\n  model: 'gpt-4o-mini',\\n  max_tokens: 300,\\n  temperature: 0.7,\\n  messages: [\\n    {\\n      role: 'system',\\n      content: 'Bạn là người tranh luận ỦNG HỘ trong một cuộc tranh luận có cấu trúc. Chỉ viết lập luận bảo vệ chủ đề bằng TIẾNG VIỆT, ngắn gọn 2-3 câu, thuyết phục. Không giải thích nhiệm vụ.'\\n    },\\n    {\\n      role: 'user',\\n      content: `Chủ đề: ${d.topic}\\\\nVòng ${d.currentRound}/${d.maxRounds}\\\\nLịch sử:\\\\n${hist}\\\\n\\\\nHãy đưa ra lập luận ỦNG HỘ mạnh mẽ cho chủ đề này.`\\n    }\\n  ]\\n};\\n\\nreturn [{ json: { ...d, _body: JSON.stringify(body) } }];"},"id":"3b34ee38-5b39-4012-814c-89b71d8b64c7","name":"📝 Prep PRO","type":"n8n-nodes-base.code","typeVersion":2,"position":[-1760,1216]},{"parameters":{"method":"POST","url":"https://api.openai.com/v1/chat/completions","authentication":"predefinedCredentialType","nodeCredentialType":"n8nApi","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={{ $json._body }}","options":{"timeout":60000}},"id":"88c1735a-546b-481b-b76f-a79bdc1b0c0e","name":"🟢 ChatGPT PRO","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-1520,1216],"credentials":{"n8nApi":{"id":"Lxhji5v37y0aihqz","name":"n8n account"}}},{"parameters":{"jsCode":"const session = $('📝 Prep PRO').item.json;\\nconst raw = $input.first().json;\\n\\nconst pro = raw.choices?.[0]?.message?.content || '[ChatGPT không phản hồi]';\\n\\nconst body = {\\n  contents: [\\n    {\\n      parts: [\\n        {\\n          text: `Bạn là người tranh luận PHẢN ĐỐI trong một cuộc tranh luận có cấu trúc. Viết bằng TIẾNG VIỆT, ngắn gọn 2-3 câu, sắc bén.\\\\n\\\\nChủ đề: ${session.topic}\\\\nVòng ${session.currentRound}/${session.maxRounds}\\\\nBên ỦNG HỘ vừa lập luận: ${pro}\\\\n\\\\nHãy PHẢN BIỆN trực tiếp lập luận trên và đưa ra lý lẽ CHỐNG LẠI chủ đề. Không giải thích nhiệm vụ.`\\n        }\\n      ]\\n    }\\n  ],\\n  generationConfig: {\\n    maxOutputTokens: 300,\\n    temperature: 0.7\\n  }\\n};\\n\\nreturn [{ json: { ...session, pro, _body: JSON.stringify(body) } }];"},"id":"1a74602d-b94b-48a9-9075-ff45971b482a","name":"📝 Prep CON","type":"n8n-nodes-base.code","typeVersion":2,"position":[-1280,1216]},{"parameters":{"method":"POST","url":"=https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key={{ $credentials.apiKey }}","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={{ $json._body }}","options":{"timeout":60000}},"id":"6da3eea8-905f-4c52-afee-72639a8f8028","name":"🔵 Gemini CON","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-1040,1216]},{"parameters":{"jsCode":"const session = $('📝 Prep CON').item.json;\\nconst raw = $input.first().json;\\n\\nconst con = raw.candidates?.[0]?.content?.parts?.[0]?.text || '[Gemini không phản hồi]';\\n\\nconst rounds = [...(session.rounds || []), {\\n  round: session.currentRound,\\n  pro: session.pro,\\n  con\\n}];\\n\\nconst nextRound = session.currentRound + 1;\\nconst done = nextRound > session.maxRounds;\\n\\nreturn [{ json: { ...session, con, rounds, currentRound: nextRound, done } }];"},"id":"36ab9eb1-9397-43c9-9435-6154cd4392e9","name":"💾 Save Round","type":"n8n-nodes-base.code","typeVersion":2,"position":[-800,1216]},{"parameters":{"conditions":{"options":{"typeValidation":"loose"},"conditions":[{"id":"cond-done","leftValue":"={{ $json.done }}","rightValue":true,"operator":{"type":"boolean","operation":"equals"}}],"combinator":"and"},"options":{}},"id":"8e0bf7f2-6232-472a-a64d-a7e3284e065d","name":"❓ Done?","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-560,1216]},{"parameters":{"amount":1},"id":"1d2d155a-364d-465e-bca0-1366ffd0af77","name":"⏳ Wait 1s","type":"n8n-nodes-base.wait","typeVersion":1.1,"position":[-320,1088],"webhookId":"wait-loop-v1"},{"parameters":{"jsCode":"return [$input.first()];"},"id":"211ce52a-ff7d-4021-b4d7-4f2c8520168e","name":"🔁 Loop Back","type":"n8n-nodes-base.code","typeVersion":2,"position":[-128,1088]},{"parameters":{"jsCode":"const d = $input.first().json;\\n\\nconst hist = d.rounds.map(r =>\\n  `Vòng ${r.round}:\\\\n- ỦNG HỘ: ${r.pro}\\\\n- PHẢN ĐỐI: ${r.con}`\\n).join('\\\\n\\\\n');\\n\\nconst body = {\\n  model: 'claude-haiku-4-5-20251001',\\n  max_tokens: 800,\\n  messages: [\\n    {\\n      role: 'user',\\n      content: `Bạn là TRỌNG TÀI khách quan. Hãy phân tích cuộc tranh luận sau bằng TIẾNG VIỆT:\\\\n\\\\nChủ đề: ${d.topic}\\\\n\\\\n${hist}\\\\n\\\\nNhiệm vụ:\\\\n1. Tóm tắt lập luận chính mỗi bên (2 câu)\\\\n2. Đánh giá chất lượng lập luận\\\\n3. Kết luận bên nào thuyết phục hơn và lý do\\\\n4. Quan điểm cân bằng cuối cùng`\\n    }\\n  ]\\n};\\n\\nreturn [{ json: { ...d, _body: JSON.stringify(body) } }];"},"id":"50bdfe97-cb1b-4734-9a7d-7f9a13f99aa4","name":"📝 Prep Judge","type":"n8n-nodes-base.code","typeVersion":2,"position":[-320,1360]},{"parameters":{"method":"POST","url":"https://api.anthropic.com/v1/messages","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"},{"name":"anthropic-version","value":"2023-06-01"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={{ $json._body }}","options":{"timeout":60000}},"id":"dad4556a-88ed-470c-9cc8-6fb758f064ec","name":"⚖️ Claude Judge","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-80,1360]},{"parameters":{"jsCode":"const session = $('📝 Prep Judge').item.json;\\nconst raw = $input.first().json;\\n\\nconst verdict = raw.content?.[0]?.text || '[Claude không phản hồi]';\\n\\nlet out = `🏁 **TRANH LUẬN KẾT THÚC!**\\\\n`;\\nout += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\\\\n`;\\nout += `📌 Chủ đề: ${session.topic}\\\\n`;\\nout += `🔄 Số vòng: ${session.rounds.length}/${session.maxRounds}\\\\n`;\\nout += `🟢 ChatGPT → ỦNG HỘ\\\\n`;\\nout += `🔵 Gemini  → PHẢN ĐỐI\\\\n`;\\nout += `⚖️ Claude  → TRỌNG TÀI\\\\n`;\\nout += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\\\\n\\\\n`;\\n\\nsession.rounds.forEach(r => {\\n  out += `**🔄 VÒNG ${r.round}**\\\\n`;\\n  out += `🟢 ỦNG HỘ: ${r.pro}\\\\n\\\\n`;\\n  out += `🔵 PHẢN ĐỐI: ${r.con}\\\\n`;\\n  out += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\\\\n\\\\n`;\\n});\\n\\nout += `⚖️ **PHÁN QUYẾT (Claude):**\\\\n${verdict}`;\\n\\nreturn [{ json: { output: out } }];"},"id":"e7ed766c-b944-4b07-86c7-2769fdd89ad6","name":"📋 Format Result","type":"n8n-nodes-base.code","typeVersion":2,"position":[160,1360]},{"parameters":{"mode":"chooseBranch","output":"all"},"id":"9aa2e16e-b828-4ade-8cc6-b14337eea4dd","name":"🔀 Merge","type":"n8n-nodes-base.merge","typeVersion":3,"position":[400,1440]},{"parameters":{"jsCode":"const items = $input.all();\\nconst item = items.find(i => i.json.output) || items[0];\\nreturn [{ json: { output: item.json.output || 'OK' } }];"},"id":"59646886-7850-4300-8a9c-ef1dcba3837a","name":"⚙️ Pick Reply","type":"n8n-nodes-base.code","typeVersion":2,"position":[608,1440]}]	{"💬 Chat":{"main":[[{"node":"⚙️ Parse Input","type":"main","index":0}]]},"⚙️ Parse Input":{"main":[[{"node":"❓ Is Debate?","type":"main","index":0}]]},"❓ Is Debate?":{"main":[[{"node":"📝 Prep PRO","type":"main","index":0}],[{"node":"💬 Command Reply","type":"main","index":0}]]},"💬 Command Reply":{"main":[[{"node":"🔀 Merge","type":"main","index":1}]]},"📝 Prep PRO":{"main":[[{"node":"🟢 ChatGPT PRO","type":"main","index":0}]]},"🟢 ChatGPT PRO":{"main":[[{"node":"📝 Prep CON","type":"main","index":0}]]},"📝 Prep CON":{"main":[[{"node":"🔵 Gemini CON","type":"main","index":0}]]},"🔵 Gemini CON":{"main":[[{"node":"💾 Save Round","type":"main","index":0}]]},"💾 Save Round":{"main":[[{"node":"❓ Done?","type":"main","index":0}]]},"❓ Done?":{"main":[[{"node":"📝 Prep Judge","type":"main","index":0}],[{"node":"⏳ Wait 1s","type":"main","index":0}]]},"⏳ Wait 1s":{"main":[[{"node":"🔁 Loop Back","type":"main","index":0}]]},"🔁 Loop Back":{"main":[[{"node":"📝 Prep PRO","type":"main","index":0}]]},"📝 Prep Judge":{"main":[[{"node":"⚖️ Claude Judge","type":"main","index":0}]]},"⚖️ Claude Judge":{"main":[[{"node":"📋 Format Result","type":"main","index":0}]]},"📋 Format Result":{"main":[[{"node":"🔀 Merge","type":"main","index":0}]]},"🔀 Merge":{"main":[[{"node":"⚙️ Pick Reply","type":"main","index":0}]]}}	2026-03-04 09:06:25.532+00	2026-03-04 09:57:21.059+00	{"executionOrder":"v1","binaryMode":"separate","availableInMCP":false}	\N	{}	c06e1eb5-5bce-4686-8967-15a60355a38f	0	NroX2dfeprwlNNP2	{"templateCredsSetupCompleted":true}	\N	f	37	\N	\N	[]	\N
Generate AI Viral Videos	f	[{"parameters":{"content":"## | Step 1: Generate Clips (Wavespeed AI)\\n","height":240,"width":880,"color":2},"id":"1f4bc354-b02c-463a-a290-ac72aabd9217","name":"Sticky Note10","type":"n8n-nodes-base.stickyNote","position":[48,624],"typeVersion":1},{"parameters":{"content":"## | Step 2: Generate Sounds (Fal AI)\\n","height":240,"width":640,"color":2},"id":"ba5539f7-594f-4ceb-9e5f-49352e1f87e5","name":"Sticky Note13","type":"n8n-nodes-base.stickyNote","position":[976,624],"typeVersion":1},{"parameters":{"content":"## | INPUT: Starting Idea Section","height":540,"width":1560,"color":7},"id":"fcb9dcfa-9d00-444d-a55d-c46579d7c87b","name":"Sticky Note14","type":"n8n-nodes-base.stickyNote","position":[48,64],"typeVersion":1},{"parameters":{"content":"## | Step 3: Stitch Video (Fal AI)","height":260,"width":1560,"color":3},"id":"e3e3388e-2552-4e7d-8b0d-42e2c331e51d","name":"Sticky Note","type":"n8n-nodes-base.stickyNote","position":[48,912],"typeVersion":1},{"parameters":{"content":"## | Step 4 — Publish Video to Social Media\\n","height":760,"width":1560,"color":4},"id":"b31345c4-9828-421d-9d48-d72369a7abdc","name":"Sticky Note2","type":"n8n-nodes-base.stickyNote","position":[48,1216],"typeVersion":1,"disabled":true},{"parameters":{"rule":{"interval":[{}]}},"id":"e4dd6321-d209-4894-b145-0845ee3332a8","name":"Trigger: Start Daily Content Generation","type":"n8n-nodes-base.scheduleTrigger","position":[112,176],"typeVersion":1.2},{"parameters":{"promptType":"define","text":"Generate a creative concept involving:\\n\\n[[\\nA solid, hard material or element being sliced cleanly with a sharp blade. Your response must follow this structure:\\n\\n\\"(Color) (Material) shaped like a (random everyday object)\\"\\n\\nFor inspiration, imagine examples like: obsidian shaped like a chess piece, quartz shaped like a coffee mug, sapphire shaped like a seashell, or titanium shaped like a leaf.\\n\\n]]\\n\\nReflect carefully before answering to ensure originality and visual appeal.\\n\\nUse the Think tool to review your output","hasOutputParser":true,"options":{"systemMessage":"=**Role:**  \\nYou are an AI designed to generate **one immersive, realistic idea** based on a user-provided topic. Your output must be formatted as a **single-line JSON array** and follow the rules below exactly.\\n\\n---\\n\\n### RULES\\n\\n1. **Number of ideas**  \\n   - Return **only one idea**.\\n\\n2. **Topic**  \\n   - The user will provide a keyword (e.g., “glass cutting ASMR,” “wood carving sounds,” “satisfying rock splits”).\\n\\n3. **Idea**  \\n   - Maximum 13 words.  \\n   - Describe a viral-worthy, original, or surreal moment related to the topic.\\n\\n4. **Caption**  \\n   - Short, punchy, viral-friendly.  \\n   - Include **one emoji**.  \\n   - Exactly **12 hashtags** in this order:  \\n     1. 4 topic-relevant hashtags  \\n     2. 4 all-time most popular hashtags  \\n     3. 4 currently trending hashtags (based on live research)  \\n   - All in lowercase.\\n\\n5. **Environment**  \\n   - Maximum 20 words.  \\n   - Must match the action in the Idea exactly.  \\n   - Specify location (studio table, natural terrain, lab bench…), visual details (dust particles, polished surface, subtle reflections…), and style (macro close-up, cinematic slow-motion, minimalist…).\\n\\n6. **Sound**  \\n   - Maximum 15 words.  \\n   - Describe the primary sound for the scene (to feed into an audio model).\\n\\n7. **Status**  \\n   - Always set to `\\"for production\\"`.\\n\\n---\\n\\n### OUTPUT FORMAT (single-line JSON array)\\n\\n```json\\n[\\n  {\\n    \\"Caption\\": \\"Your short viral title with emoji #4_topic_hashtags #4_all_time_popular_hashtags #4_trending_hashtags\\",\\n    \\"Idea\\": \\"Your idea under 13 words\\",\\n    \\"Environment\\": \\"Your vivid setting under 20 words matching the action\\",\\n    \\"Sound\\": \\"Your primary sound description under 15 words\\",\\n    \\"Status\\": \\"for production\\"\\n  }\\n]\\n"}},"id":"51e50ec9-0c02-4e92-b4a7-91a449387e64","name":"AI Agent: Generate Creative Video Idea","type":"@n8n/n8n-nodes-langchain.agent","position":[432,176],"typeVersion":1.9},{"parameters":{},"id":"194807dd-7dfe-4abb-b738-ce6f279c8aa8","name":"Tool: Inject Creative Perspective (Idea)","type":"@n8n/n8n-nodes-langchain.toolThink","position":[560,448],"typeVersion":1},{"parameters":{"jsonSchemaExample":"[\\n  {\\n    \\"Caption\\": \\"Diver Removes Nets Off Whale 🐋 #whalerescue #marinelife #oceanrescue #seahelpers #love #nature #instagood #explore #viral #savenature #oceanguardians #cleanoceans\\",\\n    \\"Idea\\": \\"Diver carefully cuts tangled net from distressed whale in open sea\\",\\n    \\"Environment\\": \\"Open ocean, sunlight beams through water, diver and whale, cinematic realism\\",\\n    \\"Sound\\": \\"Primary sound description under 15 words\\",\\n    \\"Status\\": \\"for production\\"\\n  }\\n]\\n"},"id":"ccc080e8-c799-4708-a0d5-03b7a607ba72","name":"Parse AI Output (Idea, Environment, Sound)","type":"@n8n/n8n-nodes-langchain.outputParserStructured","position":[720,448],"typeVersion":1.2},{"parameters":{"operation":"append","documentId":{"__rl":true,"mode":"id","value":"125AN9c45wqNiaMY1zATRkFGtn1Bt6nhD2TtfeZ0ZQlg"},"sheetName":{"__rl":true,"mode":"id","value":"gid=0"},"columns":{"mappingMode":"defineBelow","value":{"ID":"==ROW()-1","Ideal":"={{ $json.output[0].Idea }}","Caption":"={{ $json.output[0].Caption }}","Environment_prompt":"={{ $json.output[0].Environment }}","Sound_prompt":"={{ $json.output[0].Sound }}","Production":"={{ $json.output[0].Status }}"},"matchingColumns":["output"],"schema":[{"id":"ID","displayName":"ID","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true,"removed":false},{"id":"Ideal","displayName":"Ideal","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true,"removed":false},{"id":"Caption","displayName":"Caption","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true,"removed":false},{"id":"Production","displayName":"Production","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true,"removed":false},{"id":"Environment_prompt","displayName":"Environment_prompt","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true,"removed":false},{"id":"Sound_prompt","displayName":"Sound_prompt","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true,"removed":false},{"id":"Final_output","displayName":"Final_output","required":false,"defaultMatch":false,"display":true,"type":"string","canBeUsedToMatch":true,"removed":false}],"attemptToConvertTypes":false,"convertFieldsToString":false},"options":{}},"id":"0b01a81c-5479-4abe-9c10-290c2a3cd4b9","name":"Save Idea & Metadata to Google Sheets","type":"n8n-nodes-base.googleSheets","position":[896,176],"typeVersion":4.5},{"parameters":{"promptType":"define","text":"=Give me 3 video prompts based on the previous idea\\n\\nUse the Think tool to review your output","hasOutputParser":true,"options":{"systemMessage":"=Role: You are a prompt-generation AI specializing in cinematic, ASMR-style video prompts. Your task is to generate a multi-scene video sequence that vividly shows a sharp knife actively cutting through a specific object in a clean, high-detail setting.\\n\\nYour writing must follow this style:\\n\\nSharp, precise cinematic realism.\\n\\nMacro-level detail with tight focus on the blade interacting with the object.\\n\\nThe knife must always be in motion — slicing, splitting, or gliding through the material. Never idle or static.\\n\\nCamera terms are allowed (e.g. macro view, tight angle, over-the-blade shot).\\n\\nEach scene must contain all of the following, expressed through detailed visual language:\\n\\n✅ The main object or subject (from the Idea)\\n\\n✅ The cutting environment or surface (from the Environment)\\n\\n✅ The texture, structure, and behavior of the material as it’s being cut\\n\\n✅ A visible, sharp blade actively cutting\\n\\nDescriptions should show:\\n\\nThe physical makeup of the material — is it translucent, brittle, dense, reflective, granular, fibrous, layered, or fluid-filled?\\n\\nHow the material responds to the blade — resistance, cracking, tearing, smooth separation, tension, vibration.\\n\\nThe interaction between the blade and the surface — light reflection, buildup of particles, contact points, residue or dust.\\n\\nAny ASMR-relevant sensory cues like particle release, shimmer, or subtle movement, but always shown visually — not narrated.\\n\\nTone:\\n\\nClean, clinical, visual.\\n\\nNo poetic metaphors, emotion, or storytelling.\\n\\nAvoid fantasy or surreal imagery.\\n\\nAll description must feel physically grounded and logically accurate.\\n\\nLength:\\n\\nEach scene must be between 1,000 and 2,000 characters.\\n\\nNo shallow or repetitive scenes — each must be immersive, descriptive, and specific.\\n\\nEach scene should explore a distinct phase of the cutting process, a different camera perspective, or a new behavior of the material under the blade.\\n\\nInputs:\\n\\nIdea: \\"{{ $json.idea }}\\"\\nEnvironment: \\"{{ $json.environment_prompt }}\\"\\nSound: \\"{{ $json.sound_prompt }}\\"\\n\\nFormat:\\n\\nIdea: \\"...\\"\\nEnvironment: \\"...\\"\\nSound: \\"...\\"\\n\\nScene 1: \\"...\\"\\nScene 2: \\"...\\"\\nScene 3: \\"...\\"\\nScene 4: \\"...\\"\\nScene 5: \\"...\\"\\nScene 6: \\"...\\"\\nScene 7: \\"...\\"\\nScene 8: \\"...\\"\\nScene 9: \\"...\\"\\nScene 10: \\"...\\"\\nScene 11: \\"...\\"\\nScene 12: \\"...\\"\\nScene 13: \\"...\\"\\n\\n"}},"id":"3cd1c497-6cc6-4d03-bd5f-578fd32aa2f9","name":"AI Agent: Generate Detailed Video Prompts","type":"@n8n/n8n-nodes-langchain.agent","position":[1232,176],"typeVersion":1.9},{"parameters":{"model":{"__rl":true,"mode":"list","value":"gpt-4.1","cachedResultName":"gpt-4.1"},"options":{}},"id":"3b2e69b1-c2d7-48a9-a747-eed16d92f2b7","name":"LLM: Draft Video Prompt Details (GPT-4.1)","type":"@n8n/n8n-nodes-langchain.lmChatOpenAi","position":[1136,448],"typeVersion":1.2},{"parameters":{},"id":"b1eb3076-b8d9-4ffa-b7ab-f66f8c67b79f","name":"Tool: Refine and Validate Prompts1","type":"@n8n/n8n-nodes-langchain.toolThink","position":[1312,448],"typeVersion":1},{"parameters":{"jsonSchemaExample":"{\\n  \\"Idea\\": \\"An obsidian rock being sliced with a shimmering knife\\",\\n  \\"Environment\\": \\"Clean studio table, subtle light reflections\\",\\n  \\"Sound\\": \\"Crisp slicing, deep grinding, and delicate crumbling\\",\\n  \\"Scene 1\\": \\"Extreme macro shot: a razor-sharp, polished knife blade presses into the dark, granular surface of an obsidian rock, just beginning to indent.\\",\\n  \\"Scene 2\\": \\"Close-up: fine, iridescent dust particles erupt from the point of contact as the blade cuts deeper into the obsidian, catching the studio light.\\",\\n  \\"Scene 3\\": \\"Mid-shot: the knife, held perfectly steady, has formed a shallow, clean groove across the obsidian's shimmering surface, revealing a new, smooth texture.\\"\\n}"},"id":"6bb8fa8d-a9d3-4939-ae52-0d5052e65cf7","name":"Parse Structured Video Prompt Output","type":"@n8n/n8n-nodes-langchain.outputParserStructured","position":[1472,448],"typeVersion":1.2},{"parameters":{"jsCode":"function findSceneEntries(obj) {\\n  const scenes = [];\\n\\n  for (const [key, value] of Object.entries(obj)) {\\n    if (key.toLowerCase().startsWith(\\"scene\\") && typeof value === \\"string\\") {\\n      scenes.push(value);\\n    } else if (typeof value === \\"object\\" && value !== null) {\\n      scenes.push(...findSceneEntries(value));\\n    }\\n  }\\n\\n  return scenes;\\n}\\n\\nlet output = [];\\n\\ntry {\\n  const inputData = items[0].json;\\n  const scenes = findSceneEntries(inputData);\\n\\n  if (scenes.length === 0) {\\n    throw new Error(\\"No scene keys found at any level.\\");\\n  }\\n\\n  output = scenes.map(scene => ({ description: scene }));\\n} catch (e) {\\n  throw new Error(\\"Could not extract scenes properly. Details: \\" + e.message);\\n}\\n\\nreturn output;\\n"},"id":"200c2980-1c73-4352-a337-d59cc3c6e079","name":"Extract Individual Scene Descriptions","type":"n8n-nodes-base.code","position":[160,704],"typeVersion":2},{"parameters":{"amount":240},"id":"742f72c5-1a9d-47c8-8d7c-38a8c3cbfab5","name":"Wait for Clip Generation (Wavespeed AI)","type":"n8n-nodes-base.wait","position":[560,704],"webhookId":"54c74ddb-3e61-49a4-9006-4134e7ed39e9","typeVersion":1.1},{"parameters":{"url":"=https://api.wavespeed.ai/api/v3/predictions/{{ $json.data.id }}/result","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","options":{}},"id":"0ff2d52a-000f-41df-911e-46c904339b35","name":"Retrieve Video Clips","type":"n8n-nodes-base.httpRequest","position":[752,704],"typeVersion":4.2},{"parameters":{"method":"POST","url":"https://queue.fal.run/fal-ai/mmaudio-v2 ","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendBody":true,"contentType":"raw","rawContentType":"application/json","body":"= {\\n        \\"prompt\\": \\"ASMR Soothing sound effects. {{ $('AI Agent: Generate Detailed Video Prompts').item.json.output.Sound }}\\",\\n        \\"duration\\": 10,\\n        \\"video_url\\": \\"{{ $json.data.outputs[0] }}\\"\\n  }\\n","options":{"batching":{"batch":{"batchSize":1,"batchInterval":2000}}}},"id":"e5a73896-9774-447b-ae2f-1cd1944f3847","name":"Generate ASMR Sound (Fal AI)","type":"n8n-nodes-base.httpRequest","position":[1040,704],"typeVersion":4.2},{"parameters":{"amount":60},"id":"a7f8c50b-4a29-4958-9763-3df0f47d1097","name":"Wait for Sound Generation (Fal AI)","type":"n8n-nodes-base.wait","position":[1232,704],"webhookId":"1ff1e4a4-d546-43a3-89bd-5b0292db887f","typeVersion":1.1},{"parameters":{"url":"=https://queue.fal.run/fal-ai/mmaudio-v2/requests/{{ $json.request_id }}","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","options":{}},"id":"