._';\\n  try {\\n    await fetch('https://api.telegram.org/bot' + bot_token + '/sendMessage', {\\n      method: 'POST',\\n      headers: { 'Content-Type': 'application/json' },\\n      body: JSON.stringify({ chat_id, text: msg, parse_mode: 'Markdown' })\\n    });\\n  } catch(e) {}\\n}\\nreturn [{ json: { thanh_cong: true, ma_tai_san: d.ma_tai_san } }];"},"id":"58ce742c-7c08-4daf-8cf2-c0024c85f287","name":"07_Bao_Cao_Telegram","type":"n8n-nodes-base.code","typeVersion":2,"position":[7328,944]}]	{"Kich_Hoat_Ho_So_Vao":{"main":[[{"node":"Tien_Kiem_Tra_Ho_So","type":"main","index":0}]]},"Kiem_Tra_Trang_Thai_Sheet":{"main":[[{"node":"IF_Da_Phe_Duyet","type":"main","index":0}]]},"IF_Da_Phe_Duyet":{"main":[[{"node":"Tai_Prompt_Quy_Tac_Drive","type":"main","index":0}],[{"node":"Chuyen_File_Loi_Va_Alert","type":"main","index":0}]]},"Tai_Prompt_Quy_Tac_Drive":{"main":[[{"node":"Tai_File_Ho_So_Khach","type":"main","index":0}]]},"Tai_File_Ho_So_Khach":{"main":[[{"node":"Gemini_Extract_Du_Lieu","type":"main","index":0}]]},"Gemini_Extract_Du_Lieu":{"main":[[{"node":"Kiem_Dinh_Validator_JS","type":"main","index":0}]]},"Kiem_Dinh_Validator_JS":{"main":[[{"node":"Luu_File_JSON_Drive","type":"main","index":0}]]},"Luu_File_JSON_Drive":{"main":[[{"node":"Ghi_Log_Sheets_Van_Hanh","type":"main","index":0}]]},"Ghi_Log_Sheets_Van_Hanh":{"main":[[{"node":"Bao_Ket_Qua_Telegram","type":"main","index":0}]]},"Kich_Hoat_Yeu_Cau_Duyet":{"main":[[{"node":"Kiem_Thu_Hoi_Quy_Dice","type":"main","index":0}]]},"Kiem_Thu_Hoi_Quy_Dice":{"main":[[{"node":"Cap_Nhat_Trang_Thai_Duyet","type":"main","index":0}]]},"Cap_Nhat_Trang_Thai_Duyet":{"main":[[{"node":"Bao_Duyet_Telegram","type":"main","index":0}]]},"Tien_Kiem_Tra_Ho_So":{"main":[[{"node":"Kiem_Tra_Trang_Thai_Sheet","type":"main","index":0}]]},"Ghi_Sheets_CHO_DUYET":{"main":[[{"node":"Bao_Hoc_Xong_Telegram","type":"main","index":0}]]},"Ghi_Cau_Hinh_Drive":{"main":[[{"node":"Ghi_Sheets_CHO_DUYET","type":"main","index":0}]]},"Gemini_Phan_Tich_Mau":{"main