&&\\n    q.Explanation\\n  ) {\\n    questions.push({\\n      question: q.question,\\n      choices: q.choices,\\n      correctAnswer: q.correctAnswer,\\n      Explanation: q.Explanation,\\n      imagePrompt: q.imagePrompt || \\"\\",\\n      imageName: q.imageName || \\"\\",\\n      imageUrl: imageUrl\\n    });\\n  }\\n}\\n\\n// Chỉ lấy thông tin chung từ item đầu tiên (nếu cần)\\nconst first = items[0]?.json || {};\\n\\nreturn [\\n  {\\n    json: {\\n      \\"Môn học\\": first[\\"Môn học\\"] || \\"\\",\\n      \\"Chủ đề\\": first[\\"Chủ đề\\"] || \\"\\",\\n      \\"Lớp\\": first[\\"Lớp\\"] || \\"\\",\\n      \\"Cấp độ\\": first[\\"Cấp độ\\"] || \\"\\",\\n      questions\\n    }\\n  }\\n];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2096,544],"id":"0ecb72b2-3c0c-46a9-a8c1-b50cd9ca93e8","name":"Parse JSON1"},{"parameters":{"jsCode":"const repeat = parseInt($input.first().json['Sốcâu hỏi cần tạo'] || 1);\\nconst input = $json;\\nconst output = [];\\n\\nfor (let i = 0; i < repeat; i++) {\\n  output.push({\\n    json: {\\n      ...input,\\n      repeatIndex: i + 1,\\n    }\\n  });\\n}\\n\\nreturn output;\\n"},"id":"d0c10d34-8b4d-4780-9ec0-8216f8d3980c","name":"Tạo bản sao bài Quiz","type":"n8n-nodes-base.code","typeVersion":2,"position":[832,256]},{"parameters":{"formTitle":"Tạo bài trắc nghiệm !","formFields":{"values":[{"fieldLabel":"Môn học","fieldType":"dropdown","fieldOptions":{"values":[{"option":"Tiếng Anh"},{"option":"Toán"},{"option":"Tiếng Việt"}]},"requiredField":true},{"fieldLabel":"Chủ đề"},{"fieldLabel":"Lớp","fieldType":"dropdown","fieldOptions":{"values":[{"option":"Lớp 1"},{"option":"Lớp 2"},{"option":"Lớp 3"},{"option":"Lớp 4"},{"option":"Lớp 5"},{"option":"Lớp 6"},{"option":"Lớp 7"},{"option":"Lớp 8"},{"option":"Lớp 9"},{"option":"Lớp 10"},{"option":"Lớp 11"},{"option":"Lớp 12"}]},"requiredField":true},{"fieldLabel":"Cấp độ","fieldType":"dropdown","fieldOptions":{"values":[{"option":"bình thường"},{"option":"khó"},{"option":"rất khó"}]},"requiredField":true},{"fieldLabel":"Sốcâu hỏi cần tạo","fieldType":"number","placeholder":"1","requiredField":true}]},"options":{}},"type":"n8n-nodes-base.formTrigger","typeVersion":2.2,"position":[224,240],"id":"485a7663-63b9-4a28-8bd1-beaf10b9f804","name":"On form submission","webhookId":"353ea294-47b8-454d-9faf-a8572f270691"},{"parameters":{"mode":"combine","combineBy":"combineAll","options":{}},"type":"n8n-nodes-base.merge","typeVersion":3.2,"position":[656,256],"id":"24568d2e-9c61-4ea2-b6fc-78831470b015","name":"Merge","alwaysOutputData":true},{"parameters":{"method":"POST","url":"https://script.google.com/macros/s/AKfycbyN-XqLokk0ayfqdLGd4UotiMmJXBhwzsSSlxpAA9iGOKdq5bBYwM06N_fo5BZUhZio/exec","authentication":"predefinedCredentialType","nodeCredentialType":"googleDriveOAuth2Api","sendBody":true,"bodyParameters":{"parameters":[{"name":"formUrl","value":"={{ $json.formUrl }}"},{"name":"=Môn học","value":"={{ $('Parse JSON2').item.json[\\"Môn học\\"] }}"},{"name":"Chủ đề","value":"={{ $('Parse JSON2').item.json[\\"Chủ đề\\"] }}"},{"name":"Lớp","value":"={{ $('Parse JSON2').item.json[\\"Lớp\\"] }}"},{"name":"Cấp độ","value":"={{ $('Parse JSON2').item.json[\\"Cấp độ\\"] }}"},{"name":"Số lượng câu hỏi","value":"={{ $('Parse JSON2').item.json[\\"Số lượng câu hỏi\\"] }}"},{"name":"Đề thi số","value":"={{ $('Parse JSON2').item.json[\\"Đề thi số\\"] }}"},{"name":"responseUrl","value":"={{ $json.responseUrl }}"}]},"options":{}},"id":"96d95915-e01a-4d85-86e3-c6950beb198e","name":"Tao LinkQuiz","type":"n8n-nodes-base.httpRequest","position":[1552,1040],"typeVersion":4.2,"retryOnFail":true,"waitBetweenTries":5000,"credentials":{"googleDriveOAuth2Api":{"id":"rTUSZlOSjhGVDCDG","name":"Google Drive account LETRUNG80.HUE"}}},{"parameters":{"method":"POST","url":"https://script.google.com/macros/s/AKfycbz3_06T8uXuSBmIb_WkJRkSdweTFHuHCL470EcCimDOMzyTuuNx1BTjGlChy2l9xJGj/exec","authentication":"predefinedCredentialType","nodeCredentialType":"googleDriveOAuth2Api","sendQuery":true,"queryParameters":{"parameters":[{"name":"Môn học","value":"={{ $json[\\"Môn học\\"] }}"}]},"sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={{ $json}}","options":{}},"id":"7f13c19f-a2cd-4cb2-88a0-1da422d1e697","name":"Tao Google Form","type":"n8n-nodes-base.httpRequest","position":[1408,1040],"typeVersion":4.2,"retryOnFail":true,"waitBetweenTries":5000,"credentials":{"googleDriveOAuth2Api":{"id":"WxxAcetQyelhNKX1","name":"Google Drive ACC ngdletrung"}}},{"parameters":{"documentId":{"__rl":true,"value":"1VJzNqZ3CGmxYNaTRCy5P1L2oda0Pawu7mzw57lBwqZk","mode":"id"},"sheetName":{"__rl":true,"value":"={{ $json[\\"Lớp\\"] }}","mode":"name"},"filtersUI":{"values":[{"lookupColumn":"=Môn học","lookupValue":"={{ $json[\\"Môn học\\"] }}"}]},"options":{}},"type":"n8n-nodes-base.googleSheets","typeVersion":4.6,"position":[448,928],"id":"13a231b3-9b6f-444b-8d93-dc2fb53f810f","name":"ReadFile","retryOnFail":true,"waitBetweenTries":5000},{"parameters":{"jsCode":"// 1. Lấy toàn bộ câu hỏi từ Google Sheet\\nconst allQuestions = items.map(item => item.json);\\n\\n// 2. Lấy thông tin từ form submission\\nconst inputData = $('On form submission1').first().json;\\nconst targetLevel = inputData[\\"Cấp độ\\"] || null;\\nconst soLuongCauHoi = parseInt((inputData[\\"Số lượng câu hỏi\\"] || \\"0\\").replace(\\" câu\\", \\"\\")) || 10;\\nconst soDe = parseInt(inputData[\\"Số bài  Quiz cần tạo\\"] || \\"1\\");\\nconst chuDe = inputData[\\"Chủ đề\\"] || \\"\\";\\nconst monHoc = inputData[\\"Môn học\\"] || \\"\\";\\nconst lop = inputData[\\"Lớp\\"] || \\"\\";\\n\\n// ✅ Cấu hình: Cho phép trùng giữa các đề, nhưng không trùng trong 1 đề\\nconst chophep_cacdetrunglap = true;\\n\\n// 3. Lọc theo cấp độ nếu có, trừ khi là \\"cấp độ ngẫu nhiên\\"\\nlet filtered = allQuestions;\\nif (targetLevel && targetLevel.trim().toLowerCase() !== \\"cấp độ ngẫu nhiên\\") {\\n  filtered = filtered.filter(q => q[\\"Cấp độ\\"] === targetLevel);\\n}\\n\\n// ✅ Sắp xếp theo row_number để ổn định\\nfiltered = filtered.sort((a, b) => parseInt(a.row_number) - parseInt(b.row_number));\\n\\n// ✅ Nếu không cho phép trùng giữa các đề, cần kiểm tra số lượng đủ\\nif (!chophep_cacdetrunglap && filtered.length < soLuongCauHoi * soDe) {\\n  throw new Error(`Không đủ câu hỏi để tạo ${soDe} đề, mỗi đề ${soLuongCauHoi} câu (Cần ${soDe * soLuongCauHoi}, có ${filtered.length})`);\\n}\\n\\n// 4. Lấy STT đề thi từ node trước\\nconst sttStart = parseInt($('Lấy STT Đề Thi').first().json[\\"Đề thi số\\"] || '0') + 1;\\n\\n// 5. Bắt đầu tạo đề\\nconst output = [];\\nconst usedRowNumbersGlobal = new Set(); // chỉ dùng nếu không cho phép trùng giữa các đề\\n\\nfor (let i = 0; i < soDe; i++) {\\n  const deThiSo = sttStart + i;\\n  const usedRowNumbersLocal = new Set(); // đảm bảo không trùng trong 1 đề\\n  let selected = [];\\n\\n  if (chophep_cacdetrunglap) {\\n    // ✅ Cho phép trùng giữa các đề, nhưng không trùng trong 1 đề\\n    const shuffled = [...filtered].sort(() => Math.random() - 0.5);\\n\\n    for (const item of shuffled) {\\n      const rowNum = item.row_number;\\n      if (!usedRowNumbersLocal.has(rowNum)) {\\n        selected.push(item);\\n        usedRowNumbersLocal.add(rowNum);\\n        if (selected.length === soLuongCauHoi) break;\\n      }\\n    }\\n\\n    if (selected.length < soLuongCauHoi) {\\n      throw new Error(`❌ Đề số ${deThiSo} chỉ lấy được ${selected.length}/${soLuongCauHoi} câu không trùng. Kiểm tra lại dữ liệu.`);\\n    }\\n\\n  } else {\\n    // ❌ Không cho phép trùng giữa các đề\\n    for (const item of filtered) {\\n      const rowNum = item.row_number;\\n      if (!usedRowNumbersGlobal.has(rowNum)) {\\n        selected.push(item);\\n        usedRowNumbersGlobal.add(rowNum);\\n        if (selected.length === soLuongCauHoi) break;\\n      }\\n    }\\n\\n    if (selected.length < soLuongCauHoi) {\\n      throw new Error(`❌ Không đủ câu hỏi không trùng để tạo đề số ${deThiSo}`);\\n    }\\n  }\\n\\n  // Parse câu hỏi từ JSON gốc\\n  const questions = selected.map(q => {\\n    let parsed;\\n    try {\\n      parsed = JSON.parse(q[\\"Câu hỏi\\"]);\\n    } catch (err) {\\n      parsed = {\\n        question: \\"❌ Lỗi phân tích 'Câu hỏi'\\",\\n        raw: q[\\"Câu hỏi\\"]\\n      };\\n    }\\n\\n    // Nếu thiếu imageUrl thì thêm từ \\"Link Image\\"\\n    if (!parsed.imageUrl && q[\\"Link Image\\"]) {\\n      parsed.imageUrl = q[\\"Link Image\\"];\\n    }\\n\\n    return parsed;\\n  });\\n\\n  // Tiêu đề đề thi\\n  const title = chuDe.trim()\\n    ? `Bài kiểm tra Môn học: ${monHoc} với ${chuDe} - ${lop}\\\\nCấp độ: ${targetLevel}\\\\nĐề thi số: ${deThiSo}`\\n    : `Bài kiểm tra Môn học: ${monHoc} - ${lop}\\\\nCấp độ: ${targetLevel}\\\\nĐề thi số: ${deThiSo}`;\\n\\n  // Push kết quả ra output\\n  output.push({\\n    json: {\\n      title,\\n      questions,\\n      \\"Môn học\\": monHoc,\\n      \\"Chủ đề\\": chuDe,\\n      \\"Lớp\\": lop,\\n      \\"Cấp độ\\": targetLevel,\\n      \\"Số lượng câu hỏi\\": soLuongCauHoi,\\n      \\"Số bài Quiz cần tạo\\": soDe,\\n      \\"Đề thi số\\": deThiSo\\n    }\\n  });\\n}\\n\\nreturn output;\\n"},"id":"c16b952a-dd6e-44d0-85fa-2c6ea75e4dd6","name":"Tạo câu hỏi ngẫu nhiên cho  bài Quiz","type":"n8n-nodes-base.code","typeVersion":2,"position":[816,1024]},{"parameters":{"documentId":{"__rl":true,"value":"1Qg0bYNfFaKjI5xYLTYaODJvmJSjMPQYON2C27boHY7s","mode":"id"},"sheetName":{"__rl":true,"value":"Data","mode":"name"},"filtersUI":{"values":[{"lookupColumn":"Lớp","lookupValue":"={{ $json['Lớp'] }}"},{"lookupColumn":"Môn học","lookupValue":"={{ $json['Môn học'] }}"},{"lookupColumn":"Cấp độ","lookupValue":"={{ $json['Cấp độ'] }}"}]},"options":{}},"type":"n8n-nodes-base.googleSheets","typeVersion":4.6,"position":[448,1088],"id":"b2019d4a-1d63-42dc-a82b-58e7f9263f07","name":"Lấy STT Đề Thi","alwaysOutputData":true,"retryOnFail":true,"waitBetweenTries":5000},{"parameters":{"content":"STEP : TẠO CÂU HỎI QUIZ","height":385,"width":1943,"color":5},"id":"7db15e41-6225-4b8c-acf7-2f9276106fc8","name":"Sticky Note","type":"n8n-nodes-base.stickyNote","position":[176,864],"typeVersion":1},{"parameters":{"formTitle":"Tạo bài trắc nghiệm !","formFields":{"values":[{"fieldLabel":"Môn học","fieldType":"dropdown","fieldOptions":{"values":[{"option":"Tiếng Anh"},{"option":"Toán"},{"option":"Tiếng Việt"}]},"requiredField":true},{"fieldLabel":"Chủ đề"},{"fieldLabel":"Lớp","fieldType":"dropdown","fieldOptions":{"values":[{"option":"Lớp 1"},{"option":"Lớp 2"},{"option":"Lớp 3"},{"option":"Lớp 4"},{"option":"Lớp 5"},{"option":"Lớp 6"},{"option":"Lớp 7"},{"option":"Lớp 8"},{"option":"Lớp 9"},{"option":"Lớp 10"},{"option":"Lớp 11"},{"option":"Lớp 12"}]},"requiredField":true},{"fieldLabel":"Số lượng câu hỏi","fieldType":"dropdown","fieldOptions":{"values":[{"option":"10 câu"},{"option":"20 câu"},{"option":"50 câu"},{"option":"100 câu"},{"option":"2 câu"}]},"requiredField":true},{"fieldLabel":"Cấp độ","fieldType":"dropdown","fieldOptions":{"values":[{"option":"bình thường"},{"option":"khó"},{"option":"rất khó"},{"option":"cấp độ ngẫu nhiên"}]},"requiredField":true},{"fieldLabel":"Số bài  Quiz cần tạo","fieldType":"number","placeholder":"1","requiredField":true}]},"options":{}},"type":"n8n-nodes-base.formTrigger","typeVersion":2.2,"position":[256,1008],"id":"5eb8093f-6676-4879-9331-4c2f5589fefa","name":"On form submission1","webhookId":"c52bc803-8fd6-4810-8878-0c0919d17c90","disabled":true},{"parameters":{},"type":"n8n-nodes-base.merge","typeVersion":3.2,"position":[656,1024],"id":"d14c195a-64ee-491c-b517-a2013ed8a42a","name":"Merge1","alwaysOutputData":true},{"parameters":{"options":{"reset":false}},"type":"n8n-nodes-base.splitInBatches","typeVersion":3,"position":[1024,1024],"id":"d76b1fa6-9e19-4f48-b26e-1a0224f6fdbb","name":"Loop Over Items","alwaysOutputData":false},{"parameters":{"jsCode":"// 1. Lấy thông tin đầu vào từ node Merge\\nconst inputInfo = $('Loop Over Items').first().json;\\nconst monhoc = inputInfo[\\"Môn học\\"] || \\"\\";\\nconst chude = inputInfo[\\"Chủ đề\\"] || \\"\\";\\nconst lop = inputInfo[\\"Lớp\\"] || \\"\\";\\nconst soluongcauhoi = inputInfo[\\"Số lượng câu hỏi\\"] || \\"\\";\\nconst capdo = inputInfo[\\"Cấp độ\\"] || \\"\\";\\nconst sobaiquiz = inputInfo[\\"Số bài  Quiz cần tạo\\"] || \\"\\";\\nconst dethiso = inputInfo[\\"Đề thi số\\"] || \\"\\";\\n\\n// 2. Mỗi item đại diện 1 đề có title + questions\\n// Ta chỉ chọn đề đầu tiên (hoặc duyệt từng đề nếu muốn)\\nconst firstItem = items[0].json;\\nconst title = firstItem.title || \\"Bài kiểm tra mặc định\\";\\n\\n// 3. Duyệt câu hỏi trong item đầu tiên\\nconst rawQuestions = firstItem.questions || [];\\nconst questions = rawQuestions.map(q => {\\n  if (\\n    !q.question ||\\n    !Array.isArray(q.choices) ||\\n    !q.correctAnswer ||\\n    !q.Explanation\\n  ) {\\n    return null; // loại bỏ câu lỗi\\n  }\\n\\n  return {\\n    question: q.question,\\n    choices: q.choices,\\n    correctAnswer: q.correctAnswer,\\n    Explanation: q.Explanation,\\n    imageUrl: q.imageUrl || \\"\\"\\n  };\\n}).filter(Boolean); // loại bỏ null\\n\\n// 4. Kết quả trả về 1 object chuẩn hóa\\nconst finalQuiz = {\\n  title,\\n  \\"Môn học\\": monhoc,\\n  \\"Chủ đề\\": chude,\\n  \\"Lớp\\": lop,\\n  \\"Số lượng câu hỏi\\": soluongcauhoi,\\n  \\"Cấp độ\\": capdo,\\n  \\"Số bài Quiz cần tạo\\": sobaiquiz,\\n  \\"Đề thi số\\": dethiso,\\n  questions\\n};\\n\\nreturn [{ json: finalQuiz }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1216,1040],"id":"9220f4b2-a1ef-48a1-8428-3bdf8122c1af","name":"Parse JSON2"},{"parameters":{"chatId":"5584954476","text":"=CÔNG VIỆC BÀI TRẮC NGHIỆM QUIZ ĐÃ HOÀN TẤT !","additionalFields":{}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[1952,992],"id":"a022d0cb-7319-4639-870b-440286f0e678","name":"Send a text message1","webhookId":"0304b6c8-985d-4aeb-9c74-e75c411f777b","credentials":{"telegramApi":{"id":"3dY6VmwOtXaErnPU","name":"Telegram account"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"id":"9d7c7705-e7e7-471a-841c-c71e2930b2ea","leftValue":"={{ $json.status }}","rightValue":"ok","operator":{"type":"string","operation":"equals","name":"filter.operator.equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.2,"position":[1296,128],"id":"7f73e4a1-b153-4ec8-8449-2480da08aa17","name":"If"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"id":"9d7c7705-e7e7-471a-841c-c71e2930b2ea","leftValue":"={{ $json.status }}","rightValue":"ok","operator":{"type":"string","operation":"equals","name":"filter.operator.equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.2,"position":[1760,1008],"id":"dbbbe056-528c-4f5c-9b78-45ec9204e5e3","name":"If1"},{"parameters":{"promptType":"define","text":"={{ $json.prompt }}","hasOutputParser":true,"options":{}},"type":"@n8n/n8n-nodes-langchain.agent","typeVersion":1.7,"position":[1280,272],"id":"9b549612-e740-4e8a-a592-bbc7d7c440da","name":"Tạo câu hỏi trắc nghiệm","retryOnFail":true,"waitBetweenTries":5000},{"parameters":{"jsCode":"const mon = $input.first().json['Môn học'];\\nconst chuDe = $input.first().json['Chủ đề'];\\nconst lop = $input.first().json['Lớp'];\\nconst capDo = $input.first().json['Cấp độ'];\\nconst Xsocauhoi = 5;\\nlet prompt_TiengAnh = `Bạn là một chuyên gia giáo dục ${mon} xuất sắc và chuyên gia prompt. Nhiệm vụ của bạn là tạo ${Xsocauhoi} câu hỏi trắc nghiệm ${mon} chất lượng cao cho học sinh tiểu học. Kết quả đầu ra phải là một đối tượng JSON duy nhất và hoàn hảo, không có bất kỳ văn bản, mã markdown hoặc nội dung nào khác.\\n\\n1. CONTEXT\\nMôn học: ${mon}\\nChủ đề: ${chuDe}\\nLớp: ${lop}\\nCấp độ: ${capDo}\\n\\n2. INSTRUCTION\\nĐộ dài & Nội dung: Tạo chính xác 1 câu hỏi trắc nghiệm với 4 lựa chọn (a, b, c, d).\\n\\nPhù hợp với học sinh: Sử dụng từ vựng và ngữ pháp phù hợp với lứa tuổi ${lop} BÁM SÁT THEO chủ đề: \\"${chuDe}\\" và cấp độ: ${capDo}.\\n\\nTính chính xác: Đảm bảo chỉ có một đáp án đúng.\\n\\nTránh mơ hồ: Các câu hỏi và đáp án phải rõ ràng, không gây nhầm lẫn.\\n\\n3. JSON OUTPUT FORMAT\\nTrả về đối tượng JSON theo cấu trúc sau:\\n{\\n  \\"Môn học\\": \\"${mon}\\",\\n  \\"Chủ đề\\": \\"${chuDe}\\",\\n  \\"Lớp\\": \\"${lop}\\",\\n  \\"Cấp độ\\": \\"${capDo}\\",\\n  \\"questions\\": [\\n    {\\n    \\"question\\": \\"[Câu hỏi tiếng Anh]\\",\\n    \\"choices\\": [\\n      \\"a. [Lựa chọn a]\\",\\n      \\"b. [Lựa chọn b]\\",\\n      \\"c. [Lựa chọn c]\\",\\n      \\"d. [Lựa chọn d]\\"\\n    ],\\n    \\"correctAnswer\\": \\"[Đáp án đúng, ví dụ: 'a. ...']\\",\\n    \\"Explanation\\": \\"\\n          EN:\\n          question: [English question]\\n          a. [Lựa chọn a]: [Correct ✅ or Incorrect ❌ explanation for choice a]\\n          b. [Lựa chọn b]: [Correct ✅ or Incorrect ❌ explanation for choice b]\\n          c. [Lựa chọn c]: [Correct ✅ or Incorrect ❌ explanation for choice c]\\n          d. [Lựa chọn d]: [Correct ✅ or Incorrect ❌ explanation for choice d]\\n          \\n          VN:\\n          question: [Câu hỏi tiếng Việt]\\n          a. [Lựa chọn a]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn a]\\n          b. [Lựa chọn b]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn b]\\n          c. [Lựa chọn c]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn c]\\n         d. [Lựa chọn d]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn d].\\",\\n     \\"imagePrompt\\": \\"Hãy tạo một mô tả hình ảnh bằng tiếng Anh, rõ ràng, sinh động và có tính giáo dục, minh họa cho ý tưởng chính của câu hỏi và đáp án đúng, phù hợp với khả năng hiểu của học sinh.\\n  \\n  Nếu câu hỏi liên quan đến các khái niệm có thể minh họa trực quan (ví dụ: đồ vật, con vật, hành động, bối cảnh), hãy mô tả cảnh minh họa có đầy đủ đối tượng chính, bối cảnh phù hợp và các vật thể phụ trợ có liên quan để hỗ trợ học sinh dễ hiểu và dễ ghi nhớ.\\n  \\n  Nếu câu hỏi là “Mấy giờ rồi?”, hãy mô tả một chiếc đồng hồ rõ ràng hiển thị đúng giờ, đặt trong một bối cảnh sinh hoạt thực tế (ví dụ: lớp học, phòng ngủ buổi sáng, sân chơi giờ ra chơi...).\\n  \\n  Nếu câu hỏi là phép tính số học đơn giản (ví dụ: “3 + 1 bằng mấy?”), không được thể hiện kết quả (ví dụ: số 4). Thay vào đó, hãy minh họa bối cảnh với các đối tượng tương ứng (ví dụ: 3 quả táo + 1 quả táo), kèm theo môi trường xung quanh có màu sắc sinh động và phù hợp với học sinh.\\n  \\n  Nếu câu hỏi mang tính trừu tượng (như ngữ pháp, logic, định nghĩa), hãy trả về chuỗi rỗng \\"\\" và không tạo hình ảnh.\\n  \\n  Phong cách hình ảnh phải phù hợp với học sinh: nhiều màu sắc, thân thiện, dễ tiếp cận. Gợi ý phong cách: \\"2D cartoon illustration\\", \\"watercolor painting\\", \\"flat design\\", hoặc \\"children’s book drawing\\".\\n  \\n  Có thể kết hợp yếu tố văn hóa Việt Nam một cách tự nhiên nếu phù hợp (ví dụ: nhân vật, trang phục, bối cảnh, đồ vật,...).\\n  \\n  ➤ Chỉ trả về chuỗi mô tả ảnh, không cần định dạng đặc biệt hoặc lời giải thích.\\",\\n    \\n    \\"imageName\\": \\"Tạo chuỗi ngắn gọn, viết thường, dùng dấu - thay cho khoảng trắng, mô tả ngắn về đối tượng chính trong hình.\\"\\n    },\\n   {\\n      \\"question\\": \\"[Câu hỏi tiếp theo...]\\",\\n      \\"choices\\": [\\n        \\"a. ...\\",\\n        \\"b. ...\\",\\n        \\"c. ...\\",\\n        \\"d. ...\\"\\n      ],\\n      \\"correctAnswer\\": \\"c. ...\\",\\n      \\"Explanation\\": \\"...\\",\\n      \\"imagePrompt\\": \\"...\\",\\n      \\"imageName\\": \\"...\\"\\n    }\\n  ]\\n}\\n\\n4. IMPORTANT RULES\\nĐịnh dạng JSON: BẮT BUỘC tuân thủ chính xác định dạng JSON trên. Sử dụng dấu ngoặc kép đôi cho tất cả các khóa và giá trị.\\n\\nDuy nhất một đối tượng JSON: Không thêm bất kỳ văn bản nào trước hoặc sau đối tượng JSON.\\nCâu hỏi : tránh lặp lại nhiều lần.\\nGiải thích: Mỗi giải thích cho từng lựa chọn phải ngắn gọn, súc tích trong một câu và sử dụng icon ✅/❌ đặt phía trước.\\n\\nKiểm tra cú pháp: Tự kiểm tra lại cú pháp JSON của bạn để đảm bảo không có lỗi như thiếu dấu phẩy hoặc dấu ngoặc đóng.\\n`;\\nlet prompt_TiengViet = `Bạn là một chuyên gia giáo dục xuất sắc môn ${mon} và chuyên gia prompt tạo ảnh minh họa. Nhiệm vụ của bạn là tạo ${Xsocauhoi} câu hỏi trắc nghiệm môn ${mon} chất lượng cao cho học sinh ${lop}. Kết quả đầu ra phải là một đối tượng JSON duy nhất và hoàn hảo, không có bất kỳ văn bản, mã markdown hoặc nội dung nào khác.\\n\\n1. CONTEXT\\n  \\"Môn học\\": \\"${mon}\\"\\n  \\"Chủ đề\\": \\"${chuDe}\\"\\n  \\"Lớp\\": \\"${lop}\\"\\n  \\"Cấp độ\\": \\"${capDo}\\"\\n\\n2. INSTRUCTION\\nĐộ dài & Nội dung: Tạo chính xác 1 câu hỏi trắc nghiệm với 4 lựa chọn (a, b, c, d).\\n\\nPhù hợp với học sinh: Sử dụng từ vựng và ngữ pháp phù hợp với lứa tuổi ${lop} BÁM SÁT THEO Chủ đề: ${chuDe} và Cấp độ: ${capDo}\\n\\nTính chính xác: Đảm bảo chỉ có một đáp án đúng.\\n\\nTránh mơ hồ: Các câu hỏi và đáp án phải rõ ràng, không gây nhầm lẫn.\\n\\n3. JSON OUTPUT FORMAT\\nTrả về đối tượng JSON theo cấu trúc sau:\\n{\\n   \\"Môn học\\": \\"${mon}\\",\\n  \\"Chủ đề\\": \\"${chuDe}\\",\\n  \\"Lớp\\": \\"${lop}\\",\\n  \\"Cấp độ\\": \\"${capDo}\\",\\n  \\"questions\\": [\\n    {\\n    \\"question\\": \\"[Câu hỏi tiếng Việt]\\",\\n    \\"choices\\": [\\n      \\"a. [Lựa chọn a]\\",\\n      \\"b. [Lựa chọn b]\\",\\n      \\"c. [Lựa chọn c]\\",\\n      \\"d. [Lựa chọn d]\\"\\n    ],\\n    \\"correctAnswer\\": \\"[Đáp án đúng, ví dụ: 'a. ...']\\",\\n    \\"Explanation\\": \\"\\n          question: [Câu hỏi tiếng Việt]\\n          a. [Lựa chọn a]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn a]\\n          b. [Lựa chọn b]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn b]\\n          c. [Lựa chọn c]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn c]\\n         d. [Lựa chọn d]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn d].\\",\\n    \\"imagePrompt\\": \\"Hãy tạo một mô tả hình ảnh bằng tiếng Anh, rõ ràng, sinh động và có tính giáo dục, minh họa cho ý tưởng chính của câu hỏi và đáp án đúng, phù hợp với khả năng hiểu của học sinh.\\n  \\n  Nếu câu hỏi liên quan đến các khái niệm có thể minh họa trực quan (ví dụ: đồ vật, con vật, hành động, bối cảnh), hãy mô tả cảnh minh họa có đầy đủ đối tượng chính, bối cảnh phù hợp và các vật thể phụ trợ có liên quan để hỗ trợ học sinh dễ hiểu và dễ ghi nhớ.\\n  \\n  Nếu câu hỏi là “Mấy giờ rồi?”, hãy mô tả một chiếc đồng hồ rõ ràng hiển thị đúng giờ, đặt trong một bối cảnh sinh hoạt thực tế (ví dụ: lớp học, phòng ngủ buổi sáng, sân chơi giờ ra chơi...).\\n  \\n  Nếu câu hỏi là phép tính số học đơn giản (ví dụ: “3 + 1 bằng mấy?”), không được thể hiện kết quả (ví dụ: số 4). Thay vào đó, hãy minh họa bối cảnh với các đối tượng tương ứng (ví dụ: 3 quả táo + 1 quả táo), kèm theo môi trường xung quanh có màu sắc sinh động và phù hợp với học sinh.\\n  \\n  Nếu câu hỏi mang tính trừu tượng (như ngữ pháp, logic, định nghĩa), hãy trả về chuỗi rỗng \\"\\" và không tạo hình ảnh.\\n  \\n  Phong cách hình ảnh phải phù hợp với học sinh: nhiều màu sắc, thân thiện, dễ tiếp cận. Gợi ý phong cách: \\"2D cartoon illustration\\", \\"watercolor painting\\", \\"flat design\\", hoặc \\"children’s book drawing\\".\\n  \\n  Có thể kết hợp yếu tố văn hóa Việt Nam một cách tự nhiên nếu phù hợp (ví dụ: nhân vật, trang phục, bối cảnh, đồ vật,...).\\n  \\n  ➤ Chỉ trả về chuỗi mô tả ảnh, không cần định dạng đặc biệt hoặc lời giải thích.\\",\\n    \\n    \\"imageName\\": \\"Tạo chuỗi ngắn gọn, viết thường, dùng dấu - thay cho khoảng trắng, mô tả ngắn về đối tượng chính trong hình.\\"\\n    },\\n   {\\n      \\"question\\": \\"[Câu hỏi tiếp theo...]\\",\\n      \\"choices\\": [\\n        \\"a. ...\\",\\n        \\"b. ...\\",\\n        \\"c. ...\\",\\n        \\"d. ...\\"\\n      ],\\n      \\"correctAnswer\\": \\"c. ...\\",\\n      \\"Explanation\\": \\"...\\",\\n      \\"imagePrompt\\": \\"...\\",\\n      \\"imageName\\": \\"...\\"\\n    }\\n  ]\\n}\\n\\n4. IMPORTANT RULES\\nĐịnh dạng JSON: BẮT BUỘC tuân thủ chính xác định dạng JSON trên. Sử dụng dấu ngoặc kép đôi cho tất cả các khóa và giá trị.\\n\\nDuy nhất một đối tượng JSON: Không thêm bất kỳ văn bản nào trước hoặc sau đối tượng JSON.\\n\\nCâu hỏi : tránh lặp lại nhiều lần.\\n\\nGiải thích: Mỗi giải thích cho từng lựa chọn phải ngắn gọn, súc tích trong một câu và sử dụng icon ✅/❌ đặt phía trước.\\n\\nKiểm tra cú pháp: Tự kiểm tra lại cú pháp JSON của bạn để đảm bảo không có lỗi như thiếu dấu phẩy hoặc dấu ngoặc đóng.\\n`;\\nlet prompt_Toan = `Bạn là một chuyên gia giáo dục xuất sắc môn ${mon} và chuyên gia prompt tạo ảnh minh họa. Nhiệm vụ của bạn là tạo ${Xsocauhoi} câu hỏi trắc nghiệm ${mon} chất lượng cao cho học sinh ${lop}. Kết quả đầu ra phải là một đối tượng JSON duy nhất và hoàn hảo, không có bất kỳ văn bản, mã markdown hoặc nội dung nào khác.\\n\\n1. CONTEXT\\n  \\"Môn học\\": \\"${mon}\\"\\n  \\"Chủ đề\\": \\"${chuDe}\\"\\n  \\"Lớp\\": \\"${lop}\\"\\n  \\"Cấp độ\\": \\"${capDo}\\"\\n\\n2. INSTRUCTION\\nĐộ dài & Nội dung: Tạo chính xác 1 câu hỏi trắc nghiệm với 4 lựa chọn (a, b, c, d).\\n\\nPhù hợp với học sinh: Sử dụng từ vựng và ngữ pháp phù hợp với lứa tuổi ${lop} BÁM SÁT THEO Chủ đề: ${chuDe} và Cấp độ: ${capDo}\\n\\nTính chính xác: Đảm bảo chỉ có một đáp án đúng.\\n\\nTránh mơ hồ: Các câu hỏi và đáp án phải rõ ràng, không gây nhầm lẫn.\\n\\n3. JSON OUTPUT FORMAT\\nTrả về đối tượng JSON theo cấu trúc sau:\\n{\\n  \\"Môn học\\": \\"${mon}\\",\\n  \\"Chủ đề\\": \\"${chuDe}\\",\\n  \\"Lớp\\": \\"${lop}\\",\\n  \\"Cấp độ\\": \\"${capDo}\\",\\n  \\"questions\\": [\\n    {\\n    \\"question\\": \\"[Câu hỏi tiếng Việt]\\",\\n    \\"choices\\": [\\n      \\"a. [Lựa chọn a]\\",\\n      \\"b. [Lựa chọn b]\\",\\n      \\"c. [Lựa chọn c]\\",\\n      \\"d. [Lựa chọn d]\\"\\n    ],\\n    \\"correctAnswer\\": \\"[Đáp án đúng, ví dụ: 'a. ...']\\",\\n    \\"Explanation\\": \\"\\n          question: [Câu hỏi tiếng Việt]\\n          a. [Lựa chọn a]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn a]\\n          b. [Lựa chọn b]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn b]\\n          c. [Lựa chọn c]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn c]\\n         d. [Lựa chọn d]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn d].\\",\\n     \\"imagePrompt\\": \\"Hãy tạo một mô tả hình ảnh bằng tiếng Anh, rõ ràng, sinh động và có tính giáo dục, minh họa cho ý tưởng chính của câu hỏi và đáp án đúng, phù hợp với khả năng hiểu của học sinh.\\n  \\n  Nếu câu hỏi liên quan đến các khái niệm có thể minh họa trực quan (ví dụ: đồ vật, con vật, hành động, bối cảnh), hãy mô tả cảnh minh họa có đầy đủ đối tượng chính, bối cảnh phù hợp và các vật thể phụ trợ có liên quan để hỗ trợ học sinh dễ hiểu và dễ ghi nhớ.\\n  \\n  Nếu câu hỏi là “Mấy giờ rồi?”, hãy mô tả một chiếc đồng hồ rõ ràng hiển thị đúng giờ, đặt trong một bối cảnh sinh hoạt thực tế (ví dụ: lớp học, phòng ngủ buổi sáng, sân chơi giờ ra chơi...).\\n  \\n  Nếu câu hỏi là phép tính số học đơn giản (ví dụ: “3 + 1 bằng mấy?”), không được thể hiện kết quả (ví dụ: số 4). Thay vào đó, hãy minh họa bối cảnh với các đối tượng tương ứng (ví dụ: 3 quả táo + 1 quả táo), kèm theo môi trường xung quanh có màu sắc sinh động và phù hợp với học sinh.\\n  \\n  Nếu câu hỏi mang tính trừu tượng (như ngữ pháp, logic, định nghĩa), hãy trả về chuỗi rỗng \\"\\" và không tạo hình ảnh.\\n  \\n  Phong cách hình ảnh phải phù hợp với học sinh: nhiều màu sắc, thân thiện, dễ tiếp cận. Gợi ý phong cách: \\"2D cartoon illustration\\", \\"watercolor painting\\", \\"flat design\\", hoặc \\"children’s book drawing\\".\\n  \\n  Có thể kết hợp yếu tố văn hóa Việt Nam một cách tự nhiên nếu phù hợp (ví dụ: nhân vật, trang phục, bối cảnh, đồ vật,...).\\n  \\n  ➤ Chỉ trả về chuỗi mô tả ảnh, không cần định dạng đặc biệt hoặc lời giải thích.\\",\\n    \\n    \\"imageName\\": \\"Tạo chuỗi ngắn gọn, viết thường, dùng dấu - thay cho khoảng trắng, mô tả ngắn về đối tượng chính trong hình.\\"\\n    },\\n   {\\n      \\"question\\": \\"[Câu hỏi tiếp theo...]\\",\\n      \\"choices\\": [\\n        \\"a. ...\\",\\n        \\"b. ...\\",\\n        \\"c. ...\\",\\n        \\"d. ...\\"\\n      ],\\n      \\"correctAnswer\\": \\"c. ...\\",\\n      \\"Explanation\\": \\"...\\",\\n      \\"imagePrompt\\": \\"...\\",\\n      \\"imageName\\": \\"...\\"\\n    }\\n  ]\\n}\\n\\n4. IMPORTANT RULES\\nĐịnh dạng JSON: BẮT BUỘC tuân thủ chính xác định dạng JSON trên. Sử dụng dấu ngoặc kép đôi cho tất cả các khóa và giá trị.\\n\\nDuy nhất một đối tượng JSON: Không thêm bất kỳ văn bản nào trước hoặc sau đối tượng JSON.\\n\\nCâu hỏi : tránh lặp lại nhiều lần.\\n\\nGiải thích: Mỗi giải thích cho từng lựa chọn phải ngắn gọn, súc tích trong một câu và sử dụng icon ✅/❌ đặt phía trước.\\n\\nKiểm tra cú pháp: Tự kiểm tra lại cú pháp JSON của bạn để đảm bảo không có lỗi như thiếu dấu phẩy hoặc dấu ngoặc đóng.\\n`;\\n\\nif (mon === \\"Tiếng Anh\\") {\\n  return [{ json: { prompt: prompt_TiengAnh } }];\\n} else if (mon === \\"Tiếng Việt\\") {\\n  return [{ json: { prompt: prompt_TiengViet } }];\\n} else if (mon === \\"Toán\\") {\\n  return [{ json: { prompt: prompt_Toan } }]; // Đổi thành đúng biến\\n} else {\\n  return [{ json: { prompt: \\"\\" } }];\\n}"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[448,336],"id":"a7437ed0-431f-4106-82a8-089fb3aadde0","name":"Prompt"},{"parameters":{"options":{}},"type":"@n8n/n8n-nodes-langchain.lmChatGoogleGemini","typeVersion":1,"position":[1024,672],"id":"e096fe18-921d-48c1-bed5-dcf85ed3103a","name":"Gemini 000","credentials":{"googlePalmApi":{"id":"JwqyfcHvgMHktvau","name":"Google ACC tuduykhacbiet.vn"}}},{"parameters":{"options":{}},"type":"@n8n/n8n-nodes-langchain.lmChatGoogleGemini","typeVersion":1,"position":[1280,672],"id":"f15c3681-ddf8-46a4-a1ea-e674fcb50e64","name":"Gemini 002","credentials":{"googlePalmApi":{"id":"JwqyfcHvgMHktvau","name":"Google ACC tuduykhacbiet.vn"}}},{"parameters":{"options":{}},"type":"@n8n/n8n-nodes-langchain.lmChatGoogleGemini","typeVersion":1,"position":[880,672],"id":"75e1b217-db76-4002-a8e0-