b3abaa54-e3fb-45ab-b46d-48cb8cc44307	roGwBDJ7Nrh0IERD	import	2026-07-24 13:10:09.395+00	2026-07-24 13:10:09.395+00	[{"parameters":{},"id":"88de2021-382a-415f-9bf0-08ca1dc2e945","name":"On Error","type":"n8n-nodes-base.errorTrigger","typeVersion":1,"position":[400,256]},{"parameters":{"mode":"runOnceForEachItem","jsCode":"const fs = require('fs'); function countWav(dir){ try{ return fs.readdirSync(dir,{withFileTypes:true}).filter(d=>d.isFile() && d.name.endsWith('.wav')).length; }catch(e){ return 0; } } const speakersRoot = `${$json.jobSpeakers}`; const rvcRoot = `${$json.jobRoot}/rvc`; return { json: { stem: $json.stem, jobRoot: $json.jobRoot, vocals: $json.demucsVocals, rttm: $json.rttmPath, srt: $json.srtPath, speakersWav: countWav(speakersRoot), rvcWav: countWav(rvcRoot), status: 'COMPLETED' } };"},"id":"c5ab3c17-ec76-4dd3-a2c1-3683886dd557","name":"Summary Report","type":"n8n-nodes-base.code","typeVersion":2,"position":[1664,352]},{"parameters":{},"id":"2f0e3068-fd19-40d0-afba-b5f710a9fb8f","name":"Done","type":"n8n-nodes-base.noOp","typeVersion":1,"position":[1504,352]},{"parameters":{"command":"bash -lc '\\\\nset -euo pipefail\\\\nROOT={{ JSON.stringify($json.jobSpeakers) }}\\\\nOUTROOT={{ JSON.stringify($json.jobRoot) }}/rvc\\\\nmkdir -p \\"$OUTROOT\\"\\\\nshopt -s nullglob\\\\nfor wav in \\"$ROOT\\"/SPEAKER_*/speaker_*.wav; do\\\\n  [ -s \\"$wav\\" ] || continue\\\\n  bn=$(basename \\"$wav\\" .wav)\\\\n  spdir=$(basename \\"$(dirname \\"$wav\\")\\")\\\\n  outdir=\\"$OUTROOT/$spdir\\"\\\\n  mkdir -p \\"$outdir\\"\\\\n  out=\\"$outdir/${bn}_rvc.wav\\"\\\\n  {{ $json.pythonExe || \\"python3\\" }} {{ JSON.stringify($json.rvcPy) }} --input \\"$wav\\" --output \\"$out\\" --model {{ JSON.stringify($json.rvcModel) }} --index {{ JSON.stringify($json.rvcIndex) }} --f0method {{ JSON.stringify($json.rvcF0Method) }} --transpose {{ JSON.stringify($json.rvcTranspose) }}\\\\ndone\\\\nprintf \\"RVC_DONE\\"'\\\\n"},"id":"69638132-0477-43f7-b385-a50bd42c8c8a","name":"RVC Convert","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1344,160]},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":1},"conditions":[{"leftValue":"={{ $json.enableRVC }}","rightValue":"","operator":{"type":"boolean","operation":"isTrue"},"id":"enable-rvc-bool"},{"id":"02f047da-ecdc-4344-9044-deed41606e8c","leftValue":"","rightValue":"","operator":{"type":"string","operation":"equals","name":"filter.operator.equals"}}],"combinator":"and"},"options":{}},"id":"35d5dd90-e245-49b3-a516-c92049e3a656","name":"Enable RVC?","type":"n8n-nodes-base.if","typeVersion":2,"position":[1232,336]},{"parameters":{"content":"STEP: workflow n8n ","height":780,"width":2032,"color":4},"id":"e8573cbd-ddac-4a98-83e0-bdc45efdeece","name":"Sticky Note","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[192,624]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\nIN={{ JSON.stringify($json.src) }}\\nOUT={{ JSON.stringify($json.inputWav) }}\\nFF={{ JSON.stringify($json.ffmpegCmd || \\"ffmpeg\\") }}\\n\\n# === Skip nếu file có sẵn và >5KB ===\\n# Kiểm tra file tồn tại và kích thước >5KB thì skip\\nif [ -f \\"$OUT\\" ]; then\\n  size=$(wc -c \\\\< \\"$OUT\\" 2>/dev/null || echo 0)\\n  if [ \\"$size\\" -gt 5120 ]; then\\n    echo \\"[FFMPEG][INFO] Found existing output: $OUT, skip re-extract.\\" >&2\\n    printf \\"%s\\\\n\\" \\"$OUT\\"\\n    exit 0\\n  fi\\nfi\\n\\nMAX_THREADS=32\\nTOTAL=$(nproc --all 2>/dev/null || echo 1)\\n\\n# === Đo CPU usage qua /proc/stat ===\\nif [ -r /proc/stat ]; then\\n  read cpu a b c idle rest < /proc/stat\\n  total1=$((a+b+c+idle)); idle1=$idle\\n  sleep 1\\n  read cpu a b c idle rest < /proc/stat\\n  total2=$((a+b+c+idle)); idle2=$idle\\n  diff_total=$((total2-total1)); diff_idle=$((idle2-idle1))\\n  if [ \\"$diff_total\\" -gt 0 ]; then\\n    USAGE=$(( (100*(diff_total-diff_idle))/diff_total ))\\n  else\\n    USAGE=0\\n  fi\\n  FREE=$(( TOTAL * (100 - USAGE) / 100 ))\\nelse\\n  USAGE=0; FREE=$TOTAL\\nfi\\n\\nif [ \\"$FREE\\" -gt \\"$MAX_THREADS\\" ]; then THREADS=$MAX_THREADS; else THREADS=$FREE; fi\\nif [ \\"$THREADS\\" -le 0 ]; then THREADS=1; fi\\n\\n# Tạo thư mục output nếu chưa có\\nmkdir -p \\"$(dirname \\"$OUT\\")\\"\\n\\necho \\"[FFMPEG][INFO] Total=$TOTAL, load=${USAGE}%, free=$FREE → THREADS=$THREADS\\" >&2\\n\\n# Chuyển đổi audio\\nif \\"$FF\\" -hide_banner -loglevel error -nostdin -y \\\\\\n   -i \\"$IN\\" -vn -ar 16000 -ac 1 -threads \\"$THREADS\\" \\"$OUT\\"; then\\n  echo \\"[FFMPEG][SUCCESS] Converted: $OUT\\" >&2\\nelse\\n  echo \\"[FFMPEG][WARN] Retry without thread limit\\" >&2\\n  if \\"$FF\\" -hide_banner -loglevel error -nostdin -y \\\\\\n      -i \\"$IN\\" -vn -ar 16000 -ac 1 \\"$OUT\\"; then\\n    echo \\"[FFMPEG][SUCCESS] Converted (retry): $OUT\\" >&2\\n  else\\n    echo \\"[FFMPEG][ERROR] Failed to convert: $IN\\" >&2\\n    exit 1\\n  fi\\nfi\\n\\necho \\"$OUT\\"\\nprintf \\"%s\\\\n\\" \\"$VOC\\"\\n'"},"id":"97ed61c0-6f29-4e8d-a9ae-1b50437acc08","name":"Extract 16k Mono WAV - Optimized","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1296,656]},{"parameters":{"command":"=bash -lc 'find {{ JSON.stringify($(\\"Set Config\\").item.json.inDir) }} -maxdepth 1 -type f \\\\( -iname \\"*.mp4\\" -o -iname \\"*.mkv\\" -o -iname \\"*.mov\\" -o -iname \\"*.wav\\" -o -iname \\"*.mp3\\" -o -iname \\"*.m4a\\" \\\\) -printf \\"%f||%p\\\\n\\"'"},"id":"212d9b2c-3ce7-40cb-af05-3cd88a827561","name":"List Input Files","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[832,784]},{"parameters":{"keepOnlySet":true,"values":{"string":[{"name":"inDir","value":"/files/voice/input"},{"name":"outDir","value":"/files/voice/output"},{"name":"demucsCmd","value":"demucs"},{"name":"ffmpegCmd","value":"ffmpeg"},{"name":"pythonExe","value":"python3"},{"name":"diarPy","value":"/scripts/diarize.py"},{"name":"separateSpeakersPy","value":"/scripts/separate_speakers.py"},{"name":"rvcPy","value":"/scripts/batch_rvc.py"},{"name":"mergePy","value":"/scripts/merge.py"},{"name":"rvcModel","value":"/rvc-models/jackie.pth"},{"name":"rvcIndex","value":"/rvc-models/jackie.index"},{"name":"rvcF0Method","value":"harvest"},{"name":"rvcTranspose","value":"0"},{"name":"whisperUrl","value":"http://whisper:9000/asr?task=transcribe&language=vi"}],"boolean":[{"name":"enableRVC","value":true}]},"options":{}},"id":"ad777e7a-93d1-406a-bb13-86207af7000e","name":"Set Config","type":"n8n-nodes-base.set","typeVersion":2,"position":[608,784]},{"parameters":{},"id":"36adeff5-8cbe-467b-bb54-8a83b60fb430","name":"Start","type":"n8n-nodes-base.manualTrigger","typeVersion":1,"position":[256,784],"disabled":true},{"parameters":{"jsCode":"// Build per-file job workspace name: name, name1, name2...\\nconst lines = String($json.stdout || '').split(/\\\\r?\\\\n/).map(s=>s.trim()).filter(Boolean);\\nif (!lines.length) return [];\\n\\nconst cfg = $('Set Config').first().json;\\n\\nreturn lines.map(row=>{\\n  const [base, full] = row.split('||');\\n  const stemRaw = (base || '').replace(/\\\\.[^.]+$/, '');\\n  \\n  // Cải tiến: Sử dụng regex mạnh hơn để loại bỏ tất cả các ký tự không an toàn\\n  // và giới hạn độ dài tối đa 100 ký tự để tránh lỗi string quá dài\\n  let stem = stemRaw.replace(/[^a-zA-Z0-9-]/g, '_')\\n                   .replace(/_{2,}/g, '_')\\n                   .replace(/^_+|_+$/g, '');\\n  \\n  // Giới hạn độ dài tối đa 100 ký tự\\n  if (stem.length > 20) {\\n    stem = stem.substring(0, 20);\\n  }\\n\\n  const jobRoot = `${cfg.outDir}/${stem}`;\\n  const inputWav = `${jobRoot}/htdemucs_6s/input_16k_mono.wav`;\\n  const demucsVocals = `${jobRoot}/htdemucs_6s/input_16k_mono/vocals.wav`;\\n  const rttmPath = `${jobRoot}/htdemucs_6s/input_16k_mono/vocals.rttm`;\\n  const jobWhisper = `${jobRoot}/whisper`;\\n  const jobSpeakers = `${jobRoot}/speakers`;\\n  const srtPath = `${jobWhisper}/${stem}.srt`;\\n\\n  return { json: {\\n    src: full,\\n    base,\\n    stem,\\n    jobRoot,\\n    jobWhisper,\\n    jobSpeakers,\\n    inputWav,\\n    demucsVocals,\\n    rttmPath,\\n    srtPath,\\n    inDir: cfg.inDir,\\n    outDir: cfg.outDir,\\n    demucsCmd: cfg.demucsCmd,\\n    ffmpegCmd: cfg.ffmpegCmd,\\n    pythonExe: cfg.pythonExe,\\n    diarPy: cfg.diarPy,\\n    separateSpeakersPy: cfg.separateSpeakersPy,\\n    rvcPy: cfg.rvcPy,\\n    mergePy: cfg.mergePy,\\n    rvcModel: cfg.rvcModel,\\n    rvcIndex: cfg.rvcIndex,\\n    rvcF0Method: cfg.rvcF0Method,\\n    rvcTranspose: cfg.rvcTranspose,\\n    whisperUrl: cfg.whisperUrl,\\n    enableRVC: cfg.enableRVC === undefined ? true : !!cfg.enableRVC\\n  }};\\n});"},"id":"967e068b-f4a1-4dd7-a514-686b54fe0046","name":"Prepare Job","type":"n8n-nodes-base.code","typeVersion":2,"position":[1056,784]},{"parameters":{"chatId":"5584954476","text":"=Công việc tách speaker đã hoàn tất !","additionalFields":{},"path":"bb9f3f8b-0e3e-44c0-a93c-9071d472406a"},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[1680,992],"id":"3503af73-1d41-4148-9c5c-66d44437656a","name":"Send a text message1","webhookId":"bb9f3f8b-0e3e-44c0-a93c-9071d472406a","credentials":{"telegramApi":{"id":"3dY6VmwOtXaErnPU","name":"Telegram account"}}},{"parameters":{"options":{}},"id":"f98804c4-99e1-4d89-b22b-2d7828fe0a5f","name":"Loop Segments","type":"n8n-nodes-base.splitInBatches","typeVersion":3,"position":[800,1152]},{"parameters":{"mode":"runOnceForEachItem","jsCode":"function fmt(t) {\\n  const h = String(Math.floor(t / 3600)).padStart(2, '0');\\n  const m = String(Math.floor((t % 3600) / 60)).padStart(2, '0');\\n  const s = String(Math.floor(t % 60)).padStart(2, '0');\\n  return `${h}:${m}:${s},000`;\\n}\\n\\n// === Lấy transcript ===\\nconst text = $json.text \\n          || $json.transcription \\n          || $json.data?.text \\n          || $json.data \\n          || '';\\n\\nif (!text.trim()) {\\n  return { json: { skip: true } };\\n}\\n\\n// === Metadata gốc từ Loop Segments ===\\nconst seg = $('Loop Segments').item.json;\\nconst st = parseFloat(seg.start);\\nconst dur = parseFloat(seg.duration);\\n\\nif (isNaN(st) || isNaN(dur) || dur <= 0) {\\n  return { json: { skip: true } };\\n}\\n\\nconst et = st + dur;\\nconst idx = seg.index || 1;   // lấy index từ Build Segments\\n\\n// === Hàm chuẩn hóa slug ===\\nfunction slugify(str) {\\n  if (typeof str !== 'string') return ''; // Xử lý đầu vào không phải string\\n\\n  return str\\n    .normalize('NFD') // Tách ký tự thành base và dấu\\n    .replace(/[\\\\u0300-\\\\u036f]/g, '') // Loại bỏ dấu\\n    .replace(/[đĐ]/g, (match) => match === 'đ' ? 'd' : 'D') // Xử lý đ/Đ\\n    .replace(/['’`]/g, '') // Loại bỏ dấu apostrophe\\n    .replace(/[^\\\\p{L}\\\\p{N} ]/gu, ' ') // Giữ lại chỉ chữ cái, số và khoảng trắng (Unicode property escapes)\\n    .trim()\\n    .replace(/\\\\s+/g, ' ') // Gom nhiều khoảng trắng\\n    .split(' ')\\n    .filter(word => word.length > 0) // Lọc từ rỗng\\n    .slice(0, 20)\\n    .join('_');\\n}\\n\\nconst snippet = slugify(text) || \\"segment\\";\\n\\n// === Tạo tên file mới ===\\nconst dir = seg.segFile.replace(/\\\\/[\\\\w.-]+$/, '');\\nconst base = `Start_${st.toFixed(3)}s-End_${et.toFixed(3)}s-${snippet}_${idx}`;\\n\\nconst newWav = `${dir}/${base}.wav`;\\nconst newTxt = `${dir}/${base}.txt`;\\nconst segFile = $('Read Segment').item.json.stdout;\\nconst txtContent = text.replace(/\\\\r?\\\\n/g, \\" \\");\\n\\n// === Entry SRT ===\\nconst srt = `${idx}\\n${fmt(st)} --> ${fmt(et)}\\n${text}\\n\\n`;\\n\\n// === Output JSON đầy đủ ===\\nreturn {\\n  json: {\\n    ...seg,            // giữ metadata gốc\\n    index: idx,        // luôn có index\\n    start: st,\\n    duration: dur,\\n    segFile: segFile,\\n\\n    srtEntry: srt,\\n    wavFile: newWav,\\n    txtFile: newTxt,\\n    transcript: text,\\n    txtContent\\n  }\\n};\\n"},"id":"88ccfea5-fb93-45de-a644-c47f70bd24a4","name":"Build SRT Entry","type":"n8n-nodes-base.code","typeVersion":2,"position":[1696,1152]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\nOUT_DIR=\\"{{ $(\\"Prepare Job\\").item.json.jobWhisper }}\\"\\nOUT_FILE=\\"$OUT_DIR/{{ $(\\"Prepare Job\\").item.json.stem }}.srt\\"\\nmkdir -p \\"$OUT_DIR\\"\\n\\nNEW_WAV=\\"{{ $json.wavFile }}\\"\\nNEW_TXT=\\"{{ $json.txtFile }}\\"\\nOLD_WAV=\\"{{ $json.segFile }}\\"\\n# ✅ thay vì gán trực tiếp, dùng cat <<'EOF'\\nSRT_ENTRY=$(cat <<'EOF'\\n{{ $json.srtEntry || \\"\\" }}\\nEOF\\n)\\n\\nTXT_CONTENT=$(cat <<'EOF'\\n{{ $json.txtContent || \\"\\" }}\\nEOF\\n)\\n\\nSTART={{ $json.start }}\\nDUR={{ $json.duration }}\\nEND=$(awk \\"BEGIN{print $START+$DUR}\\")\\nSPEAKER=\\"{{ $json.speaker || \\"unknown\\" }}\\"\\n\\n# 📝 Debug\\necho \\"[DEBUG] TXT_CONTENT = $TXT_CONTENT\\" >&2\\necho \\"[DEBUG] Ghi đè file TXT: $NEW_TXT\\" >&2\\n\\n# 📝 ghi file TXT\\nprintf \\"Start: %s\\\\nEnd: %s\\\\nDuration: %s\\\\nSpeaker: %s\\\\n\\\\nTranscript:\\\\n%s\\\\n\\" \\\\\\n  \\"$START\\" \\"$END\\" \\"$DUR\\" \\"$SPEAKER\\" \\"$TXT_CONTENT\\" > \\"$NEW_TXT\\"\\n\\n# 🔄 Rename WAV\\nif [ -n \\"$NEW_WAV\\" ] && [ -f \\"$OLD_WAV\\" ]; then\\n  echo \\"[DEBUG] Rename WAV: $OLD_WAV -> $NEW_WAV\\" >&2\\n  mv -f \\"$OLD_WAV\\" \\"$NEW_WAV\\"\\nelse\\n  echo \\"[DEBUG] WAV rename skipped: OLD_WAV=$OLD_WAV, NEW_WAV=$NEW_WAV\\" >&2\\nfi\\n\\n# 🔄 Append SRT (luôn thêm dòng trắng sau entry)\\nif [ -n \\"$SRT_ENTRY\\" ] && [ -n \\"$OUT_FILE\\" ]; then\\n  printf \\"%s\\\\n\\\\n\\" \\"$SRT_ENTRY\\" >> \\"$OUT_FILE\\"\\n  echo \\"[DEBUG] Append SRT entry -> $OUT_FILE\\" >&2\\nfi\\n\\necho \\"$OUT_FILE\\"\\n'\\n"},"id":"eec4732e-f3ae-46cb-8e8f-b608bbc7e9ee","name":"Append to SRT","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1856,1152],"alwaysOutputData":true},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\n# 🚫 Vô hiệu hóa kết nối mạng HuggingFace\\nexport HF_HUB_OFFLINE=1\\nexport TRANSFORMERS_OFFLINE=1\\nexport PYANNOTE_DONT_USE_HF_TRANSFORMERS_CACHE=1\\n\\nPY={{ $(\\"Prepare Job\\").item.json.pythonExe || \\"python3\\" }}\\nSCR={{ $(\\"Prepare Job\\").item.json.separateSpeakersPy }}\\nRTTM={{ $(\\"Prepare Job\\").item.json.rttmPath }}\\nSRT={{ $(\\"Prepare Job\\").item.json.srtPath}}\\nAUDIO={{ $(\\"Prepare Job\\").item.json.demucsVocals }}\\nOUT={{ $(\\"Prepare Job\\").item.json.jobSpeakers }}\\n\\n# 🔄 SRT fallback\\nif [ -z \\"$SRT\\" ] || [ ! -s \\"$SRT\\" ]; then\\n  JOBROOT=\\"${AUDIO%/htdemucs/*}\\"\\n  STEM=\\"$(basename \\"$JOBROOT\\")\\"\\n  CAND1=\\"$JOBROOT/whisper/$STEM.srt\\"\\n  if [ -s \\"$CAND1\\" ]; then\\n    SRT=\\"$CAND1\\"\\n  else\\n    CAND2=\\"$(find \\"$JOBROOT/whisper\\" -type f -name \\"*.srt\\" -print -quit 2>/dev/null || true)\\"\\n    [ -n \\"$CAND2\\" ] && [ -s \\"$CAND2\\" ] && SRT=\\"$CAND2\\"\\n  fi\\nfi\\n\\n# 🔄 RTTM fallback\\nif [ -z \\"$RTTM\\" ] || [ ! -s \\"$RTTM\\" ]; then\\n  RTDIR=\\"$(dirname \\"$AUDIO\\")\\"\\n  RTALT=\\"$RTDIR/vocals.rttm\\"\\n  [ -s \\"$RTALT\\" ] && RTTM=\\"$RTALT\\"\\nfi\\n\\n# ✅ Kiểm tra input\\n[ -f \\"$SCR\\" ]  || { echo \\"[SEP][ERR] separate_speakers.py missing: $SCR\\" >&2; exit 1; }\\n[ -s \\"$RTTM\\" ] || { echo \\"[SEP][ERR] RTTM missing: $RTTM\\" >&2; exit 1; }\\n[ -s \\"$SRT\\" ]  || { echo \\"[SEP][ERR] SRT missing: $SRT\\" >&2; exit 1; }\\n[ -s \\"$AUDIO\\" ]|| { echo \\"[SEP][ERR] audio missing: $AUDIO\\" >&2; exit 1; }\\n\\nmkdir -p \\"$OUT\\"\\n\\n# === Giới hạn threads tối đa từ Prepare Job ===\\nMAX_THREADS=32\\n\\n# === Lấy tổng core thực tế ===\\nTOTAL=$(nproc --all)\\n\\n# === Đo CPU usage trong 1 giây ===\\nread cpu a b c idle rest < /proc/stat\\ntotal1=$((a+b+c+idle))\\nidle1=$idle\\nsleep 1\\nread cpu a b c idle rest < /proc/stat\\ntotal2=$((a+b+c+idle))\\nidle2=$idle\\ndiff_total=$((total2-total1))\\ndiff_idle=$((idle2-idle1))\\nUSAGE=$(( (100*(diff_total-diff_idle))/diff_total ))\\n\\n# === Tính số core rảnh ===\\nFREE=$(( TOTAL * (100 - USAGE) / 100 ))\\n\\n# === Chọn threads: free nhưng không vượt MAX_THREADS ===\\nif [ \\"$FREE\\" -gt \\"$MAX_THREADS\\" ]; then\\n  THREADS=$MAX_THREADS\\nelse\\n  THREADS=$FREE\\nfi\\nTHREADS=$(( THREADS > 0 ? THREADS : 1 ))\\n\\nexport OMP_NUM_THREADS=$THREADS\\nexport MKL_NUM_THREADS=$THREADS\\nexport OPENBLAS_NUM_THREADS=$THREADS\\nexport NUMEXPR_NUM_THREADS=$THREADS\\n\\necho \\"[SEP][INFO] Total cores=$TOTAL, load=${USAGE}%, free=$FREE, limit=$MAX_THREADS → dùng THREADS=$THREADS\\" >&2\\n\\n# 🚀 Chạy\\ntimeout 600 \\"$PY\\" \\"$SCR\\" --rttm \\"$RTTM\\" --srt \\"$SRT\\" --input_audio \\"$AUDIO\\" --output_dir \\"$OUT\\"\\n\\nprintf \\"%s\\" \\"$OUT\\"\\n'"},"id":"ac470239-2378-4cd3-80bc-b9a55477b355","name":"Separate Speakers - Optimized1","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[1328,992]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\nRTTM={{ $(\\"Prepare Job\\").item.json.rttmPath }}\\n\\nawk '\\\\''$1==\\"SPEAKER\\" {print $4 \\"||\\" $5 \\"||\\" $8}'\\\\'' \\"$RTTM\\"\\n'\\n"},"id":"93e0223f-0158-4c0d-88bb-cd127fcf5f29","name":"Parse RTTM","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[288,1152]},{"parameters":{"jsCode":"const pj = $('Prepare Job').item.json;\\nconst lines = String($json.stdout || '').split(/\\\\n/).filter(Boolean);\\n\\nreturn lines.map((l,i)=>{\\n  const [start,dur,spk] = l.split('||');\\n  const s = parseFloat(start);\\n  const d = parseFloat(dur);\\n  const e = s + d;\\n\\n  const segName = `Start_${s.toFixed(2)}s-End_${e.toFixed(2)}s-segment_${i}`;\\n\\n  return { \\n    json: { \\n      index: i + 1,   // ✅ gán số thứ tự ở đây\\n      start: s, \\n      duration: d, \\n      speaker: spk, \\n      segFile: `${pj.jobRoot}/segments/${segName}.wav`, \\n      txtFile: `${pj.jobRoot}/segments/${segName}.txt`\\n    }\\n  };\\n});\\n"},"id":"278c51fd-bfbf-42ca-9bd4-afec258ab072","name":"Build Segments","type":"n8n-nodes-base.code","typeVersion":2,"position":[448,1152]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\nVOC={{ JSON.stringify($(\\"Prepare Job\\").item.json.demucsVocals) }}\\nSRT={{$('Prepare Job').item.json.srtPath}}\\n\\n[ -n \\"$VOC\\" ] && [ -s \\"$VOC\\" ] || { echo \\"[CHECK][ERR] Missing vocals.wav: $VOC\\" >&2; exit 1; }\\n[ -n \\"$SRT\\" ] && [ -s \\"$SRT\\" ] || { echo \\"[CHECK][ERR] Missing SRT: $SRT\\" >&2; exit 1; }\\n\\nRTTM_DIR=\\"$(dirname \\"$VOC\\")\\"\\nRTTM=\\"$RTTM_DIR/vocals.rttm\\"\\n[ -s \\"$RTTM\\" ] || { echo \\"[CHECK][ERR] Missing vocals.rttm: $RTTM\\" >&2; exit 1; }\\n\\nprintf \\"OK\\\\n\\"\\n'\\n"},"id":"f8701578-4276-4a87-9b18-5713a8daf438","name":"Check Inputs","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[992,992]},{"parameters":{"filePath":"={{ $json.stdout }}","dataPropertyName":"audioData"},"id":"9aec102e-a326-420c-85d2-cdd8ac25cfec","name":"Read Segment","type":"n8n-nodes-base.readBinaryFile","typeVersion":1,"position":[1152,1168]},{"parameters":{"command":"=bash -lc '\\nset -euo pipefail\\n\\nIN={{ $(\\"Prepare Job\\").item.json.demucsVocals }}\\nSTART={{ $json.start }}\\nDUR={{ $json.duration }}\\nSPEAKER={{ $json.speaker || \\"unknown\\" }}\\n\\n# 🔢 Tính END\\nEND=$(awk \\"BEGIN{print $START+$DUR}\\")\\n\\nOUT_DIR=\\"$(dirname {{ $json.segFile }})\\"\\nmkdir -p \\"$OUT_DIR\\"\\n\\nBASE=\\"Start_${START}s-End_${END}s-segment\\"\\nWAV_OUT=\\"$OUT_DIR/${BASE}.wav\\"\\nTXT_OUT=\\"$OUT_DIR/${BASE}.txt\\"\\n\\n# 🎵 Cắt audio\\nffmpeg -hide_banner -loglevel error -y -i \\"$IN\\" -ss \\"$START\\" -t \\"$DUR\\" -ar 16000 -ac 1 \\"$WAV_OUT\\"\\n\\n# 📝 Metadata TXT (placeholder Transcript)\\n#{\\n # echo \\"Start: $START\\"\\n  #echo \\"End: $END\\"\\n  #echo \\"Duration: $DUR\\"\\n  #echo \\"Speaker: $SPEAKER\\"\\n  #echo \\"\\"\\n  #echo \\"Transcript:\\"\\n#} > \\"$TXT_OUT\\"\\n\\n# 👉 Xuất đường dẫn WAV cho Whisper\\necho \\"$WAV_OUT\\"\\n'\\n"},"id":"e1b918c3-aaaf-457c-8d24-e7806ceba36a","name":"Cut Segment","type":"n8n-nodes-base.executeCommand","typeVersion":1,"position":[976,1168]},{"parameters":{"method":"POST","url":"={{ $('Prepare Job').item.json.whisperUrl }}","sendBody":true,"contentType":"multipart-form-data","bodyParameters":{"parameters":[{"parameterType":