'].json.next_button : \\"\\";\\nvar more_pages = next_page.length > 0;\\nconst staticData = getWorkflowStaticData('global');\\n\\n//all current items are after date: needs pagination\\nif (more_pages) {\\n  staticData.page = next_page;\\n} else {\\n  //don't check more items in previous pages;\\n  delete staticData.page;\\n}\\n\\nreturn [\\n  {\\n    json: {\\n      more_pages: more_pages\\n    }\\n  }\\n];\\n"},"name":"Set More Pages","type":"n8n-nodes-base.function","position":[3632,6768],"typeVersion":1,"id":"2ae2eb4c-7dd8-4225-9980-0cdda352c11e"},{"parameters":{"values":{"string":[{"name":"url","value":"=https://www.theswiftcodes.com{{$node[\\"Set Page to Scrape\\"].json[\\"page\\"]}}"}]},"options":{}},"name":"Set","type":"n8n-nodes-base.set","position":[1600,6848],"typeVersion":1,"id":"135cbc02-a42c-4c7a-958e-379d891fce73"},{"parameters":{"functionCode":"var generateNameFromUrl = function(url){\\n    return url.replace(/[^a-z0-9]/gi, \\"_\\");\\n}\\n\\nitem.file = generateNameFromUrl(item.url) + \\".html\\"\\nreturn item;"},"name":"Generate filename","type":"n8n-nodes-base.functionItem","position":[1760,6784],"typeVersion":1,"id":"02df5bf8-2436-43a0-add0-00259167c897"},{"parameters":{"filePath":"=/home/node/.cache/scrapper/{{$json[\\"file\\"]}}"},"name":"Read Binary File","type":"n8n-nodes-base.readBinaryFile","position":[1936,6784],"typeVersion":1,"alwaysOutputData":true,"id":"0f06be41-1730-431c-bf32-b614e8065668","continueOnFail":true},{"parameters":{"conditions":{"string":[{"value1":"={{$node[\\"Read Binary File\\"].binary.data.mimeType}}","value2":"text/html"}]}},"name":"File exists?","type":"n8n-nodes-base.if","position":[2112,6784],"typeVersion":1,"id":"2c46f2b7-e5e9-44cc-a442-b1b73cb3fcf7"},{"parameters":{"fileName":"=/home/node/.cache/scrapper/{{$node[\\"Generate filename\\"].json[\\"file\\"]}}","dataPropertyName":"=data","options":{}},"name":"Write Binary File","type":"n8n-nodes-base.writeBinaryFile","position":[2560,6912],"typeVersion":1,"id":"35668d4