   q &&\\n    q.question &&\\n    Array.isArray(q.choices) &&\\n    q.correctAnswer &&\\n    q.Explanation\\n  ) {\\n    questions.push({\\n      question: q.question,\\n      choices: q.choices,\\n      correctAnswer: q.correctAnswer,\\n      Explanation: q.Explanation,\\n      imagePrompt: q.imagePrompt || \\"\\",\\n      imageName: q.imageName || \\"\\",\\n      imageUrl: imageUrl\\n    });\\n  }\\n}\\n\\n// Chỉ lấy thông tin chung từ item đầu tiên (nếu cần)\\nconst first = items[0]?.json || {};\\n\\nreturn [\\n  {\\n    json: {\\n      \\"Môn học\\": first[\\"Môn học\\"] || \\"\\",\\n      \\"Chủ đề\\": first[\\"Chủ đề\\"] || \\"\\",\\n      \\"Lớp\\": first[\\"Lớp\\"] || \\"\\",\\n      \\"Cấp độ\\": first[\\"Cấp độ\\"] || \\"\\",\\n      questions\\n    }\\n  }\\n];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[2096,544],"id":"0ecb72b2-3c0c-46a9-a8c1-b50cd9ca93e8","name":"Parse JSON1"},{"parameters":{"jsCode":"const repeat = parseInt($input.first().json['Sốcâu hỏi cần tạo'] || 1);\\nconst input = $json;\\nconst output = [];\\n\\nfor (let i = 0; i < repeat; i++) {\\n  output.push({\\n    json: {\\n      ...input,\\n      repeatIndex: i + 1,\\n    }\\n  });\\n}\\n\\nreturn output;\\n"},"id":"d0c10d34-8b4d-4780-9ec0-8216f8d3980c","name":"Tạo bản sao bài Quiz","type":"n8n-nodes-base.code","typeVersion":2,"position":[832,256]},{"parameters":{"formTitle":"Tạo bài trắc nghiệm !","formFields":{"values":[{"fieldLabel":"Môn học","fieldType":"dropdown","fieldOptions":{"values":[{"option":"Tiếng Anh"},{"option":"Toán"},{"option":"Tiếng Việt"}]},"requiredField":true},{"fieldLabel":"Chủ đề"},{"fieldLabel":"Lớp","fieldType":"dropdown","fieldOptions":{"values":[{"option":"Lớp 1"},{"option":"Lớp 2"},{"option":"Lớp 3"},{"option":"Lớp 4"},{"option":"Lớp 5"},{"option":"Lớp 6"},{"option":"Lớp 7"},{"option":"Lớp 8"},{"option":"Lớp 9"},{"option":"Lớp 10"},{"option":"Lớp 11"},{"option":"Lớp 12"}]},"requiredField":true},{"fieldLabel":"Cấp độ","fieldType":"dropdown","fieldOptions":{"values":[{"option":"bình thường"},{"option":"khó"},{"option":"rất khó"}]},"requiredField":true},{"fieldLabel":"Sốcâu hỏi cần tạo","fieldType":"number","placeholder":"1","requiredField":true}]},"options":{}},"type":"n8n-nodes-base.formTrigger","typeVersion":2.2,"position":[224,240],"id":"485a7663-63b9-4a28-8bd1-beaf10b9f804","name":"On form submission","webhookId":"353ea294-47b8-454d-9faf-a8572f270691"},{"parameters":{"mode":"combine","combineBy":"combineAll","options":{}},"type":"n8n-nodes-base.merge","typeVersion":3.2,"position":[656,256],"id":"24568d2e-9c61-4ea2-b6fc-78831470b015","name":"Merge","alwaysOutputData":true},{"parameters":{"method":"POST","url":"https://script.google.com/macros/s/AKfycbyN-XqLokk0ayfqdLGd4UotiMmJXBhwzsSSlxpAA9iGOKdq5bBYwM06N_fo5BZUhZio/exec","authentication":"predefinedCredentialType","nodeCredentialType":"googleDriveOAuth2Api","sendBody":true,"bodyParameters":{"parameters":[{"name":"formUrl","value":"={{ $json.formUrl }}"},{"name":"=Môn học","value":"={{ $('Parse JSON2').item.json[\\"Môn học\\"] }}"},{"name":"Chủ đề","value":"={{ $('Parse JSON2').item.json[\\"Chủ đề\\"] }}"},{"name":"Lớp","value":"={{ $('Parse JSON2').item.json[\\"Lớp\\"] }}"},{"name":"Cấp độ","value":"={{ $('Parse JSON2').item.json[\\"Cấp độ\\"] }}"},{"name":"Số lượng câu hỏi","value":"={{ $('Parse JSON2').item.json[\\"Số lượng câu hỏi\\"] }}"},{"name":"Đề thi số","value":"={{ $('Parse JSON2').item.json[\\"Đề thi số\\"] }}"},{"name":"responseUrl","value":"={{ $json.responseUrl }}"}]},"options":{}},"id":"96d95915-e01a-4d85-86e3-c6950beb198e","name":"Tao LinkQuiz","type":"n8n-nodes-base.httpRequest","position":[1552,1040],"typeVersion":4.2,"retryOnFail":true,"waitBetweenTries":5000,"credentials":{"googleDriveOAuth2Api":{"id":"rTUSZlOSjhGVDCDG","name":"Google Drive account LETRUNG80.HUE"}}},{"parameters":{"method":"POST","url":"https://script.google.com/macros/s/AKfycbz3_06T8uXuSBmIb_WkJRkSdweTFHuHCL470EcCimDOMzyTuuNx1BTjGlChy2l9xJGj/exec","authentication":"predefinedCredentialType","nodeCredentialType":"googleDriveOAuth2Api","sendQuery":true,"queryParameters":{"parameters":[{"name":"Môn học","value":"={{ $json[\\"Môn học\\"] }}"}]},"sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={{ $json}}","options":{}},"id":"7f13c19f-a2cd-4cb2-88a0-1da422d1e697","name":"Tao Google Form","type":"n8n-nodes-base.httpRequest","position":[1408,1040],"typeVersion":4.2,"retryOnFail":true,"waitBetweenTries":5000,"credentials":{"googleDriveOAuth2Api":{"id":"WxxAcetQyelhNKX1","name":"Google Drive ACC ngdletrung"}}},{"parameters":{"documentId":{"__rl":true,"value":"1VJzNqZ3CGmxYNaTRCy5P1L2oda0Pawu7mzw57lBwqZk","mode":"id"},"sheetName":{"__rl":true,"value":"={{ $json[\\"Lớp\\"] }}","mode":"name"},"filtersUI":{"values":[{"lookupColumn":"=Môn học","lookupValue":"={{ $json[\\"Môn học\\"] }}"}]},"options":{}},"type":"n8n-nodes-base.googleSheets","typeVersion":4.6,"position":[448,928],"id":"13a231b3-9b6f-444b-8d93-dc2fb53f810f","name":"ReadFile","retryOnFail":true,"waitBetweenTries":5000},{"parameters":{"jsCode":"// 1. Lấy toàn bộ câu hỏi từ Google Sheet\\nconst allQuestions = items.map(item => item.json);\\n\\n// 2. Lấy thông tin từ form submission\\nconst inputData = $('On form submission1').first().json;\\nconst targetLevel = inputData[\\"Cấp độ\\"] || null;\\nconst soLuongCauHoi = parseInt((inputData[\\"Số lượng câu hỏi\\"] || \\"0\\").replace(\\" câu\\", \\"\\")) || 10;\\nconst soDe = parseInt(inputData[\\"Số bài  Quiz cần tạo\\"] || \\"1\\");\\nconst chuDe = inputData[\\"Chủ đề\\"] || \\"\\";\\nconst monHoc = inputData[\\"Môn học\\"] || \\"\\";\\nconst lop = inputData[\\"Lớp\\"] || \\"\\";\\n\\n// ✅ Cấu hình: Cho phép trùng giữa các đề, nhưng không trùng trong 1 đề\\nconst chophep_cacdetrunglap = true;\\n\\n// 3. Lọc theo cấp độ nếu có, trừ khi là \\"cấp độ ngẫu nhiên\\"\\nlet filtered = allQuestions;\\nif (targetLevel && targetLevel.trim().toLowerCase() !== \\"cấp độ ngẫu nhiên\\") {\\n  filtered = filtered.filter(q => q[\\"Cấp độ\\"] === targetLevel);\\n}\\n\\n// ✅ Sắp xếp theo row_number để ổn định\\nfiltered = filtered.sort((a, b) => parseInt(a.row_number) - parseInt(b.row_number));\\n\\n// ✅ Nếu không cho phép trùng giữa các đề, cần kiểm tra số lượng đủ\\nif (!chophep_cacdetrunglap && filtered.length < soLuongCauHoi * soDe) {\\n  throw new Error(`Không đủ câu hỏi để tạo ${soDe} đề, mỗi đề ${soLuongCauHoi} câu (Cần ${soDe * soLuongCauHoi}, có ${filtered.length})`);\\n}\\n\\n// 4. Lấy STT đề thi từ node trước\\nconst sttStart = parseInt($('Lấy STT Đề Thi').first().json[\\"Đề thi số\\"] || '0') + 1;\\n\\n// 5. Bắt đầu tạo đề\\nconst output = [];\\nconst usedRowNumbersGlobal = new Set(); // chỉ dùng nếu không cho phép trùng giữa các đề\\n\\nfor (let i = 0; i < soDe; i++) {\\n  const deThiSo = sttStart + i;\\n  const usedRowNumbersLocal = new Set(); // đảm bảo không trùng trong 1 đề\\n  let selected = [];\\n\\n  if (chophep_cacdetrunglap) {\\n    // ✅ Cho phép trùng giữa các đề, nhưng không trùng trong 1 đề\\n    const shuffled = [...filtered].sort(() => Math.random() - 0.5);\\n\\n    for (const item of shuffled) {\\n      const rowNum = item.row_number;\\n      if (!usedRowNumbersLocal.has(rowNum)) {\\n        selected.push(item);\\n        usedRowNumbersLocal.add(rowNum);\\n        if (selected.length === soLuongCauHoi) break;\\n      }\\n    }\\n\\n    if (selected.length < soLuongCauHoi) {\\n      throw new Error(`❌ Đề số ${deThiSo} chỉ lấy được ${selected.length}/${soLuongCauHoi} câu không trùng. Kiểm tra lại dữ liệu.`);\\n    }\\n\\n  } else {\\n    // ❌ Không cho phép trùng giữa các đề\\n    for (const item of filtered) {\\n      const rowNum = item.row_number;\\n      if (!usedRowNumbersGlobal.has(rowNum)) {\\n        selected.push(item);\\n        usedRowNumbersGlobal.add(rowNum);\\n        if (selected.length === soLuongCauHoi) break;\\n      }\\n    }\\n\\n    if (selected.length < soLuongCauHoi) {\\n      throw new Error(`❌ Không đủ câu hỏi không trùng để tạo đề số ${deThiSo}`);\\n    }\\n  }\\n\\n  // Parse câu hỏi từ JSON gốc\\n  const questions = selected.map(q => {\\n    let parsed;\\n    try {\\n      parsed = JSON.parse(q[\\"Câu hỏi\\"]);\\n    } catch (err) {\\n      parsed = {\\n        question: \\"❌ Lỗi phân tích 'Câu hỏi'\\",\\n        raw: q[\\"Câu hỏi\\"]\\n      };\\n    }\\n\\n    // Nếu thiếu imageUrl thì thêm từ \\"Link Image\\"\\n    if (!parsed.imageUrl && q[\\"Link Image\\"]) {\\n      parsed.imageUrl = q[\\"Link Image\\"];\\n    }\\n\\n    return parsed;\\n  });\\n\\n  // Tiêu đề đề thi\\n  const title = chuDe.trim()\\n    ? `Bài kiểm tra Môn học: ${monHoc} với ${chuDe} - ${lop}\\\\nCấp độ: ${targetLevel}\\\\nĐề thi số: ${deThiSo}`\\n    : `Bài kiểm tra Môn học: ${monHoc} - ${lop}\\\\nCấp độ: ${targetLevel}\\\\nĐề thi số: ${deThiSo}`;\\n\\n  // Push kết quả ra output\\n  output.push({\\n    json: {\\n      title,\\n      questions,\\n      \\"Môn học\\": monHoc,\\n      \\"Chủ đề\\": chuDe,\\n      \\"Lớp\\": lop,\\n      \\"Cấp độ\\": targetLevel,\\n      \\"Số lượng câu hỏi\\": soLuongCauHoi,\\n      \\"Số bài Quiz cần tạo\\": soDe,\\n      \\"Đề thi số\\": deThiSo\\n    }\\n  });\\n}\\n\\nreturn output;\\n"},"id":"c16b952a-dd6e-44d0-85fa-2c6ea75e4dd6","name":"Tạo câu hỏi ngẫu nhiên cho  bài Quiz","type":"n8n-nodes-base.code","typeVersion":2,"position":[816,1024]},{"parameters":{"documentId":{"__rl":true,"value":"1Qg0bYNfFaKjI5xYLTYaODJvmJSjMPQYON2C27boHY7s","mode":"id"},"sheetName":{"__rl":true,"value":"Data","mode":"name"},"filtersUI":{"values":[{"lookupColumn":"Lớp","lookupValue":"={{ $json['Lớp'] }}"},{"lookupColumn":"Môn học","lookupValue":"={{ $json['Môn học'] }}"},{"lookupColumn":"Cấp độ","lookupValue":"={{ $json['Cấp độ'] }}"}]},"options":{}},"type":"n8n-nodes-base.googleSheets","typeVersion":4.6,"position":[448,1088],"id":"b2019d4a-1d63-42dc-a82b-58e7f9263f07","name":"Lấy STT Đề Thi","alwaysOutputData":true,"retryO