ng tin đầu vào từ node Merge\\nconst inputInfo = $('Loop Over Items').first().json;\\nconst monhoc = inputInfo[\\"Môn học\\"] || \\"\\";\\nconst chude = inputInfo[\\"Chủ đề\\"] || \\"\\";\\nconst lop = inputInfo[\\"Lớp\\"] || \\"\\";\\nconst soluongcauhoi = inputInfo[\\"Số lượng câu hỏi\\"] || \\"\\";\\nconst capdo = inputInfo[\\"Cấp độ\\"] || \\"\\";\\nconst sobaiquiz = inputInfo[\\"Số bài  Quiz cần tạo\\"] || \\"\\";\\nconst dethiso = inputInfo[\\"Đề thi số\\"] || \\"\\";\\n\\n// 2. Mỗi item đại diện 1 đề có title + questions\\n// Ta chỉ chọn đề đầu tiên (hoặc duyệt từng đề nếu muốn)\\nconst firstItem = items[0].json;\\nconst title = firstItem.title || \\"Bài kiểm tra mặc định\\";\\n\\n// 3. Duyệt câu hỏi trong item đầu tiên\\nconst rawQuestions = firstItem.questions || [];\\nconst questions = rawQuestions.map(q => {\\n  if (\\n    !q.question ||\\n    !Array.isArray(q.choices) ||\\n    !q.correctAnswer ||\\n    !q.Explanation\\n  ) {\\n    return null; // loại bỏ câu lỗi\\n  }\\n\\n  return {\\n    question: q.question,\\n    choices: q.choices,\\n    correctAnswer: q.correctAnswer,\\n    Explanation: q.Explanation,\\n    imageUrl: q.imageUrl || \\"\\"\\n  };\\n}).filter(Boolean); // loại bỏ null\\n\\n// 4. Kết quả trả về 1 object chuẩn hóa\\nconst finalQuiz = {\\n  title,\\n  \\"Môn học\\": monhoc,\\n  \\"Chủ đề\\": chude,\\n  \\"Lớp\\": lop,\\n  \\"Số lượng câu hỏi\\": soluongcauhoi,\\n  \\"Cấp độ\\": capdo,\\n  \\"Số bài Quiz cần tạo\\": sobaiquiz,\\n  \\"Đề thi số\\": dethiso,\\n  questions\\n};\\n\\nreturn [{ json: finalQuiz }];\\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[1216,1040],"id":"9220f4b2-a1ef-48a1-8428-3bdf8122c1af","name":"Parse JSON2"},{"parameters":{"chatId":"5584954476","text":"=CÔNG VIỆC BÀI TRẮC NGHIỆM QUIZ ĐÃ HOÀN TẤT !","additionalFields":{}},"type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[1952,992],"id":"a022d0cb-7319-4639-870b-440286f0e678","name":"Send a text message1","webhookId":"0304b6c8-985d-4aeb-9c74-e75c411f777b","credentials":{"telegramApi":{"id":"3dY6VmwOtXaErnPU","name":"Telegram account"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"id":"9d7c7705-e7e7-471a-841c-c71e2930b2ea","leftValue":"={{ $json.status }}","rightValue":"ok","operator":{"type":"string","operation":"equals","name":"filter.operator.equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.2,"position":[1296,128],"id":"7f73e4a1-b153-4ec8-8449-2480da08aa17","name":"If"},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"id":"9d7c7705-e7e7-471a-841c-c71e2930b2ea","leftValue":"={{ $json.status }}","rightValue":"ok","operator":{"type":"string","operation":"equals","name":"filter.operator.equals"}}],"combinator":"and"},"options":{}},"type":"n8n-nodes-base.if","typeVersion":2.2,"position":[1760,1008],"id":"dbbbe056-528c-4f5c-9b78-45ec9204e5e3","name":"If1"},{"parameters":{"promptType":"define","text":"={{ $json.prompt }}","hasOutputParser":true,"options":{}},"type":"@n8n/n8n-nodes-langchain.agent","typeVersion":1.7,"position":[1280,272],"id":"9b549612-e740-4e8a-a592-bbc7d7c440da","name":"Tạo câu hỏi trắc nghiệm","retryOnFail":true,"waitBetweenTries":5000},{"parameters":{"jsCode":"const mon = $input.first().json['Môn học'];\\nconst chuDe = $input.first().json['Chủ đề'];\\nconst lop = $input.first().json['Lớp'];\\nconst capDo = $input.first().json['Cấp độ'];\\nconst Xsocauhoi = 5;\\nlet prompt_TiengAnh = `Bạn là một chuyên gia giáo dục ${mon} xuất sắc và chuyên gia prompt. Nhiệm vụ của bạn là tạo ${Xsocauhoi} câu hỏi trắc nghiệm ${mon} chất lượng cao cho học sinh tiểu học. Kết quả đầu ra phải là một đối tượng JSON duy nhất và hoàn hảo, không có bất kỳ văn bản, mã markdown hoặc nội dung nào khác.\\n\\n1. CONTEXT\\nMôn học: ${mon}\\nChủ đề: ${chuDe}\\nLớp: ${lop}\\nCấp độ: ${capDo}\\n\\n2. INSTRUCTION\\nĐộ dài & Nội dung: Tạo chính xác 1 câu hỏi trắc nghiệm với 4 lựa chọn (a, b, c, d).\\n\\nPhù hợp với học sinh: Sử dụng từ vựng và ngữ pháp phù hợp với lứa tuổi ${lop} BÁM SÁT THEO chủ đề: \\"${chuDe}\\" và cấp độ: ${capDo}.\\n\\nTính chính xác: Đảm bảo chỉ có một đáp án đúng.\\n\\nTránh mơ hồ: Các câu hỏi và đáp án phải rõ ràng, không gây nhầm lẫn.\\n\\n3. JSON OUTPUT FORMAT\\nTrả về đối tượng JSON theo cấu trúc sau:\\n{\\n  \\"Môn học\\": \\"${mon}\\",\\n  \\"Chủ đề\\": \\"${chuDe}\\",\\n  \\"Lớp\\": \\"${lop}\\",\\n  \\"Cấp độ\\": \\"${capDo}\\",\\n  \\"questions\\": [\\n    {\\n    \\"question\\": \\"[Câu hỏi tiếng Anh]\\",\\n    \\"choices\\": [\\n      \\"a. [Lựa chọn a]\\",\\n      \\"b. [Lựa chọn b]\\",\\n      \\"c. [Lựa chọn c]\\",\\n      \\"d. [Lựa chọn d]\\"\\n    ],\\n    \\"correctAnswer\\": \\"[Đáp án đúng, ví dụ: 'a. ...']\\",\\n    \\"Explanation\\": \\"\\n          EN:\\n          question: [English question]\\n          a. [Lựa chọn a]: [Correct ✅ or Incorrect ❌ explanation for choice a]\\n          b. [Lựa chọn b]: [Correct ✅ or Incorrect ❌ explanation for choice b]\\n          c. [Lựa chọn c]: [Correct ✅ or Incorrect ❌ explanation for choice c]\\n          d. [Lựa chọn d]: [Correct ✅ or Incorrect ❌ explanation for choice d]\\n          \\n          VN:\\n          question: [Câu hỏi tiếng Việt]\\n          a. [Lựa chọn a]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn a]\\n          b. [Lựa chọn b]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn b]\\n          c. [Lựa chọn c]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn c]\\n         d. [Lựa chọn d]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn d].\\",\\n     \\"imagePrompt\\": \\"Hãy tạo một mô tả hình ảnh bằng tiếng Anh, rõ ràng, sinh động và có tính giáo dục, minh họa cho ý tưởng chính của câu hỏi và đáp án đúng, phù hợp với khả năng hiểu của học sinh.\\n  \\n  Nếu câu hỏi liên quan đến các khái niệm có thể minh họa trực quan (ví dụ: đồ vật, con vật, hành động, bối cảnh), hãy mô tả cảnh minh họa có đầy đủ đối tượng chính, bối cảnh phù hợp và các vật thể phụ trợ có liên quan để hỗ trợ học sinh dễ hiểu và dễ ghi nhớ.\\n  \\n  Nếu câu hỏi là “Mấy giờ rồi?”, hãy mô tả một chiếc đồng hồ rõ ràng hiển thị đúng giờ, đặt trong một bối cảnh sinh hoạt thực tế (ví dụ: lớp học, phòng ngủ buổi sáng, sân chơi giờ ra chơi...).\\n  \\n  Nếu câu hỏi là phép tính số học đơn giản (ví dụ: “3 + 1 bằng mấy?”), không được thể hiện kết quả (ví dụ: số 4). Thay vào đó, hãy minh họa bối cảnh với các đối tượng tương ứng (ví dụ: 3 quả táo + 1 quả táo), kèm theo môi trường xung quanh có màu sắc sinh động và phù hợp với học sinh.\\n  \\n  Nếu câu hỏi mang tính trừu tượng (như ngữ pháp, logic, định nghĩa), hãy trả về chuỗi rỗng \\"\\" và không tạo hình ảnh.\\n  \\n  Phong cách hình ảnh phải phù hợp với học sinh: nhiều màu sắc, thân thiện, dễ tiếp cận. Gợi ý phong cách: \\"2D cartoon illustration\\", \\"watercolor painting\\", \\"flat design\\", hoặc \\"children’s book drawing\\".\\n  \\n  Có thể kết hợp yếu tố văn hóa Việt Nam một cách tự nhiên nếu phù hợp (ví dụ: nhân vật, trang phục, bối cảnh, đồ vật,...).\\n  \\n  ➤ Chỉ trả về chuỗi mô tả ảnh, không cần định dạng đặc biệt hoặc lời giải thích.\\",\\n    \\n    \\"imageName\\": \\"Tạo chuỗi ngắn gọn, viết thường, dùng dấu - thay cho khoảng trắng, mô tả ngắn về đối tượng chính trong hình.\\"\\n    },\\n   {\\n      \\"question\\": \\"[Câu hỏi tiếp theo...]\\",\\n      \\"choices\\": [\\n        \\"a. ...\\",\\n        \\"b. ...\\",\\n        \\"c. ...\\",\\n        \\"d. ...\\"\\n      ],\\n      \\"correctAnswer\\": \\"c. ...\\",\\n      \\"Explanation\\": \\"...\\",\\n      \\"imagePrompt\\": \\"...\\",\\n      \\"imageName\\": \\"...\\"\\n    }\\n  ]\\n}\\n\\n4. IMPORTANT RULES\\nĐịnh dạng JSON: BẮT BUỘC tuân thủ chính xác định dạng JSON trên. Sử dụng dấu ngoặc kép đôi cho tất cả các khóa và giá trị.\\n\\nDuy nhất một đối tượng JSON: Không thêm bất kỳ văn bản nào trước hoặc sau đối tượng JSON.\\nCâu hỏi : tránh lặp lại nhiều lần.\\nGiải thích: Mỗi giải thích cho từng lựa chọn phải ngắn gọn, súc tích trong một câu và sử dụng icon ✅/❌ đặt phía trước.\\n\\nKiểm tra cú pháp: Tự kiểm tra lại cú pháp JSON của bạn để đảm bảo không có lỗi như thiếu dấu phẩy hoặc dấu ngoặc đóng.\\n`;\\nlet prompt_TiengViet = `Bạn là một chuyên gia giáo dục xuất sắc môn ${mon} và chuyên gia prompt tạo ảnh minh họa. Nhiệm vụ của bạn là tạo ${Xsocauhoi} câu hỏi trắc nghiệm môn ${mon} chất lượng cao cho học sinh ${lop}. Kết quả đầu ra phải là một đối tượng JSON duy nhất và hoàn hảo, không có bất kỳ văn bản, mã markdown hoặc nội dung nào khác.\\n\\n1. CONTEXT\\n  \\"Môn học\\": \\"${mon}\\"\\n  \\"Chủ đề\\": \\"${chuDe}\\"\\n  \\"Lớp\\": \\"${lop}\\"\\n  \\"Cấp độ\\": \\"${capDo}\\"\\n\\n2. INSTRUCTION\\nĐộ dài & Nội dung: Tạo chính xác 1 câu hỏi trắc nghiệm với 4 lựa chọn (a, b, c, d).\\n\\nPhù hợp với học sinh: Sử dụng từ vựng và ngữ pháp phù hợp với lứa tuổi ${lop} BÁM SÁT THEO Chủ đề: ${chuDe} và Cấp độ: ${capDo}\\n\\nTính chính xác: Đảm bảo chỉ có một đáp án đúng.\\n\\nTránh mơ hồ: Các câu hỏi và đáp án phải rõ ràng, không gây nhầm lẫn.\\n\\n3. JSON OUTPUT FORMAT\\nTrả về đối tượng JSON theo cấu trúc sau:\\n{\\n   \\"Môn học\\": \\"${mon}\\",\\n  \\"Chủ đề\\": \\"${chuDe}\\",\\n  \\"Lớp\\": \\"${lop}\\",\\n  \\"Cấp độ\\": \\"${capDo}\\",\\n  \\"questions\\": [\\n    {\\n    \\"question\\": \\"[Câu hỏi tiếng Việt]\\",\\n    \\"choices\\": [\\n      \\"a. [Lựa chọn a]\\",\\n      \\"b. [Lựa chọn b]\\",\\n      \\"c. [Lựa chọn c]\\",\\n      \\"d. [Lựa chọn d]\\"\\n    ],\\n    \\"correctAnswer\\": \\"[Đáp án đúng, ví dụ: 'a. ...']\\",\\n    \\"Explanation\\": \\"\\n          question: [Câu hỏi tiếng Việt]\\n          a. [Lựa chọn a]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn a]\\n          b. [Lựa chọn b]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn b]\\n          c. [Lựa chọn c]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn c]\\n         d. [Lựa chọn d]: [Giải thích đúng ✅ hoặc sai ❌ cho lựa chọn d].\\",\\n    \\"imagePrompt\\": \\"Hãy tạo một mô tả hình ảnh bằng tiếng Anh, rõ ràng, sinh động và có tính giáo dục, minh họa cho ý tưởng chính của câu hỏi và đáp án đúng, phù hợp với khả năng hiểu của học sinh.\\n  \\n  Nếu câu hỏi liên quan đến các khái niệm có thể minh họa trực quan (ví dụ: đồ vật, con vật, hành động, bối cảnh), hãy mô tả cảnh minh họa có đầy đủ đối tượng chính, bối cảnh phù hợp và các vật thể phụ trợ có liên quan để hỗ trợ học sinh dễ hiểu và dễ ghi nhớ.\\n  \\n  Nếu câu hỏi là “Mấy giờ rồi?”, hãy mô tả một chiếc đồng hồ rõ ràng hiển thị đúng giờ, đặt trong một bối cảnh sinh hoạt thực tế (ví dụ: lớp học, phòng ngủ buổi sáng, sân chơi giờ ra chơi...).\\n  \\n  Nếu câu hỏi là phép tính số học đơn giản (ví dụ: “3 + 1 bằng mấy?”), không được thể hiện kết quả (ví dụ: số 4). Thay vào đó, hãy minh họa bối cảnh với các đối tượng tương ứng (ví dụ: 3 quả táo + 1 quả táo), kèm theo môi trường xung quanh có màu sắc sinh động và phù hợp với học sinh.\\n  \\n  Nếu câu hỏi mang tính trừu tượng (như ngữ pháp, logic, định nghĩa), hãy trả về chuỗi rỗng \\"\\" và không tạo hình ảnh.\\n  \\n  Phong cách hình ảnh phải phù hợp với học sinh: nhiều màu sắc, thân thiện, dễ tiếp cận. Gợi ý phong cách: \\"2D cartoon illustration\\", \\"watercolor painting\\", \\"flat design\\", hoặc \\"children’s book drawing\\".\\n  \\n  Có thể kết hợp yếu tố văn hóa Việt Nam một cách tự nhiên nếu phù hợp (ví dụ: nhân vật, trang phục, bối cảnh, đồ vật,...).\\n  \\n  ➤ Chỉ trả về chuỗi mô tả ảnh, không cần định dạng đặc biệt hoặc lời giải thích.\\",\\n    \\n    \\"imageName\\": \\"Tạo chuỗi ngắn gọn, viết thường, dùng dấu - thay cho khoảng trắng, mô tả ngắn về đối tượng chính trong hình.\\"\\n    },\\n   {\\n      \\"question\\": \\"[Câu hỏi tiếp theo...]\\",\\n      \\"choices\\": [\\n        \\"a. ...\\",\\n        \\"b. ...\\",\\n        \\"c. ...\\",\\n        \\"d. ...\\"\\n      ],\\n      \\"correctAnswer\\": \\"c. ...\\",\\n      \\"Explanation\\": \\"...\\",\\n      \\"imagePrompt\\": \\"...\\",\\n      \\"imageName\\": \\"...\\"\\n    }\\n  ]\\n}\\n\\n4. IMPORTANT RULES\\nĐịnh dạng JSON: BẮT BUỘC tuân thủ chính xác định dạng JSON trên. Sử dụng dấu ngoặc kép đôi cho tất cả các khóa và giá trị.\\n\\nDuy nhất một đối tượng JSON: Không thêm bất kỳ văn bản nào trước hoặc sau đối tượng JSON.\\n\\nCâu hỏi : tránh lặp lại nhiều lần.\\n\\nGiải thích: Mỗi giải thích cho từng lựa chọn phải ngắn gọn, súc tích trong một câu và sử dụng icon ✅/❌ đặt phía trước.\\n\\nKiểm tra cú pháp: Tự kiểm tra lại cú pháp JSON của bạn để đảm bảo không có lỗi như thiếu dấu phẩy hoặc dấu ngoặc đóng.\\n`;\\nlet prompt_Toan = `Bạn là một chuyên gia giáo dục xuất sắc môn ${mon} và chuyên gia prompt tạo ảnh minh họa. Nhiệm vụ của bạn là tạo ${Xsocauhoi} câu hỏi trắc nghiệm ${mon} chất lượng cao cho học sinh ${lop}. Kết quả đầu ra phải là một đối tượng JSON duy nhất và hoàn hảo, không có bất kỳ văn bản, mã markdown hoặc nội dung nào khác.\\n\\n1. CONTEXT\\n  \\"Môn học\\": \\"${mon}\\"\\n  \\"Chủ đề\\": \\"${chuDe}\\"\\n  \\"Lớp\\": \\"${lop}\\"\\n  \\"Cấp độ\\": \\"${capDo}\\"\\n\\n2. INSTRUCTION\\nĐộ dài & Nội dung: Tạo chính xác 1 câu hỏi trắc nghiệm với 4 lựa chọn (a, b, c, d).\\n\\nPhù hợp với học sinh: Sử dụng từ vựng và ngữ pháp phù hợp với lứa tuổi ${lop} BÁM SÁT THEO Chủ đề: ${chuDe} và Cấp độ: ${capDo}\\n\\nTính chính xác: Đảm bảo chỉ có một đáp án đúng.\\n\\nTránh mơ hồ: Các câu hỏi và đáp án phải rõ ràng, không gây nhầm lẫn.\\n\\n3. JSON OUTPUT FORMAT\\nTrả về đối tượng JSON theo cấu trúc sau:\\n{\\n  \\"Môn học\\": \\"${mon}\\",\\n  \\"Chủ đề\\": \\"${chuDe}\\",\\n  \\"Lớp\\": \\"${lop}\\",\\n  \\"Cấp độ\\": \\"${capDo}\\",\\n  \\"questions\\": [\\n    {\\n    \\"question\\": \\"[Câu hỏi tiếng Việt]\\",\\n    \\"choices\\": [\\n      \\"a. [Lựa chọn a]\\",\\n      \\"b. [Lựa chọn b]\\",\\n      \\"c. [Lựa chọn c]\\",\\n      \\"d. [Lựa chọn d]\\"\\n    ],\\n    \\"correctAnswer\\": \\"[Đáp án đúng, ví dụ: 'a. ...']\\",\\n    \\"Explanation\\": \\"\\n          question: [Câu hỏi tiếng Việt]\\n     